/* 令和2年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r02.committeeSessions.push(...[{"id":"r02-20200313-3","meetingId":"r02-c-budget","date":"2020年3月13日","dateIso":"2020-03-13","committee":"予算特別委員会","time":"午前１０時００分～午後 ５時５５分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を172件整理しています。","topics":[{"id":"topic-01","title":"第５号議案、令和２年度品川区一般会計予算","agenda":"第５号議案、令和２年度品川区一般会計予算","exchanges":[{"speaker":"本多委員","kind":"質問","question":"厳密には今日で１０日だと思いますけれども、子ども、児童・生徒が家にいる。質問は、そのことに関して、品川区教育委員会の模索についてどうだったのかを説明を求めました。","respondent":"有馬庶務課長","answer":"学校が休業になるということは、まさしく突然のことでして、学校も対応に追われたということがございました。発表があった翌日の３月２日の午前中には生徒に来ていただいて、卒業式はぜひやっていきたいなど、さまざまなことをこれまで検討してきたです。","id":"exchange-001"},{"speaker":"本多委員","kind":"質問・要望","question":"子どもの活動の場所、校庭ということで、このような方針は本当に理解しております。思う存分、活動してほしいと求めましたが、その点についていかがか尋ねました。","respondent":"有馬庶務課長","answer":"１つは、子どもたちも１週間、なかなか自宅に閉じこもって、勉強と言っていても限界もあるだろうということ。午前中の自学自習というところは残して、午後の３時間というふうにしましたので、短い時間なので精いっぱい遊んでもらおうと考えているところです。","id":"exchange-002"},{"speaker":"本多委員","kind":"質問・要望","question":"日にちを数えると７日間になりますけれども、協力が得られるように、その辺の働きかけというのをお願いしたいと思うのです。これは、対象は校庭だけの部活なのか、その辺を説明を求めました。","respondent":"有馬庶務課長","answer":"それから部活動につきましては、基本的には全ての部活動ということで考えております。いわゆる室内のほうも、密集しないように注意しながらということで、飲食はしないようになど一定の条件をつけて行っていくという考えです。","id":"exchange-003"},{"speaker":"本多委員","kind":"質問","question":"発表になった瞬時の子どもたちの、部活動ができると喜ぶ瞬間は、もう想像するだけでも本当に胸が膨らむ思いです。した後などに、いろいろな意見が出るかもしれませんが、その辺のところはどういうふうに対応するのか説明を求めました。","respondent":"有馬庶務課長","answer":"対外試合はやらないといった上に、強制参加はさせないというところが、もう一つポイントになってくるかと思います。これは、家庭の判断で、行かせる、行かせないということは当然出てくると思いますので、そこまでしっかり配慮していきたいと考えているところです。","id":"exchange-004"},{"speaker":"本多委員","kind":"質問","question":"それで、飲み物につきまして、何か指導というか、柔軟な工夫というか、その辺があれば教えてください。今、物がなければそれまでなのですが、何かちょっとでも工夫などできないものか説明を求めました。","respondent":"有馬庶務課長","answer":"うがいや、水を飲んだりというのもあると思いますので、そういったところは可としていきたいと思います。今、場合によってはマスクを着用して子どもたちは遊んでもいいですよだとか、その辺のところも検討しながら進めていきたいと思っているところです。","id":"exchange-005"},{"speaker":"本多委員","kind":"質問・要望","question":"ぜひ、できる限りのことをやってほしいと求めましたが、最後に伺いたいのは、この教育委員会の判断につきましては、我が会派も支持しています。その意気込みを説明を求めました。","respondent":"有馬庶務課長","answer":"しっかり子どもたちの生活のリズムをつくってあげること、それから何より健康を守っていくということも大事だと考えています。安全にこの事業を進めていって、４月以降につきましては平常な学校生活を送れるように、何とか頑張っていきたいと思っているところです。","id":"exchange-006"},{"speaker":"せお委員","kind":"質問","question":"３６７ページ、お時間がありましたら３６９ページ、順不同でお聞きします。１点だけ、例えば自閉傾向の強いお子さんなどは、そのようなお子さんへの対応はどのようになっておりますか尋ねました。","respondent":"大関教育総合支援センター長","answer":"臨時休業期間中も個別の対応は各校でしていただいているところです。平均して１校当たり１日１０名程度は、個別に子どものほうから相談に来るケースがあると、今、把握しています。","id":"exchange-007"},{"speaker":"せお委員","kind":"質問・要望","question":"国は昨年２月に、医療的ケアを実施する際に留意すべき点等について整理したと書いています。一般質問の繰り返しになりますが、品川区はこの研修の受講を積極的に支援してほしいと求めましたが、見解をもう一度説明を求めました。","respondent":"大関教育総合支援センター長","answer":"実際に４０人の児童・生徒等を担任している教員が、４０人分の連絡帳を書きながら、非常にハードルが高いのが今の現実だと品川区では考えております。","id":"exchange-008"},{"speaker":"せお委員","kind":"質問・要望","question":"現状を考えて、特別支援学級のお友達は、できれば１日１回は交流する取り組みを積極的に行ってほしいと求めました。一般質問のご答弁で、「交流機会等を充実してまいります」とありましたが、具体的にはどのように交流を充実していくのか、説明を求めました。","respondent":"大関教育総合支援センター長","answer":"特別支援学校を含めた交流も、あるいは作品展示を浅間台小学校と品川特別支援学校がやったり、特別支援学級のお子さんは。個別の対応はどんどん進めていきたいと考えております。","id":"exchange-009"},{"speaker":"せお委員","kind":"質問・要望","question":"さらに、特別支援学級には、さいかち学級という、昭和大学病院に入院している児童へさまざまな学習を行っている学級が、昭和大学病院内にあります。質問したいのが、さいかち学級に通う制度はないのでしょうかということと、２点説明を求めました。","respondent":"大関教育総合支援センター長","answer":"さいかち学級は、清水台小学校の特別支援学級の一つとして、教室が昭和大学病院の１６階にあるという位置づけです。昭和大学病院入院中のお子さんについては、１日大体６名、７名程度の教育相談には対応しています。","id":"exchange-010"},{"speaker":"せお委員","kind":"質問・要望","question":"さいかち学級というとてもよい取り組みがあるので、上手に活用していただいて、子どもたちとご家族に最善を尽くしていただきたいと思っています。このような活用方法も大切かと思いますが、特別支援学級でのＩＣＴ活用について見解を説明を求めました。","respondent":"大関教育総合支援センター長","answer":"ＯｒｉＨｉｍｅというロボットを使って小学校の教室の理科の時間に一緒に参加したケースなどもありますので、在籍校側との連携が可能な内容については柔軟に対応できるよう、今後とも情報を集めてまいりたいと思います。","id":"exchange-011"},{"speaker":"せお委員","kind":"質問","question":"現在は学習方法も多様化してきているので、そのお子さんに合った学習方法など、教師全員が意見を出し合ったりして考えていってほしいと思っています。現時点で２点、考えられるかとは思うのですが、現在、庶務課で何か考えている、そして現在行っている対策などがありましたら説明を求めました。","respondent":"有馬庶務課長","answer":"人工芝の破片が、要するに、ごみとなっているということは認識しています。特に海洋汚染につながっているということもあるということを認識して、また一層、取り組みとして入れていきたいと思っています。","id":"exchange-012"},{"speaker":"つる委員","kind":"質問・要望","question":"３月３日の補正予算の審査のときにも対策を求めておりましたけれども、あくまでも大前提は感染させないという中で、お願いしたいと思います。こうしたものが、学校のそうした対応の中でも見られるようにしていくのかどうか、それを確認させてください。","respondent":"大関教育総合支援センター長","answer":"４０台あるタブレットＰＣの活用ですが、対応した教員の判断で、どうしても学習のためにここを調べたりという部分は対応が十分可能です。なお、学校図書館につきましても、今、開設している中で可能な範囲で、対応は工夫できるものかと考えております。","id":"exchange-013"},{"speaker":"つる委員","kind":"質問・要望","question":"これからの時代に求められる能力をつけていく上でも、こういう機会だからこそ、読書の活用を推進ほしいと求めました。一般質問でも確認させていただきましたが、それから学校図書館への展開等について、ご見解をお知らせください。","respondent":"横山品川図書館長","answer":"タイトル数はまだ１９と少ないのですが、これから、ティーンズ世代への活用を含め、拡充していく予定です。各学校図書館についても幾つかの書籍は備えているという状況でございまして、これから拡充していくようになってあります。","id":"exchange-014"},{"speaker":"つる委員","kind":"質問・要望","question":"先ほど、学校の臨時対応のところを１点だけ確認し忘れてしまったのですが、文部科学省からＱ＆Ａが出ているかと思うのです。いろいろな質問の中で、これの遊び方や活用の仕方については、どのような指導になっているのか説明を求めました。","respondent":"有馬庶務課長","answer":"実際に子どもたちがどれくらい集まるか。それは、様子を見ながら、そのときそのときに判断していくということが、実際の対応になってくると考えております。","id":"exchange-015"},{"speaker":"つる委員","kind":"質問・要望","question":"そういったときに、うちにもかかってきましたけれども、学校の先生が保護者に対して、お子さんの様子はどうですかという電話がかかってきた。学校の先生たちはどういうご努力をしていただいているのかというのが、そういう、わかる範囲で説明を求めました。","respondent":"大関教育総合支援センター長","answer":"そうすると、「明日相談に行きたいから、行くね」などという子がいて、個別対応をしているという報告を受けている学校もあります。何時でもいいからおいで」などという対応をしていたり、登校渋りのあったお子さんのところには家庭訪問をしたりという報告も聞いております。","id":"exchange-016"},{"speaker":"つる委員","kind":"質問・要望","question":"これだけすごい技術を持っていても、ドラえもんは学校には行かないという。感染拡大を防止しながら、子どもたちの健全な成長のために、これからも一生懸命頑張ってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"おくの委員","kind":"質問","question":"こういうことで、私としては、ご答弁に対して３つほど、お伺いしたいことがあります。いかがか尋ねました。","respondent":"工藤指導課長","answer":"今回のところにおきましては、さらにそれを配分するというもの、いわゆる勤務時間を長くするものではないと認識しています。ですから、やはり教員の健康の保持をするという目的で改正されているという認識ですので、それを進めていきたいと考えておるところです。","id":"exchange-018"},{"speaker":"おくの委員","kind":"質問","question":"時間がないので、第三の質問に移ります。養成研修、学校閉庁日等の休暇を取得しやすい期間を設けるなどによって、休日のまとめ取りができるのではないかと言うことができると思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"筒井委員","kind":"質問","question":"時間があれば、３６２ページ、図書館費についてお伺いいたします。改めて、中島教育長の代でコミュニティ・スクールを導入した理由と、品川区の特色は何か尋ねました。","respondent":"工藤指導課長","answer":"その地域にある学校、そこで行っている教育活動を含め、そういったものが持続可能になるシステムであると認識しています。やはり地域総がかりで、その地域にある学校の子どもたちを成長させていく、育てていこうという仕組みであると認識しています。","id":"exchange-020"},{"speaker":"筒井委員","kind":"質問","question":"私が聞きたかったのは、導入した理由は何でしょうかということだったのですけれども、その理由を簡単に。","respondent":"工藤指導課長","answer":"学校だけで学校を運営するのではなく、持続可能にするという点です。","id":"exchange-021"},{"speaker":"筒井委員","kind":"質問","question":"それで、貝ノ瀬教育長のお話と、私が質問する中で、そこで課題は何ですかという話になりまして、課題が２つ挙げられました。形骸化の防ぎ方と、保護者以外の地域住民への浸透の仕方について、どのように品川区はお考えなのか尋ねました。","respondent":"工藤指導課長","answer":"コミュニティ・スクールの取り組みを、通信を発行するなどもしていますけれども、さまざまなところで周知を図っていきたいと考えておるところです。","id":"exchange-022"},{"speaker":"筒井委員","kind":"質問・要望","question":"２０１６年に日本建築学会賞も取られたほどのすばらしい場所でしたけれども、今、サードプレイスということも出ております。さらによいものにしていっていただきたいと思っていますけれども、意気込み、そのあたりのお考えはいかがか尋ねました。","respondent":"横山品川図書館長","answer":"誰にでも開かれた身近な居場所としての図書館づくりということを、今回の長期基本計画でも図書館の方針として挙げしています。品川区のほかの文化センターや児童センター等と協力して、複合的にサービスを提供できるように努めてまいりたいと考えています。","id":"exchange-023"},{"speaker":"田中委員","kind":"確認","question":"３６７ページ、２項学校教育費、時間があればＰＣＢ廃棄物調査経費を伺います。東京都教育委員会は、確認書については、通知として送ったと言います。","respondent":"大関教育総合支援センター長","answer":"令和２年度より特別支援教室を継続利用する方も含めまして、その趣旨も説明して、適切な対応をするように伝えたところです。今後とも、校長連絡会あるいは特別支援教育コーディネーター連絡会を通じまして、各校に周知・徹底してまいりたいと考えています。","id":"exchange-024"},{"speaker":"田中委員","kind":"確認","question":"東京都教育委員会が送った確認書が、通知として送られたものが、都の規定となって保護者の手に渡ったことについて、今ご説明がなかったので、お願いします。","respondent":"大関教育総合支援センター長","answer":"特別支援教室に関する確認書冒頭の１行目が、特別支援教室は学校教育法施行規則第１４０条に規定されている云々という文章になっております。今回のような多少の行き違いがあった部分は、またそういうことのないように留意してまいりたいと考えております。","id":"exchange-025"},{"speaker":"田中委員","kind":"確認","question":"東京都は、確認書はあくまで案であり、子どもと保護者が十分に理解・納得する話し合いの場を設けるための１つの道具として通知したとしています。もしそうだとしたら、そのような区としての説明も必要だったと思いますが、区の見解を伺います。","respondent":"大関教育総合支援センター長","answer":"特別支援教室の利用は、例えば発達検査などもさせていただいた上で、その結果に基づいて丁寧なご説明もした上で。一部誤解があったことかと推測しますので、そういったこともないように、より丁寧な説明を続けてまいりたいと思います。","id":"exchange-026"},{"speaker":"田中委員","kind":"質問","question":"区の見解を伺います。子どもと保護者に与える影響についても、どのように想定したのか伺います。","respondent":"有馬庶務課長","answer":"それを踏まえて品川区でどう対応するかということですけれども、まず子どもの健康を第一に考える必要があるだろうというのが１点。３月という時期ですので、卒業生を送る会というイベントもどうするかとか、そういったところの対応に判断も出していたという状況です。","id":"exchange-027"},{"speaker":"田中委員","kind":"確認","question":"その中で確認させてください。司書の配置などについても確認させてください。","respondent":"有馬庶務課長、横山品川図書館長","answer":"休校に対する保護者への対応のところで補足させていただきたいと思いますけれども、このように対応いたします、保護者にもしっかり対応というか。あるいは濃厚接触者が誰かわからなくて… 今回の休校の間の学校図書館対応ですが、こちらにつきましては、スタッフを派遣している週１５時間については確保しています。","id":"exchange-028"},{"speaker":"田中委員","kind":"質問・要望","question":"品川・生活者ネットワークは学校図書館司書の週５日配置を求めましたが、学校司書の配置増については言及しませんでした。委員からも、現在の２.５日より配置を増やしてほしいという声が多く聞かれましたが、現在の司書配置についての検討状況についてお知らせください。","respondent":"横山品川図書館長","answer":"委員ご指摘のとおり、学校図書館の重要性に言及していただきまして、さらに充実するべしというご意見をたくさんいただいております。","id":"exchange-029"},{"speaker":"田中委員","kind":"質問・要望","question":"児童・生徒・教員が授業に活用できる学校図書館として求められるのは、学習センター、情報センターとしての役割を果たすことができる図書館です。司書の研修センター設置についてはどのような検討がされているのか伺います。","respondent":"横山品川図書館長","answer":"研修を受けまして経験や資格を持った方にお勤めいただきたいという形で、契約の中で依頼させていただいているような状況です。これからも、その形を進めながら調整してまいるような方針です。","id":"exchange-030"},{"speaker":"田中委員","kind":"質問・要望","question":"そのような有能な司書が育つにも研修が重要と考えておりますので、もう一度見解を伺いたいと思います。区の推進計画を進めるためにも前向きに検討を進めてほしいと要望しますが、いかがか尋ねました。","respondent":"横山品川図書館長","answer":"ただいまの研修の実施につきましては、共同で進める形で区もかかわっていきたいと考えています。そのお子さんたちに対応した形で寄り添っていきたいというのが、それを図書館でも推進していきたいと考えています。","id":"exchange-031"},{"speaker":"田中委員","kind":"質問・要望","question":"牛乳パック回収経費について伺います。しかし、どういう形で活用されるリサイクルになっているのか、そこまで求めた仕様書となっているのかお知らせください。","respondent":"篠田学務課長","answer":"そういう形では整理しています。その先につきましては、区としてどういう形でという業務を指示しているものではございません。","id":"exchange-032"},{"speaker":"田中委員","kind":"確認","question":"では、どのようなリサイクル処理がされるということは確認できないということですか。ちょっとその辺についてお知らせください。","respondent":"篠田学務課長","answer":"基本的に牛乳パック等は、一般的には再生紙等に利用されていますけれども、その利用先については、こちらで指定する形にはなっていないです。","id":"exchange-033"},{"speaker":"松本委員","kind":"質問・要望","question":"あるいは社会的自立も併置していただきたいという要望は、ここは改めて見解を伺わないのですけれど、せめてウェブサイトの記載なのです。こちらのウェブサイトの記載も、学校復帰と社会的自立をぜひとも併置してほしいと求めましたが、いかがか尋ねました。","respondent":"大関教育総合支援センター長","answer":"中には、不登校児童・生徒への支援に対する基本的な考え方として。生徒あるいは保護者から相談があったときには丁寧な説明をしてまいりたいと思いますが、そこは子どもたちのために丁寧に対応は進めてまいります。","id":"exchange-034"},{"speaker":"松本委員","kind":"質問","question":"伺いたいのですけれども、要因別のところにも、特に挙がっていないかと思います。お伺いしたいのですけれども、そこまでは把握されていないという理解でよろしいのか尋ねました。","respondent":"大関教育総合支援センター長","answer":"今度はＩＣＤ－１１になりますが、翻訳中ですけれども、そちらには正式に精神疾患の部類の一つと位置づけられたところです。そういった部分も含めて丁寧に対応はしてまいります。","id":"exchange-035"},{"speaker":"松本委員","kind":"確認","question":"一応、確認ですけれども、この要因の中には今のところ、直接の原因としてゲームやネットというのはないという理解でよろしいでしょうか。ここだけお願いいたします。","respondent":"大関教育総合支援センター長","answer":"そういう調査項目として挙げていないという段階です。","id":"exchange-036"},{"speaker":"松本委員","kind":"確認","question":"政府答弁というか、質問主意書を出したところで、ネットやゲームの依存症とプレー時間の規定との関係は、科学的な根拠は特に確認できていないというところは政府も言っているところですので、ぜひここはご理解ほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"西村委員","kind":"質問","question":"校庭利用は、すまいるスクールにいる子どもたちとの兼ね合いはどうなるでしょうか。１２時半から１５時半は一緒に利用できるのか尋ねました。","respondent":"有馬庶務課長","answer":"それで、時間の調整は、この時間は基本的には、すまいるスクールは、体育館と多目的室とを使うということを原則としております。当日の人数等によって、一緒に遊ぶということも場合によってはあるだろうということにしています。","id":"exchange-038"},{"speaker":"西村委員","kind":"質問","question":"３６１ページ、３６７ページ、順不同で伺います。ＧＩＧＡスクール構想についての区の考え方を伺ってまいります。","respondent":"篠田学務課長","answer":"それ以外の学校につきましては、現状は１クラス分、４０台、各学校に設置してございまして、順番に使っていただく。１人１台というのは考えられる状況ではありますけれども、各学校、必要なときに使えるような体制をとっていくということを考えているところです。","id":"exchange-039"},{"speaker":"西村委員","kind":"意見","question":"１人１台、１人１台パソコンが配付されると、個に応じた支援の形が変わってくることが期待されています。区は、先んじて行ってきたＩＣＴ活用推進校の取り組みがありますので、現状や子どもたちの学びの変化を改めて説明を求めました。","respondent":"篠田学務課長","answer":"ＩＣＴ活用推進校は、例えば宿題など、それぞれ各クラス担任などの考え方によって有効に活用していただいているという状況があります。それぞれの授業の中で、今後、そういったものをさらに伸ばしていけるように対応してまいりたいと考えております。","id":"exchange-040"},{"speaker":"西村委員","kind":"質問","question":"特別支援教育に関しては、どのような授業・取り組みが可能になっているのでしょうか。今後どのような可能性が広がっていくのか説明を求めました。","respondent":"大関教育総合支援センター長","answer":"特別支援学級・特別支援教室には、別の形でｉＰａｄを、子ども２人に対して１台程度の台数を配置しています。自分たちで説明のアニメーションのようなものをつくって、発表会に向けて準備をしているなどという授業も、私は見てまいりました。","id":"exchange-041"},{"speaker":"西村委員","kind":"質問","question":"続きまして、定期的に学校に来られる相談員の方について伺いたいと思います。現在どのような専門家がいらっしゃるのか、改めて伺います。","respondent":"大関教育総合支援センター長","answer":"さらに特別支援教育に関する見識のある者を１０名ほど、特別支援教育係から、実際に子どもたちの様子を見ている。学期に１回程度ですが、これは大学教授クラスも含めまして、必要な課題に応じた特別支援教育に関連する専門家を派遣したりもしています。","id":"exchange-042"},{"speaker":"西村委員","kind":"意見","question":"専門家に相談しやすい環境でありがたいと、声が届いておりましたので、お伝えします。続きまして、知能発達検査業務委託について、改めてどのようなものか、説明を求めました。","respondent":"大関教育総合支援センター長","answer":"入学前の段階ですと田中ビネー式、そして入学後のお子さんですとＷＩＳＣを、一般的なものとして活用しています。年間３００件を超える内容を、資格を持っているカウンセラーが実施して、データを保護者に対してフィードバックさせていただいているところです。","id":"exchange-043"},{"speaker":"西村委員","kind":"質問","question":"クラスの気になるお子さんに対して、教職員全体とすまいるスクールの担当者が一緒に情報共有する時間がとられていると伺ったことがあります。これは全小学校で行われているものなのか尋ねました。","respondent":"大関教育総合支援センター長","answer":"学校の立場からということでの回答となりますが、校長とすまいるスクールの担当者との間で定期的に情報共有はしています。なお、とてもナイーブな個人情報が含まれますので、保護者の同意があった上での情報共有は可能だと考えております。","id":"exchange-044"},{"speaker":"西村委員","kind":"質問","question":"そこから、家庭教育支援、学校・家庭・地域の連携協力について伺います。家庭との連動で取り組んでいることなどがございましたら、説明を求めました。","respondent":"有馬庶務課長","answer":"家庭教育力の支援ということでございまして、子育てのヒントとなるように、これは各保護者に配っているというようなことで支援しています。それから、そういったところにも支援しているというのが実態ですので、こういったことは引き続き行ってまいりたいと考えております。","id":"exchange-045"},{"speaker":"西村委員","kind":"意見","question":"家庭の教育力の低下の理由は、子どもに対して過保護、甘やかし過ぎや過干渉な親の増加が最も多いとも書かれておりました。区のご見解、お感じになっているところなどありましたら説明を求めました。","respondent":"工藤指導課長","answer":"現在お子さんが通っている学校に満足しているという質問にも、９２％と非常に高い評価をいただいています。これらの結果から、家庭の協力というのも、学校教育を進める上ではいただいているところで把握しています。","id":"exchange-046"},{"speaker":"西村委員","kind":"質問","question":"この点に関してはいかがでしょうか。説明を求めました。","respondent":"工藤指導課長","answer":"そういう意味では今後、学校・家庭・地域が協働し、地域総がかりで児童・生徒を育成していくことがますます重要になっていくと認識しています。","id":"exchange-047"},{"speaker":"西村委員","kind":"質問","question":"最後になりますが、子どもの体力について伺ってまいりたいと思います。ニュースでも新聞でもたびたび書かれておりますが、体力の低下傾向が言われておりますけれども、区の取り組み、現状を改めて説明を求めました。","respondent":"大関教育総合支援センター長","answer":"体力は低下が叫ばれている中学生も含めまして、本区においては徐々に上がってきている状況があります。アクティブライフプロジェクトとして体力向上プロジェクトを進めてきたところ、東京都内の中では品川区は上がってきているという実情です。","id":"exchange-048"},{"speaker":"西村委員","kind":"質問・要望","question":"これからも、静の活動と動の活動とバランスよく、子どもたちの豊かな心を育んでほしいと求めました。１点だけ、子どもたちの姿勢も気になっておりまして、筋力がつけば姿勢も整っていくと思いますので、どうぞ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"},{"speaker":"松澤委員","kind":"質問","question":"３６７ページ、そして３７１ページ、順不同にて質問いたします。８３運動の経費の使い道の説明をお願いいたします。","respondent":"有馬庶務課長","answer":"８３運動を進める上での推進委員会と協議いたしまして、今年度はピンバッジみたいなものを作成する予定で、つくっています。来年度はパトロールベストをつくっていこうかという経費で計上しているものです。","id":"exchange-050"},{"speaker":"松澤委員","kind":"質問","question":"啓発グッズということがわかりました。この８３運動というのは、小学校の登下校である８時と３時に沿って、８３運動の理念として合っていますか尋ねました。","respondent":"有馬庶務課長","answer":"８３運動は、８時と３時に、大人も用事をしながら地域で子どもを見守りましょうというのがきっかけでスタートしております。８時と３時に限らず、運動が広がっているというか、そういったところの時間で活動しています。","id":"exchange-051"},{"speaker":"松澤委員","kind":"質問","question":"８３運動というものは、もう学校の枠というのですか、理念として合っているのではないかと私は思っております。そういうところで、地域の見守り、８３運動についてのご見解を説明を求めました。","respondent":"有馬庶務課長","answer":"この運動の主体は、あくまでも小学校ＰＴＡ連合会というか、８３運動推進委員会が中心になって、小学校のＰＴＡに働きかけているものです。","id":"exchange-052"},{"speaker":"松澤委員","kind":"質問・要望","question":"この８３運動というのは品川区発祥とお聞きしておりまして、しっかりと要望いたしまして、次の質問に移らせていただきます。先ほど、無線ＬＡＮは全校に設置するというお話がありましたので、無線ＬＡＮが全てにつながったかどうか、確認だけさせてください。","respondent":"篠田学務課長","answer":"無線ＬＡＮの工事につきましては、今年度をもちまして全ての学校で終了するということで、一番最後の学校が、今ちょうど春休みの時期にかかるところで最後の詰めをしていますけれど、今年度中には全て終わる予定です。","id":"exchange-053"},{"speaker":"松澤委員","kind":"質問","question":"こういったオンライン教室は海外では当たり前で、今後、インフルエンザによる学級閉鎖という場合にも対応が可能になるはずであります。品川区の教育においてのリモート学習をどのように捉えていますか尋ねました。","respondent":"篠田学務課長","answer":"ＩＣＴ活用推進校の場合は１人１台、配付していますので、セキュリティーの観点からネットワークにはつなげないような状況になってあります。そういう可能性はあろうかと思いますけれども、現状は学校外ではつながりませんので、リモートラーニング等はできないという状況です。","id":"exchange-054"},{"speaker":"松澤委員","kind":"質問","question":"聞きましたら、品川区は早くからＩＣＴを取り入れているとお聞きました。在宅で学べる環境をつくるべきと考えますが、区教育委員会の考えを説明を求めました。","respondent":"篠田学務課長","answer":"こちらは、ＧＩＧＡスクールと言っているものですので、校内通信ネットワークの１ＧＢに対応した設備を入れなさいというのが大前提となっています。将来的に見れば、１人１台というのは、いずれかの時点で判断していくことが必要になってくるものだとは考えているところです。","id":"exchange-055"},{"speaker":"松澤委員","kind":"質問・要望","question":"学習にばらつきが出ないよう、学習環境の整備を要望し、次の質問へ移ります。要は地域にある防犯カメラとは管轄が違うと思いますが、教育委員会で、通学において危険と思われるような箇所は把握しておりますか尋ねました。","respondent":"有馬庶務課長","answer":"まず通学路の安全点検というのを行っておりまして、そこで危険なところというのは、まず確認しているというのがあります。各学校、４、５台ずつは防犯カメラを設置しているというものです。","id":"exchange-056"},{"speaker":"松澤委員","kind":"質問・要望","question":"荏原第五地域センターの裏にあります住吉踏切は、車が１台ぎりぎり通れて、歩行者がすれ違うのは大変困難な場所であります。そういった危険な場所に優先的に防犯カメラをつけてほしいと求めましたが、どうか尋ねました。","respondent":"有馬庶務課長","answer":"令和元年度、４５台ほど追加で設置している実態があります。今後についてもまた見ていきたいと思います。","id":"exchange-057"},{"speaker":"あくつ委員","kind":"質問","question":"３６９ページ、学校環境整備事業、防災目的の避難路確保について伺います。結構早い段階で、これは４月分に充当しますというお知らせが幾つかの学校で出ているようですけれども、ここの考え方との整合性も説明を求めました。","respondent":"篠田学務課長","answer":"今回、区としては給食費に関しては早急に対応しなければいけないということで、かなり事務的な処理をどうするかということは検討してまいりました。","id":"exchange-058"},{"speaker":"あくつ委員","kind":"質問","question":"中学校に関しては、再来年度から完全実施と聞いておるのですけれども、モデル校となるところはあるのか。そこについても説明を求めました。","respondent":"大関教育総合支援センター長","answer":"品川区内では冨士見台中学校が都の指定を受けまして、２年間の指定で、次年度は発表も含めまして、今、研究を進めているところです。１年目は、持続可能な教育というものをそれぞれの教科の中で考えて、試行錯誤をしている段階です。","id":"exchange-059"},{"speaker":"あくつ委員","kind":"質問・要望","question":"着実に品川区でも始まってくるというところで、３年前の一般質問でＳＤＧｓの教育について、このように要望させていただきました。続いて、それに関連して、給食運営費から学校給食の牛乳パックについて伺います。","respondent":"篠田学務課長","answer":"今回、ぜひそういったことを使って取り組んでいくべきであろうということを教育委員会としても考えまして、各学校にお願いをしています。ただ、どうしても無理な場合には学校で独自の判断をすることもやむを得ないだろうという形で、各学校には通達しています。","id":"exchange-060"},{"speaker":"あくつ委員","kind":"質問","question":"これだけＣＯ２の問題、温暖化が叫ばれている中で、どうするのですかということです。出入り口をつくって、１２階建ての都営住宅がありますので、万が一のときはそこに避難したらどうですかという申し出があると聞いています。","respondent":"篠田学務課長、有馬庶務課長","answer":"ストローに関しましては、一番問題なのは、リサイクルのルートがないということで、今までも廃棄処分をしてきたということがあります。今後も、ストローを使わないような形での子どもたちから申し出があったときの柔軟な対応等は… 隣接している都営住宅の自治会長から、避難路として有効に使えるところがあるのではないかという話は聞いているところです。","id":"exchange-061"},{"speaker":"あくつ委員","kind":"意見","question":"ストローの件は、気づきの促しをよろしくお願いしたいということと、都営住宅の避難路の件、台場小学校は３階建て、お隣が１２階ですので、よろしくご検討のほどお願いいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-062"},{"speaker":"くにば委員","kind":"意見","question":"本日は、３５７ページ、プログラミング学習、３５９ページ、人工知能（ＡＩ）型教材導入経費についてお尋ねします。このプログラミング教育必修化に対応するために、プログラミング学習の予算が組まれておりますが、この事業概要について説明を求めました。","respondent":"大関教育総合支援センター長","answer":"今度の４月から、全ての小学校および義務教育学校前期課程は、プログラミング教育に取り組む新たな教育要領に基づいて指導が行われます。それらの取り組みは、引き続き学校独自の取り組みとして継続するとともに、予算要求しています。","id":"exchange-063"},{"speaker":"くにば委員","kind":"質問","question":"続いて、３５９ページの人工知能（ＡＩ）型教材導入経費についてお伺いします。はこちらの事業内容と、導入するに至った経緯について説明を求めました。","respondent":"工藤指導課長","answer":"課題が大きく２つございまして、本来、先生方にとっていわゆるプラスの業務というのが発生するということも課題で挙げられておりました。そういった意味で、地域未来塾で課題であったものが解消されるということで、導入しようと思ったところです。","id":"exchange-064"},{"speaker":"くにば委員","kind":"質問","question":"こちらは、いい意味で私は懸念しているのですけれども、この点について何か問題だと捉えていらっしゃるか、いかがお考えになりますでしょうか。現場での声について説明を求めました。","respondent":"工藤指導課長","answer":"ですので、今後、そういうことでの成果を見ながら、やはり基礎学力向上というところは図っていきたいと考えているところではあります。そういった意味では成果に期待しています。","id":"exchange-065"},{"speaker":"くにば委員","kind":"意見","question":"このようなすぐれた学習システムを、学校教育の場においても取り入れれば、より学習効果が高まるのではないかと考えます。現在、検討しているかどうか、検討状況について説明を求めました。","respondent":"工藤指導課長","answer":"例えば公立の学校でこれが実践されているというのは、経済産業省が実証事業として行っている、千代田区立中学校１校のみです。やはり基礎学力の向上を図りつつ、いわゆる授業の中でそれが活用できるものかどうかというのは、あわせて今後検討していきたいと考えております。","id":"exchange-066"},{"speaker":"くにば委員","kind":"質問","question":"こちらは民生費の款で触れましたけれども、この導入につきましても、２３区初であるということをお聞きしました。そちらについて最後にお聞きかせください。","respondent":"工藤指導課長","answer":"今、委員にご案内いただきましたように、私どもが今、取り組んでいる取り組みというのは、やはり子どもたちに確かな学力を定着させていく。そういった取り組みだけではなく成果も含めて広く公表しながら、また進めていきたいと考えているところです。","id":"exchange-067"},{"speaker":"中塚委員","kind":"質問・要望","question":"３５５ページの生徒指導対策等経費にかかわって、性教育についてお伺いしたいと思います。この問題意識を述べて、今回は不純異性交遊の禁止について伺いたいと思います。","respondent":"大関教育総合支援センター長","answer":"生活指導上の課題として、文言で１か所出てまいりますが、不純異性交遊自体を指導内容として定めている状況にはございません。ご存じのとおり、個別の指導が必要な教育相談的対応と教育内容は区別して考えるべきだと考えておるところです。","id":"exchange-068"},{"speaker":"中塚委員","kind":"質問","question":"先ほど、個別の対応というお話がありましたが、小学校や中学生、児童や生徒は、恋愛禁止ということなのですか。ストレートに伺いたいのですけれど、いかがか尋ねました。","respondent":"大関教育総合支援センター長","answer":"考えるべきであろうという時代となってきておりますが、本区の１５校の中学校・義務教育学校の生徒手帳にも書かれてございません。そのような現状にあると認識しております。","id":"exchange-069"},{"speaker":"中塚委員","kind":"質問","question":"家庭でというお話もありましたけれども、親も子どもとどう接したらいいのかというのも悩みの一つでもあるかと思います。どこまでならだめなのか、これをどう教えるのか、教育委員会の考えを伺いたいと思います。","respondent":"大関教育総合支援センター長","answer":"まだ社会的に自立していない年齢であれば、どこまでどのように考えるべきかという部分も踏まえた上で学習指導要領は示されていると認識しております。そういった部分は個別の対応として丁寧に扱う必要があろうかと考えております。","id":"exchange-070"},{"speaker":"中塚委員","kind":"質問・要望","question":"小学校の高学年でしょうか、中学生でしょうか、さまざまな年齢があってもいいと思います。やはり２人の関係性やスキルなどを健やかに学ぶことができる性教育を、ぜひとも実践してほしいと求めましたが、いかがか尋ねました。","respondent":"大関教育総合支援センター長","answer":"一概に何年生だったらキスをしていいとか、そういった部分の指導は、なかなか極端な考え方になってしまうかもしれないと認識しております。","id":"exchange-071"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひ、こうした包括的な性教育の実践と研究を、親、教員の力を合わせて進めてほしいと求めましたが、お伺いいたします。今どんなふうに授業が行われているのか、そしてお互いの理解を深めることが大切だと思うのですけれども、いかがか尋ねました。","respondent":"大関教育総合支援センター長","answer":"５年生のところでしっかりともう出てきますので、授業として、まず共通に扱うという場面があります。女子は女子で集めて、あるいはゲストティーチャーとして生理用品メーカーの方が出前授業で来てくださる授業を活用した学校も過去にはあります。","id":"exchange-072"},{"speaker":"中塚委員","kind":"質問・要望","question":"今日は性教育について質問させていただきましたが、もっと早くちゃんと説明してほしかったと、とても思っております。ぜひとも性教育を抜本的に充実、引き上げていただきたいことを要望して、終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-073"},{"speaker":"木村委員","kind":"質問","question":"最初に、３５７ページの特色ある教育活動経費の中、しながわドリームジョブからの質問をいたします。子どもたちがどのような夢を持ち、その夢に向かって頑張っていると感じる姿をかいま見ることということはあったか尋ねました。","respondent":"工藤指導課長","answer":"子どもたちがさまざまな職業を早い段階から知り、そして自分の将来に向けた夢や希望を持つという意味では、非常に重要なことだと認識しています。気軽に声をかけて、そういったところからも学ぶ、学びが広がるというところも効果として見られているところです。","id":"exchange-074"},{"speaker":"木村委員","kind":"質問","question":"３５９ページの上段にありますけれども、１億３５万円余からですけれども、ブラインドサッカー体験教室からの質問をいたします。品川区の応援競技でもある５人制サッカー、通称ブラインドサッカーの体験教室の概要について説明を求めました。","respondent":"工藤指導課長","answer":"令和元年度からは区内の子どもたちが必ず体験できるように、第８学年で必ず実施するものということで行ってあります。令和元年度から、同じく幼稚園教員も含めまして、区立学校の教員向けの体験研修会も実施しています。","id":"exchange-075"},{"speaker":"木村委員","kind":"質問","question":"たまたま体に障害を持って生まれてきただけ、また何かでけがをしただけで、どこに引け目を感じる必要があるのか。少しでも近づきたい、自分たちの姿を理解してもらいたいと強く思っていることと思いますけれども、こういう考えに間違いはないか尋ねました。","respondent":"工藤指導課長","answer":"ふだんの生活の中で自分の考えを相手に伝える、あるいは相手を思いやる心であったりというのが非常にわかったという声を聞いてあります。そういった意味では、委員にご案内いただいたとおり、思いやりの心が育つなどの効果は見られるところです。","id":"exchange-076"},{"speaker":"木村委員","kind":"質問","question":"社会で活躍するころには、今行っている授業は、また人を思いやる気持ちがきっと役に立つときが来るであろうと私は思っています。生きた授業だと思いますが、教育長、いかがお考えか尋ねました。","respondent":"工藤指導課長","answer":"教育委員会といたしましては、現在行っている体験教室などは、今後、東京２０２０大会後も、本区のレガシーとしてやはり継続してまいりたいと考えているところです。","id":"exchange-077"},{"speaker":"木村委員","kind":"質問","question":"次に、３６９ページの中ほどにあります、教室等照明ＬＥＤ化工事費からの質問です。最初に、この事業の内容と、その目的について説明を求めました。","respondent":"有馬庶務課長","answer":"最近では、性能がよくなって、照度も十分確保できますし、蛍光灯のようなちらつきもなく、スイッチを入れるとすぐ点灯するということもあります。値段が下がっているということもございまして、ＬＥＤ化を進めているというものです。","id":"exchange-078"},{"speaker":"木村委員","kind":"質問","question":"学校のどの部分に、例えば教室や職員室など、どの部屋の照明器具を交換するのでしょうか。ＬＥＤ化することによる効果にはどのようなことがあるのか、説明を求めました。","respondent":"有馬庶務課長","answer":"教室等ということでございまして、普通教室のほかに、特別教室や管理諸室、廊下など、あらゆるところに設置していくという考え方です。電気料金が削減されるというほかに、電気の使用量が削減されるために、ＣＯ２の排出量が削減されていくと考えているところです。","id":"exchange-079"},{"speaker":"木村委員","kind":"質問","question":"令和２年度の設置校は、小学校４校、中学校２校、義務教育学校１校とありますが、具体的にどの学校でしょうか。今まで改修した学校は何校あるのか、今後の計画も説明を求めました。","respondent":"有馬庶務課長","answer":"令和２年度の設置予定校ですが、荏原第六中学校の２校、義務教育学校は八潮学園です。今のところの計画では、それ以外の学校については、基本的に令和４年度までに完了していこうと考えているところです。","id":"exchange-080"},{"speaker":"木村委員","kind":"質問・要望","question":"令和２年度の設置校１校とありますが、どちらの学校なのでしょうか。太陽光発電設備を設置する学校の選定理由はどのようなことで選ぶのか尋ねました。","respondent":"有馬庶務課長","answer":"令和２年度の太陽光発電は京陽小学校に設置いたします。基本的には、屋上防水工事をやるときに、一緒に場所があれば設置するという考えと、あとは改築時に合わせてやるという考え方で進めているものです。","id":"exchange-081"},{"speaker":"木村委員","kind":"意見","question":"今まで設置した学校の数が何校で、太陽光発電設備を学校に設置することによる効果はどのようなものがあり、どのように活用しているのか。さらに今後の計画についても、時間がある限りお知らせくださいとの意見を述べました。","respondent":"有馬庶務課長","answer":"今までに設置してきた学校は２０校です。それから、最近では蓄電池を一緒に配備しておりますので、災害用としても使えるというところだと考えております。","id":"exchange-082"},{"speaker":"横山委員","kind":"質問・要望","question":"ＧＩＧＡスクール構想の実現を要望したいのですけれども、こちらは午前中にもいろいろな議論が出ておりましたので、簡単にご見解を伺います。分析可能な状態でデータを収集・保管していただきたいと考えますが、いかがか尋ねました。","respondent":"工藤指導課長、大関教育総合支援センター長、横山品川図書館長","answer":"現在、国が行ってあります英語教育実施状況調査の中では、いわゆる英検３級以上を取得している９年生というのは４８％という結果が出てあります。… 私からは、プログラミング教育関連についてお答えいたします。さまざまな学校で取り組みを行っているものを、どのような機械… 図書館から、まずスタッフの対応についてお褒めの言葉をいただき、ありがとうあります。","id":"exchange-083"},{"speaker":"横山委員","kind":"質問・要望","question":"私は昨年、子どもたちが安心安全に食べられるメニューなので、ほかの子ども食堂からレシピを教えてほしいなどの声が寄せられていることを伺いました。すばらしい事例だと考えておりますけれども、給食を通して民間の活力を活かしていくことについて、教育委員会の考えをお伺いします。","respondent":"横山品川図書館長、篠田学務課長","answer":"最終的な大人になってからの目的ですので、委員ご指摘のとおり、高齢者や大人の方こそ身につけていっていただきたい能力だと把握しております。 給食に関するお尋ねにお答えいたします。教育委員会で考えてつくっているレシピですので、有効に使っていただけるのであれば、ぜひ提供してまいりたいと考えているところです。","id":"exchange-084"},{"speaker":"湯澤委員","kind":"質問・要望","question":"質問の前に、さまざまな批判もあるかもしれませんが、ぜひその姿勢を貫いてほしいと求めました。まずプログラミング教育とはどういったものなのか、そしてどうして必修化されたのか、経緯などを説明を求めました。","respondent":"大関教育総合支援センター長","answer":"しっかりと、基本を組み立てられる思考力・ロジックを、小学生段階で身につける必要があろうかと考えております。その中で、コンピューターだけではなくて、日常の考え方・ロジックという部分にまで踏み込んで育てていきたいと考えているところです。","id":"exchange-085"},{"speaker":"湯澤委員","kind":"質問","question":"は、２年生・３年生の子どもたちが１５人くらい、おのおので独自のプログラミングをパソコンで作成しておりました。品川区におけるプログラミング教育推進校が、対象学校中、何校あるのかも教えてほしいと求めました。","respondent":"大関教育総合支援センター長","answer":"今年度１０校ございまして、その１０校に対しましては、情報共有を図ったところです。次年度も同じように、各校の取り組みを情報共有しながら進めてまいる所存です。","id":"exchange-086"},{"speaker":"湯澤委員","kind":"質問","question":"プロボノとして活動されている方に、ある小学校の１年生から４年生の先生を対象に研修会を行ったときの話を伺いました。コミュニケーションロボットを活用した実証実験を行ったと聞いておりますが、そちらに至った経緯と成果についても教えてほしいと求めました。","respondent":"大関教育総合支援センター長","answer":"あるいは、そこに必要な、音に反応するような装置を購入した学校などもあります。２校よりぜひやりたいということで、次年度より、希望のある学校には貸し出していくことができるようになっております。","id":"exchange-087"},{"speaker":"湯澤委員","kind":"質問","question":"品川区もしっかりと先生方を支援していただけるということで、ぜひよろしくお願いしたいと思います。多くの民間企業や、こういった民間企業やボランティアの支援を効率よく今後受けていく予定はあるか、その辺も教えてほしいと求めました。","respondent":"大関教育総合支援センター長","answer":"五反田バレーから４名の方がボランティアで子どもたちへの授業を実施し、その後、教員研修会もやっていただけるというすばらしい予定がありました。今回の新型コロナウイルス感染症対応のために流れてしまったのですが。","id":"exchange-088"},{"speaker":"湯澤委員","kind":"質問・要望","question":"そういった家庭も少なくないのではないかと思いますが、確認を兼ねて質問します。そして、新規でも図書カードなどはつくれるのかを教えてほしいと求めました。","respondent":"横山品川図書館長","answer":"休業中の図書館での対応についてのお尋ねです。今までどおり各図書館取次施設ほかで受け付けておりますし、カウンターが開いておりますので、新規の登録についても受け付けしています。","id":"exchange-089"},{"speaker":"湯澤委員","kind":"質問","question":"サービスを休止してからの予約状況などはどうなのかというのと、あと、こういった大変なときですから、運営のほうは皆さん大丈夫かと思うのですが、その辺はいかがか尋ねました。","respondent":"横山品川図書館長","answer":"ご不便をかけていることを口になさる方もいらっしゃるのですが、スタッフは、そういう応援のお声を力に変えて頑張っているような状況です。バックヤードについては、むしろ、忙しいような形で運営しています。","id":"exchange-090"},{"speaker":"湯澤委員","kind":"質問・要望","question":"本当に大変ご苦労の中、お仕事をされているかと思います。業務上、手に負えない場合などにおきましては、臨時職員等の対策もとってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-091"},{"speaker":"のだて委員","kind":"確認","question":"３６９ページの学校図書館運営費にかかわって、３７３ページ、新型コロナウイルス感染症での補償について伺います。確認になってしまいますが、業者にも支援をしていくということでよいのか、確認させてください。","respondent":"篠田学務課長","answer":"給食納入業者への支援についてです。直接、国からさまざまな形で企業への支援をしていくと伺っておりますので、そういった対応がなされるものと考えているところです。","id":"exchange-092"},{"speaker":"のだて委員","kind":"質問・要望","question":"しかし、文教委員会では、５年、１０年先の話ということでした。できる限り早く実施できるようにしてほしいと求めましたが、何が課題になっているのか伺います。","respondent":"横山品川図書館長","answer":"それなので、今の形を継続する学校もあるでしょうし、やはり時間を増やしてスタッフを配置してほしいという学校もある。それぞれ検討し、お時間をいただいて、長期的な検討をしたいとお答え申し上げております。","id":"exchange-093"},{"speaker":"のだて委員","kind":"質問","question":"例えばで構わないのですけれど、どれだけ違うのか、その例を具体的に教えてほしいと求めました。やはり週５日、さらにボランティアなどの支援をしていくという形で進めていけばいいのかと思うのですが、いかがか尋ねました。","respondent":"横山品川図書館長","answer":"自分から読んであげたり、情報共有をしたりという交流を通じて読書に親しむことが、とても効果的だというご意見をたくさんいただいております。","id":"exchange-094"},{"speaker":"のだて委員","kind":"質問・要望","question":"１校専任で、より子どもたちの読書への関心を高めることや、教育面でも充実させることができると考えています。よりよい学校図書館の充実へ、学校司書の１校専任、直接雇用を求めますが、いかがか尋ねました。","respondent":"横山品川図書館長","answer":"必ず月に１度、直接雇用であるとか、スタッフだから不足しているというような部分はございません。とてもバランスがとれている状態なので、これから変化を起こす必要があるかどうかも、各学校で検討するような課題だと考えております。","id":"exchange-095"},{"speaker":"のだて委員","kind":"質問・要望","question":"今、学校司書の配置ということで求めていますので、そういった形で進めてほしいと求めました。区の司書教諭の状況と、研修はどのように行われているのか、伺います。","respondent":"工藤指導課長","answer":"現在、司書教諭で、資格を持っている者ということで言えば、本区内教員で言えば１４０名おるのですが、そのうち発令を出している者は、小学校２２名、中学校２名、義務教育学校１０名です。","id":"exchange-096"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"最初に、３６９ページ、音楽室折れ天井等改修工事費についてお伺いいたします。それで、これは音楽室の工事なので、防音対策とか、あるいは近隣の対策も兼ねた工事なのかどうなのか、教えてほしいと求めました。","respondent":"有馬庶務課長","answer":"音楽室等の改修ですけども、これにつきましては、来年度、小学校２校ですけれども、やる場所は、１つの学校は音楽室とパソコン教室、それからもう一校につきましては多目的室ということで、規模が大きいということで、２校ですけれども２,０００万円を超えているという状況です。","id":"exchange-097"},{"speaker":"高橋（伸）委員","kind":"質問","question":"わかりました。これは予算書にも書いてありますけれども、折れ天井等というのは、今までにもそういった事例があったかどうかということだけ説明を求めました。","respondent":"有馬庶務課長","answer":"ああいうのが１つの対象にはなるのと同時に、そういうところを全部、対象にしているというものです。","id":"exchange-098"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"続きまして、３７３ページ、防災ヘルメット購入に関連して、防災教育についてお伺いします。それで具体的に、本区の公立の小・中学校の防災教育の中でも、避難訓練についてお知らせほしいと求めました。","respondent":"大関教育総合支援センター長","answer":"これは、予告なしで、子どもたちにとっては、３時間目に起きるときもあれば、あるいは１５分休みに起きる場合もあります。そのような形を目指しています。","id":"exchange-099"},{"speaker":"高橋（伸）委員","kind":"質問","question":"それで私は、指導はされておられることを前提にして申し上げるのですけれど、音楽室でしたらグランドピアノが大体３００ｋｇ近くあると思うのです。体育館では、どういうふうに対応をとられているのかということを、改めてお聞きしたいと思います。","respondent":"大関教育総合支援センター長","answer":"子どもたちに対しては、窓ガラスからは少し離しておかねばならない。もしそこへ隠れようとする子があれば、そこは逆に危ないのだと、具体的に指導するチャンスだと捉えております。","id":"exchange-100"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ほかの地区でもやっておられると思うのですけれども、防災教育としてどういうふうに取り組んだのかどうかだけ教えてほしいと求めました。当然、地域とのかかわりも含めて、。","respondent":"大関教育総合支援センター長","answer":"やはり休日の中で、教員も複数名参加していることによって、子どもたちが来てくれたなどという地域もあろうかと思います。自分たちのよく知っているあの子がポンプ隊として活躍している姿を見ることによって、身近なものだと考えるいい機会だと捉えております。","id":"exchange-101"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"地震は、本当にいつどこで発生するかわかりません。避難訓練も、何ですか、マンネリ化にならないように、これからも子どもたちのために指導してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-102"},{"speaker":"塚本委員","kind":"質問","question":"時間がもしあれば３６１ページの特別支援教育サポート経費ということでお伺いしたいと思います。区のほうから一括して、この件につきまして、今どのように対応が考えられているかお伺いしたいと思います。","respondent":"大関教育総合支援センター長","answer":"４月からの新たな配布を目指しまして、毎年配っている、台風の際の対応等について改定を進めているところです。区内の関係課と調整も行いまして、私または統括指導主事より、４月以降はホームページを見てくださいという文言も書き加える予定です。","id":"exchange-103"},{"speaker":"塚本委員","kind":"質問","question":"そこのところでのお伺いをしたいのですが、通常の教員のほうでこれを使って教育をするということですから、どういった工夫がされてきているのか。一応、開発元等からの技術的なサポート等はどの程度受けられてきているのかというところも含めてお伺いしたいと思います。","respondent":"大関教育総合支援センター長","answer":"ご案内いただきましたように、三木小学校および第一日野小学校、２校で取り組んでまいりました。２校がそれぞれ自校でもともと予定していた年間の学習の中にどう取り入れるかという視点で、ＮＴＴ東日本、教材としての開発を行ってきたところです。","id":"exchange-104"},{"speaker":"塚本委員","kind":"質問","question":"設計時点から積み重ねてやってきた学校のように、なかなか一足飛びに行くのかというところが、非常に問われるところかと思います。きちっとスタートできるように、展開できるように、どのようにしていくというお考えかをお伺いいたします。","respondent":"大関教育総合支援センター長","answer":"例えば１週間、２週間という単位で指導案はありますので、次年度もそのような形で広めていきたいと考えております。","id":"exchange-105"},{"speaker":"塚本委員","kind":"質問","question":"３５５ページの生徒指導対策費で、本当にもう抜き差しならない状況に陥るというようなことを、非常によく勉強させていただきました。生徒指導対策費というところで本当にいいのかどうかも、どれぐらいの力を込めて取り組んでいるのだというようなところをお伺いしたいと思います。","respondent":"大関教育総合支援センター長","answer":"どの学年も毎年必ず行っていますが、それでもやはり、事件はゼロにはなりません。家族も巻き込んで、地域も巻き込んで、啓発を重ねているところです。","id":"exchange-106"},{"speaker":"塚本委員","kind":"質問・要望","question":"やはりほとんどの方、もう９割方が所持するという中学生ぐらいの時期に、今後とも取り組みをよろしくお願いしたいと思います。そういった意味で、新しい事業についてのお考えというか、お聞かせほしいと求めました。","respondent":"大関教育総合支援センター長","answer":"新たな状況にも知見のある方を常にお願いする形で、区内にもたくさん先進的な研究者がいらっしゃいますので、そういった方もお呼びしてまいりたいと考えております。","id":"exchange-107"},{"speaker":"あべ委員","kind":"質問・要望","question":"私からは、３５１ページ、就学援助費と、３５５ページの生徒指導対策費になるのでしょうか、痴漢対策についてお伺いしたいと思います。いかがか尋ねました。","respondent":"大関教育総合支援センター長、篠田学務課長","answer":"３日間いつでもいいですよ」というふうに、学年をずらすなど、工夫はさせていただいているところです。そのときに、ある小学校では、ふだんのパソコン室のｅライブラリのＩＤなどを渡すなどの工夫もしているところです。 ４月の当初に皆さんにお渡しするような形で、新年度のものを今、つくり始めてしまっているところがあります。ただ、ご指摘の内容も踏まえまして、今後、どういったレイアウトができるかというのは研究してまいりたいと思います。","id":"exchange-108"},{"speaker":"あべ委員","kind":"質問・要望","question":"通勤・通学の電車内で多発する痴漢被害は、被害者の約３割が１０代の女性です。ＨＥＡＲＴＳの方々とも連携しながら、子どもたちに学ぶ機会をつくってほしいと求めましたが、いかがか尋ねました。","respondent":"大関教育総合支援センター長","answer":"いじめ対応だけでなく、不登校未然防止という部分でも、ＨＥＡＲＴＳは活躍しています。既に取り組まれて数年経っているようですので、そんな取り組みをご紹介するなど、いろんな工夫はあろうかと思います。","id":"exchange-109"},{"speaker":"あべ委員","kind":"質問・要望","question":"これは実は保護者の側からも要望が多くて、区内では、実態としては連絡帳を使っているというところもかなり多いと聞きました。いかがか尋ねました。","respondent":"大関教育総合支援センター長","answer":"電話での連絡等をお願いしている部分は、まずご家庭と学校が連絡を取り合うことで、やはり子どものことを一緒に共通理解したいという狙いがあります。","id":"exchange-110"},{"speaker":"あべ委員","kind":"質問・要望","question":"メーカーを含めて引き続き対策をとっていただきたいのですが、それにはある程度、定量的な調査も必要なのかと思います。人工芝は、学校だけではなく運動施設にも広く使われており、ぜひ連携して調査と対策を進めていただきたいと思うのですが、いかがでしょう。","respondent":"有馬庶務課長、大関教育総合支援センター長","answer":"きちんと、それなりの頻度で清掃を行っているということですので、その状況をまたメーカーに伝える機会を設けていきたいと思います。それから、天王洲などの公園にも芝もありますし… 補足させてください。原則はやはり子どもの安否確認という目的もありますので、メールありきではないということは、誤解のないようにつけ加えさせてください。","id":"exchange-111"},{"speaker":"あべ委員","kind":"質問・要望","question":"それはそれで、やはり改善の余地があるのであれば、見直していくということもありかと考えています。品川区でもぜひ検討していただきたいと思うのですが、いかがか尋ねました。","respondent":"大関教育総合支援センター長","answer":"標準服は各学校で、校区教育協働委員会の中で検討していく学校などもあろうかと思います。もう既に、それは各学校の地域と一体化した中での取り組みであると、教育委員会は考えております。","id":"exchange-112"},{"speaker":"大倉委員","kind":"質問・要望","question":"私からは、学校授業で武道について伺いたいと思います。現在、教員の方がどのぐらいやられているのかという数を教えていただきたいのと、こういう気づきがありましたみたいなところがあれば説明を求めました。","respondent":"大関教育総合支援センター長","answer":"ここには課題が実はこれまでもありまして、そして礼儀作法をその中でどう学んでいくかという部分を踏まえながら、検討してきた経緯があります。次年度以降は市民科の中の「私たちのまちの伝統と文化」「様々な伝統と文化」の中で扱うというふうに予定しています。","id":"exchange-113"},{"speaker":"大倉委員","kind":"質問・要望","question":"数がわかれば教えていただきたい。市民科で行っていくところで、今までと違うことがあるなら、違うところについて教えてほしいと求めました。","respondent":"大関教育総合支援センター長","answer":"最近は、剣道に変えたいので、剣道の防具をぜひ買ってほしいと申請いただくようなケースもあります。それは、近隣の支援いただくゲストティーチャーが見つかるかどうかもあろうかと思いますが、とても子どもたちの心に響くという実態もありますので。","id":"exchange-114"},{"speaker":"大倉委員","kind":"質問","question":"投げたり打ったりするわけですから、自分１人ではできない、武道は非常にいいかと思っているところです。例えば人数が多い学校に先生が１人来て、多くの人に参加していただくというところでは、その辺について説明を求めました。","respondent":"大関教育総合支援センター長","answer":"どういう内容をどこまで安全に実施するかは、例えば連盟の方と教育委員会が十分に情報共有等を事前にすることが、今後大切だと認識しています。","id":"exchange-115"},{"speaker":"大倉委員","kind":"質問・要望","question":"そういったところもしっかり活用していただきたいというところと、品川区にも武道場ができたらいいと、すごく心から思っているところです。私からは願望ということで、非常にやっていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-116"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私からは、３６１ページの特別支援教育費について伺いたいと思います。それから、それは誰がどのように立てて、どう活用されるのかについても説明を求めました。","respondent":"大関教育総合支援センター長","answer":"教員の配当の考え方ですが、特別支援教室を利用する児童・生徒１０名に対して１名の教員ということで、配当されているところです。次年度は、拠点校は、小学生については１０校から１２校に増える予定ですので。","id":"exchange-117"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"小学校では１万１,２６０時間、中学校では１,８６０時間ということになっていたのですけれど、この時間数ということでいいのでしょうか。おおよそ、夏休みや春休みなどを入れて１０か月として３６６人で割り返すと、これぐらいの配置というのが実態なのかについても伺わせてください。","respondent":"大関教育総合支援センター長","answer":"学習支援員・介助員の配置は、週に１日配置されるお子さんもいれば、その２人について学習支援員が週当たり３時間入ります。その３時間はどこがいいか、プール介助で、一律に並べて１人当たり３時間という考え方はしておりません。","id":"exchange-118"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"もっとたくさんつけていただきたいという要望との状況とあわせて、どうなのかというあたりもちょっとお聞かせください。合理的配慮というところに対しても提供が求められていると思うのですけれど、なぜ特別支援教育推進計画をつくらないのかについて伺いたいと思います。","respondent":"大関教育総合支援センター長","answer":"学習支援員の部分ですが、特別支援学級にはぜひ常駐で、支援員を教員のほかにつけるという部分も増やしてまいりました。ですので、また必要に応じて、また就学相談委員会などで保護者等の意見ももらいながら見直しは進めてまいります。","id":"exchange-119"},{"speaker":"西本委員","kind":"質問","question":"もうそろそろ、いいのではないでしょうか。教育改革「プラン２１」から、どういう観点でこういう動きになってきているのか、その成果をお聞きしたいと思います。","respondent":"篠田学務課長、工藤指導課長、横山品川図書館長、大関教育総合支援センター長","answer":"今回、令和２年度の予算では、これまで継続してきましたストロンチウムの測定を一旦お休みするということで考えてあります。… 例えば過去１０年間、また今後の１０年先を見据えた中でも、やはり社会あるいは変化というのは激しいものです。その中では… 小学校においては、今現在ですと７２万６,８７４冊、中学校においては４万５,１０５冊になってあります。年当たり、今現在の換算で… 不登校の実態です。","id":"exchange-120"},{"speaker":"西本委員","kind":"質問","question":"学校選択制については、そろそろ見直しを図っていくべき時期に来ているのではないかと私は思っておりますので、その考え方についてお聞きします。図書館というのは、かなめになるのではないかと思いますが、区のお考えについてお知らせください。","respondent":"工藤指導課長、篠田学務課長、大関教育総合支援センター長","answer":"コミュニティ・スクールでのところですが、やはり学校・家庭・地域、総がかりとなって、地域の学校に通う子どもたちをよりよく成長させていくと。… 学校選択制の見直しについてのお話です。学校が選択できると、入学できる学校を考えるということが一番重要だと考えておりますので… 教室に入りづらいお子さんへの対応は、そこについて柔軟に、今後とも各校のアイデアを支援してまいりたいと思います。","id":"exchange-121"},{"speaker":"西本委員","kind":"質問・要望","question":"これから学校のあり方ということも大きく変わってくると思いますので、地域に根差したというところでは、進めていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-122"},{"speaker":"吉田委員","kind":"質問・要望","question":"継続を求めますが、今のリスクについて見解を伺います。それから、先ほどご答弁の中で、ストロンチウム検査について一旦お休みをするということについての、どういう意図かも伺いたいと思います。","respondent":"篠田学務課長","answer":"ほかの自治体の実施状況を見ても、過去には２０区を超えるような状況だったのですけれども、半数以下になっている状況があります。先ほどご説明したような状況がありますので、来年度は引き続き、こちらについては実施していくというような形で。","id":"exchange-123"},{"speaker":"吉田委員","kind":"質問","question":"このときに、今やめる判断をするということは、どういうことなのかということを伺っております。対象を絞って単品検査に切り替えるとか、そういう考え方もあると思うのですけれども、その点についてはいかがか尋ねました。","respondent":"篠田学務課長","answer":"今回についても、そういった流れの中で、認識を改めることはないのかと考えているところです。単品検査ですと、全ての食材を検査するという方向になりましたので、この考え方は基本的に変える必要はないのかと考えているところです。","id":"exchange-124"},{"speaker":"吉田委員","kind":"質問・要望","question":"当初の単品検査から全体の検査になった経緯は伺っております。リスクは高まっている今、やめるべきではないと、最後、要望とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-125"},{"speaker":"こんの委員","kind":"質問","question":"この３点の質問の前に、今朝ほどのご報告に関連して何点かお伺いしたいと思います。あわせてもう一点、１６日から２５日までの校庭や学校図書館に来る児童・生徒の登下校の安全についてお伺いしたいと思います。","respondent":"有馬庶務課長","answer":"我々はリスク管理をしながらの対応ということで、苦渋の判断ですけれども、そのような対応としています。ＰＴＡを中心に、いわゆる８３運動の拡大版ではありませんけれども、そういったところはまたＰＴＡなどにも呼びかけていきたいと考えている次第です。","id":"exchange-126"},{"speaker":"こんの委員","kind":"質問・要望","question":"今ご努力をしてくださっているということですので、引き続き安全対策のほうもよろしくお願いいたします。現状をまずお伺いしたいのと、マイスクールではどういう対応をとられているのか、現状をお聞かせほしいと求めました。","respondent":"大関教育総合支援センター長","answer":"は個別の対応として、指導員からお電話を家庭にかけて、「どうだい？」などということで、生活リズムが崩れないようにという配慮をしている最中です。","id":"exchange-127"},{"speaker":"こんの委員","kind":"質問・要望","question":"次に、中学生への対応についてお伺いします。そうすると、本来ならば登校しているこの時期に休校になっていることについて、日常の中学生の過ごし方はどのような方針がとられているのか尋ねました。","respondent":"大関教育総合支援センター長","answer":"個別に相談に来たお子さんへの対応だけではなくて、必要なお子さんには、教員が出向いて行って、家庭訪問もケースによっては今やっているところです。臨時休業期間中も対応しながら、進路が未決定のお子さんへの対応などもありますので、そこはもう特にやっている最中です。","id":"exchange-128"},{"speaker":"こんの委員","kind":"質問","question":"学校夜間電話対応経費についてお伺いします。この辺を簡潔にご説明ください。","respondent":"工藤指導課長","answer":"委員ご指摘の本事業です。かかってきた電話の対応に追われて、そこに委託をしまして、そのかかった電話についてはそちらが受けるというものを計画しています。","id":"exchange-129"},{"speaker":"こんの委員","kind":"質問・要望","question":"夜間だったり、そうした夜間に発生する事案への対応は、代行サービスの方はどの程度それに対応できる体制をとられているのか。例えば、アドバイスやその場の対処などを求めてくる、そうしたことへの対応はどのように考えていらっしゃいますか尋ねました。","respondent":"工藤指導課長","answer":"委員ご指摘のように、これから実施する上でも、そういったことは懸念されることは当然あります。そういったことは、今後どこに送るのかというのは、検討する必要があるとは考えているところはあります。","id":"exchange-130"},{"speaker":"こんの委員","kind":"質問","question":"次に、図書館の維持・運営費についてお伺いしたいと思います。あれから２年近く経つわけなのですが、その後の導入状況はどのようになっていますか尋ねました。","respondent":"横山品川図書館長","answer":"小型の書籍消毒機を導入する予定で、今、購入の手続きを進めているところです。来年度、指定管理者の協力を得まして、地区図書館に導入を検討しているところがあります。","id":"exchange-131"},{"speaker":"こんの委員","kind":"質問・要望","question":"１つの機械で２、３冊しか消毒はできないのですけれども、導入を進めてほしいと求めました。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-132"},{"speaker":"芹澤委員","kind":"質問","question":"３４９ページ、８３運動経費、時間があれば３５７ページの経済活動体験学習について伺います。初めに、ＡＩについて伺います。","respondent":"工藤指導課長","answer":"Ｑｕｂｅｎａですけれども、今、地域未来塾に来ている６年生を対象にと考えているところです。これは教員であっても、教員のアカウントで入れば、例えば自分の学校の子どもたちの履歴というのが確認できるという状況になるものです。","id":"exchange-133"},{"speaker":"芹澤委員","kind":"質問・要望","question":"品川で言えば９年生までの、あとは場合によっては英語もあるような記載の確認がとれて、これからこういう授業というのが増えていくと思います。もちろんボランティアですからないと思うのですが、そういったかかわりが引き続きあるのかどうか、説明を求めました。","respondent":"工藤指導課長","answer":"まず１点目ですが、また管理は学校支援地域本部で行いますので、切り離した形で考えてあります。それをクリアするのが、このソフトであると考えていますので、そういったところでの活用を考えているところです。","id":"exchange-134"},{"speaker":"芹澤委員","kind":"質問・要望","question":"続いて、８３運動経費について伺います。質問としては、正式には何年から８３運動が始まったのか、あと登録するに当たって何か資格というのが必要なのかを説明を求めました。","respondent":"有馬庶務課長","answer":"基本的に、子どもの安全として取り組んできたということで表面化してきており、歴史としてはそのぐらいの長さとなっているものです。これまでも、今年はピンバッジ、その前はクリアファイルといった、啓発グッズをつくってきたというものです。","id":"exchange-135"},{"speaker":"芹澤委員","kind":"質問","question":"計１２の事業で３項目ですから、計３６項目ある中で、おおむねＡとＢなのですが、残念ながら、８３運動の効率性だけがＣの評価になっている。一部見直しと書いてあるのだと思うのですが、この一部というのは、どういったことを改善される予定なのか尋ねました。","respondent":"有馬庶務課長","answer":"今年度の事務事業評価において、８３運動を全体の１２事業の一つとして取り上げさせていただきました。もう少し周知活動をしっかりしていこうということで、今年は年２回の広報紙以外にも、少しずつそういったことに取り組んでいるという状況です。","id":"exchange-136"},{"speaker":"芹澤委員","kind":"質問","question":"例えば学校関連のイベントというのはいろいろあると思うのですが、そういったところでの周知・啓発というのは行われているのでしょうか。地元の清掃活動など、高齢者クラブとの連携と含めて、企業や商店街との連携というのはご検討されていらっしゃるのか尋ねました。","respondent":"有馬庶務課長","answer":"これは、８３運動の推進委員会へ私どもが支援をしている事業というような位置づけというところがございまして、ちょっと難しいところであります。","id":"exchange-137"},{"speaker":"芹澤委員","kind":"質問・要望","question":"その１週間には、カラーアクションというのですか、お互いに意思表示をする。「これは８３運動なんですね」と聞いてみたら、８３運動って何ですか」と逆に聞かれて、そこでまた広がっていくということもあると思います。","respondent":"有馬庶務課長","answer":"まさに委員がおっしゃるとおり、この８３運動ができたときの主意書にも、多くの大人の目で見守ることが必要だというようなことも書いてあります。今後、もう少し広げるために何ができるか、また一生懸命、考えていきたいと思います。","id":"exchange-138"},{"speaker":"渡部委員","kind":"質問","question":"学校によって、去年は４,０００万円余ついていた学校地域コーディネーター経費が１２万円になってしまっていて、どこに行ってしまったのだろうと。その辺のお金の行き先を教えてほしいのと、アシスタントコーディネーターの経費は今度、去年より増えているわけです。","respondent":"工藤指導課長","answer":"これは平成３０年度から進めているのですが、やはり学校支援地域本部、アシスタントコーディネーターを設けているです。連携は同じ学校にいますから考えられるところですが、教員の業務を支援する役割としての任用・配置ですので、教員免許によらない業務を支援するです。","id":"exchange-139"},{"speaker":"渡部委員","kind":"確認","question":"でも、その中で、今、指導課長がおっしゃったようなことで確認はとれましたので、よろしくお願いします。決まった時間の中で何人かで、総枠で決まっている時間内でおさめていけばいい仕組みなわけですね。","respondent":"工藤指導課長","answer":"委員ご指摘のとおりです。","id":"exchange-140"},{"speaker":"渡部委員","kind":"質問・要望","question":"学校給食の３７３ページは、確認をもう一回させていただきたいのは、卒業生には返すのだと。この辺は何か混乱等があったかどうかというところ、あと保護者との間で給食費云々のところで問題があったかどうかのところだけ説明を求めました。","respondent":"篠田学務課長","answer":"在校生に関しては４月以降に送るという形で、場合によっては、そういった対応も変わらざるを得ないこともあり得るかと思います。ですので、業者によっては当然、その辺の対応がありまして、その先の段階の卸や生産者などの方にいろいろ発注をかけているところがあります。","id":"exchange-141"},{"speaker":"渡部委員","kind":"質問・要望","question":"その場その場の適切な情報をしっかりとお流しいただいて、子どもたちが、卒業式はやるですので、最後に１つだけ聞きます。終業式というのはどういうふうになるのでしょう。","respondent":"大関教育総合支援センター長","answer":"体育館に一同を単に集めるのではなくて、例えば教室の中で、放送設備を使うなどの工夫をして行います。","id":"exchange-142"},{"speaker":"高橋（し）委員","kind":"質問","question":"そして、登下校時の責任の所在といいますか、学校管理下でそういったことを行うという考え方なのでしょうか。それから、すまいるスクールにも保険があるのですが、そちらとの関係はどのようになっているのか尋ねました。","respondent":"有馬庶務課長","answer":"それから、自校の児童・生徒に限るということは、事故があったときの保険の関係ということもあります。ある意味、教育活動の一環の中で行うものだということで、教員が見る、いわゆる事故があったときは保険を適用するということで考えている中身です。","id":"exchange-143"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"それから、それらの教員、先生方ですけれども、小学校５２人、中学校１８人のうち、いわゆる初任者の方はどれぐらいいらっしゃるのでしょうか。少し前の委員からも質問がありましたけれども、それから巡回している先生と、対象児童の保護者との情報共用はどのようにされているのか尋ねました。","respondent":"大関教育総合支援センター長、工藤指導課長、若生学校施設担当課長","answer":"授業を抜けて特別支援教室が必要なお子さんは、東京都では３％と考えているということで、品川区の考え方と一致していると認識しています。… ご指摘のとおり、週における勤務日数あるいは１日の勤務時間数等が固定されるなど、これまでの柔軟な任用というのができないということがあります。… 具体的には、修繕や更新についてどのような考え方に基づいて行っていくかといった大まかな方針を整理するといった内容で検討を進めております。","id":"exchange-144"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"学校地域コーディネーターの会計年度職員制度については、働きやすい状況で、ぜひ地域の方のご協力を仰いでほしいと求めました。ホームページで公開ということですので、改築計画やほかの計画との整合性を見て、また別の機会にお尋ねしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-145"},{"speaker":"須貝委員","kind":"質問","question":"私は、３６４ページ、学校教育費についてお聞きしたいと思います。学校では、このような実情を把握していると思いますが、なぜ改善できないのか尋ねました。","respondent":"工藤指導課長","answer":"そういったサイクルで授業改善も進めながら定着を図ってきているところではあります。算数・数学におきましては習熟度別指導なども行いながら、より基礎学力の定着を図るという取り組みは十分進めてきているところではあります。","id":"exchange-146"},{"speaker":"須貝委員","kind":"質問","question":"定着させるためにさまざまな努力を重ねてというならば、こういうお子さんたちをどうして見逃してしまうのですか。教育委員会は、このような実情をきっちり把握しているのか尋ねました。","respondent":"工藤指導課長","answer":"そういった取り組みは進めているところです。その学校の努力についても私ども教育委員会は把握しているというところで、進めているところです。","id":"exchange-147"},{"speaker":"須貝委員","kind":"質問","question":"ですが、現実、どうなのですか。それを全然やっていないというのはどういうことか尋ねました。","respondent":"工藤指導課長","answer":"その中でも習熟の程度の違いがあらわれてくるというところが、教員が授業改善に資して、場合によっては長時間労働をするということがあらわれてくる。健康を保持しながら、より質の高い教育ができるように、教育委員会としては学校を指導していくです。","id":"exchange-148"},{"speaker":"須貝委員","kind":"質問","question":"では、皆さんは責任をどうとられるのですか。「義務教育段階で重要だと思うことは何ですか」という問いに、小・中学生の保護者の回答は、１番目に、基礎学力をつけることという回答が７割。","respondent":"工藤指導課長","answer":"教育委員会としての責任ということで言わせていただければ、今、品川区におります２万人の子どもたちの将来に対しては責任を負っている。これが本義であるということは重々理解していますので、それを進めてまいるです。","id":"exchange-149"},{"speaker":"須貝委員","kind":"質問・要望","question":"学年に見合った学力を身につけていない児童・生徒がいたら、春休み・夏休み・冬休みや土曜日などを使って、補習を義務づけたらどうですか。ちょっと身につけていない、この子を上の学年に上げてしまったら大変だという子は、やはりそういうこともすべきではないか尋ねました。","respondent":"工藤指導課長","answer":"卒業した後であっても、自分が異動した後であっても、教え子というのはそのままつながっているものであると認識しています。それについては私どもが何か言うところはございませんが、私どもはあくまでも教育課程内の授業の中で力をつけるべく努力しています。","id":"exchange-150"},{"speaker":"須貝委員","kind":"意見","question":"そして、なぜ私学ではやっているのに公立学校はやらないのか。その辺についてちょっとお答えくださいとの意見を述べました。","respondent":"工藤指導課長","answer":"例えば学校に進学であれば、志望校選択に向かっては、一人ひとりとしっかりと向き合って支援していくということで行っている。これがまさに、私ども区立学校で行っているところだと認識しています。","id":"exchange-151"},{"speaker":"須貝委員","kind":"質問・要望","question":"ですから塾に行ってしまっているのです。基礎学力、その学年に見合った学力を身につけさせるような仕組みづくりをしてほしいのですが、それについてご見解を説明を求めました。","respondent":"工藤指導課長","answer":"そこに焦点を当てながらも、やはり授業改善に資して、子どもたちに確かな学力を身につけさせていく。このことをさらに進めていきたいと考えています。","id":"exchange-152"},{"speaker":"安藤委員","kind":"質問","question":"１点だけ伺いますけれど、保護者等からの希望などがあれば、何か代替措置などはとられるということもあるのでしょうか。伺いたいと思います。","respondent":"有馬庶務課長","answer":"現在のところ、改築で校庭が使えないというところにつきましては、今回の校庭開放でどこを使ってほしい、使えるというところまでの調整ができているものではございません。","id":"exchange-153"},{"speaker":"安藤委員","kind":"質問・要望","question":"昨年７月の文教委員会で、今後検討させていただきたい」と答弁しておりましたけれども、どんな検討をされたのか伺います。資料配付を改めて求めますけれども、いかがか尋ねました。","respondent":"有馬庶務課長","answer":"ただ、ほかのやり方については、また別途、今、検討は引き続き行っていこうということにしております。ただし、それ以外のものについて、その場で閲覧できるものがあるかどうかということは、引き続き検討している状況です。","id":"exchange-154"},{"speaker":"安藤委員","kind":"質問・要望","question":"２３区中１１区でやっていますし、閲覧も配付もしないという区は２３区では少数派なのですけれども、その後で議会に報告されるわけじゃないですか。区教育委員会はどのように評価しているのか伺いたいと思います。","respondent":"大関教育総合支援センター長","answer":"校則や、まずはフリーな状態から、校長が子どもの意見を聞くというような取り組みがクローズアップされている記事なども読んでいるところです。学校運営、学校経営は校長が考えていくべきものであるとして、１つの例として認識したところです。","id":"exchange-155"},{"speaker":"安藤委員","kind":"質問","question":"結果、子どもたちの豊かな成長、自発性、社会性をゆがめるものではないかと思うのですけれども、いかがでしょうか。桜丘中学校の実践も参考に児童・生徒の意見を聞き、これは見直していくべきだと思いますけれども、見解を伺います。","respondent":"大関教育総合支援センター長","answer":"社会の中で何らかの約束、ルールというものがあってこそ、民主主義が成り立っていると認識しております。それが学校の教員の立場だと考えております。","id":"exchange-156"},{"speaker":"安藤委員","kind":"質問・要望","question":"もう一つ伺いたいのですけれど、これになじめない子が一定数出てくるのは当然だと、これを読んで思わざるを得ませんでした。伺いますけれども、今のこうした品川区の教育の全体の流れを根本から見直すべき必要があると私は思いますけれども、いかがか尋ねました。","respondent":"大関教育総合支援センター長","answer":"別個で捉えるべきだと考えておりますが、まずは、子どもたちがどのように自分たちの生活をよりよくしていくかを考えていく。それが品川区の現在の教育の形だと考えております。","id":"exchange-157"},{"speaker":"安藤委員","kind":"質問・要望","question":"個々の声への配慮と品川区の教育改革は別個に捉えるべきだというお話でありましたけれど、確かに単純に結びつけて考えるつもりはないのです。限られた一部の価値観で子どもたちを毎回測る学力テストという、全体の教育システムがかかわっていると私は指摘し、改善を求めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-158"},{"speaker":"たけうち委員","kind":"質問","question":"私は、３５１ページのクラブ・部活動等経費に関連して、また３６７ページの学校ホームページ経費でお伺いします。そこに参加される予定だったような方がいるかどうか、もしくはさまざまな対応について、どのようにされているかというのがわかれば説明を求めました。","respondent":"有馬庶務課長、大関教育総合支援センター長","answer":"どんな形のお知らせをすればいいのかというようなことで、午前中のうちに、少しひな形みたいなものをつくりまして学校に周知しています。学校で出さなかった学校もあったのかとも思いますけれども、今度はしっかり出すようにということ… ９年生が卒業した後の春休み中等の活動は、もともと新型コロナウイルス感染症対応以前に、春季の大会などは中止という動きになっておりました。","id":"exchange-159"},{"speaker":"たけうち委員","kind":"質問・要望","question":"これも要望で終わりたいと思います。どういう形で残すかというのは、振り返る中でしっかり残して検証していくことが大事だと思いますが、それについてのお考えを説明を求めました。","respondent":"有馬庶務課長","answer":"まさに我々も経験したことのないようなところで、何が正解かわからないですので、しっかり後で検証はしていきたいと考えております。","id":"exchange-160"},{"speaker":"大沢委員","kind":"質問・要望","question":"２つ、お伺いさせてほしいと求めましたが、国会で特別措置法が成立したということになっております。理事者より区の学校の対応を伺ったわけですけれども、そして学校の運営面、具体的というより考え方を説明を求めました。","respondent":"有馬庶務課長","answer":"それに基づいて我々も、品川区の現状を考えながら、対応を日々考えてきたということがあります。それはそれで対応せざるを得ない部分があるかと思いますけれど、我々は品川区の感染を予防していくというような立場で頑張っていきたいと思います。","id":"exchange-161"},{"speaker":"大沢委員","kind":"質問","question":"これも考え方で結構ですので、どのように行っていくのか、基本的な考え方を説明を求めました。","respondent":"工藤指導課長","answer":"４月以降、自分のこれまでの学習を振り返り、自分が大会のある年にかかわって何ができるかを一人ひとり考えてもらおうと思ってあります。それは今後も、延期や中止になったという時期などが示された段階で構築し直して、より充実した教育をしていくという考えです。","id":"exchange-162"},{"speaker":"大沢委員","kind":"質問・要望","question":"今日は教育費なので、あえて読み方なども正確にお話をさせてほしいと求めましたが、対話力についてどのように学校現場で行われているのか。まずは対話力を伺う前に、ご見解というか、認識をお伺いしたいと思います。","respondent":"大関教育総合支援センター長","answer":"対話という考え方、何か、希望を伝えた相手方が「了解です」という部分を「りょ」と入れるだけで通じてしまっている現実もあります。誰にでも伝わる国語力を身につけさせるのが教育であると考えておりますので、しっかりと正確な言葉遣いも含めて教えていきたいと考えております。","id":"exchange-163"},{"speaker":"大沢委員","kind":"質問・要望","question":"やはり発信力、それと物事を考える思考力等々が必要となってくるわけですけれども、ここのところを養うにはどのようなものが必要であるのか。それで、学校現場で養うために、活動が行われているのか、現状を教えてほしいと求めました。","respondent":"大関教育総合支援センター長","answer":"２つに分かれた考え方があろうかと思いますが、発信という面だけでご説明いたしますと、説明をどのように。まず何よりも相手の目を見て、自分の伝えたいことを、必要に応じては補足も加えながら説明をする力という部分は必要になります。","id":"exchange-164"},{"speaker":"大沢委員","kind":"意見","question":"勉強ができる子は、おそらく私が考えると思うのですけれども、みんなできるのですが、それをいかにして習慣にするかということが大事であると思う。今、２点お話をいたしましたけれど、そこについてのお考えを聞かせてくださいとの意見を述べました。","respondent":"大関教育総合支援センター長","answer":"より正確に自己認識を深めるということは、教育において非常に、日々重要な場面だと考えております。そんな力を高めていきたいと考えております。","id":"exchange-165"},{"speaker":"大沢委員","kind":"質問・要望","question":"そういうものを子どもたちに身につけさせてほしいと求めましたし、いじめとか家庭内の不和とか、お願いしたいと考えています。現状、考えていらっしゃるのですけれども、考えていらっしゃることがあればご披露してほしいと求めました。","respondent":"大関教育総合支援センター長","answer":"市民科の学習です。ステップ１から５までかけて、自分が実践した内容を繰り返し繰り返し、ほかの教科にも十分活かしていけるのではないかと考えております。","id":"exchange-166"},{"speaker":"大沢委員","kind":"質問・要望","question":"これは質問ではないのですけれども、語彙力というのは、しかしながら語彙力も取捨選択しなければいけないと思います。古典文学に触れさせる機会を多くつくってほしいと求めましたので、二歩も前進しますことをお願いいたしまして、私の質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-167"},{"speaker":"石田（秀）委員","kind":"質問","question":"それからもう一個は、３５３ページ、教職員研修というか、教員の指導のことについて伺いたいと思います。どのような形で今これを推し進めてきて、結果としてこういうふうになってきたのだというところについて、改めて見解をお知らせください。","respondent":"大関教育総合支援センター長","answer":"家庭の協力も得ながら、もう日常的に取り組んできた成果が少しずつあらわれて、２３区の中では体力値が上がってきたと認識しております。","id":"exchange-168"},{"speaker":"石田（秀）委員","kind":"質問","question":"ではどうする。いろいろ携わってくれる子どもが増えてくれるのはありがたいのだけれども、こういう今の現状をどう捉えていらっしゃるかというのも説明を求めました。","respondent":"大関教育総合支援センター長","answer":"さまざまなスポーツの人気も時代とともに変化もする中、でも一定の層は、例えば野球が好きなお子さんもいます。全ての学校が同じ条件ではありませんが、希望する部員がいれば、今後とも区のスポーツ協会等との情報共有なども綿密に進めてまいりたいと思います。","id":"exchange-169"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"１日１升、どうして指導員の話をするかというと、こういうこともしていかなくてはいけない。それぐらいは教育委員会で考えて打ち出しても、私は品川区なりの部活動ができると思うので、これの考えを教えていただきたい。","respondent":"大関教育総合支援センター長","answer":"第１回目の今年度は、現在は立正大学で准教授をされている方をお招きして、その方は日本ハムにも指導に行かれている方です。そういったニーズに応えられるような人選を、今後、部活動指導員の採用においては心がけてまいりたいと思います。","id":"exchange-170"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"子どもたちだけではなくて、今度、保護者たちとのコミュニケーション能力も教員に求められていると思う。そういうところをどうお考えになっているかというところだけ説明を求めました。","respondent":"工藤指導課長","answer":"そして、その成果は、すぐ出なくても、１０年後であっても出る。品川区の教育を伝えるとともに、そのことはしっかり伝えるべきであると思いますし、これからもやっていくという考えです。","id":"exchange-171"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"これは要望にしておきます。よりよい子どもをつくれる、生き抜く力をつける子どもたちがつくれるように、品川区の教育をしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-172"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/273075?Template=document&Id=1120#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":135731,"voices":394}},{"id":"r02-20200323-3","meetingId":"r02-c-budget","date":"2020年3月23日","dateIso":"2020-03-23","committee":"予算特別委員会","time":"午前１０時００分～午後 ５時４５分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を125件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"本多委員","kind":"質問","question":"そして、補正予算について伺います。そして、３点目は、基金を活用しての財政的支援についてはどのようなお考えか、考え方、方針について説明を求めました。","respondent":"堀越企画部長","answer":"保健衛生面での対応はもとより、今、令和２年度当初予算の補正も必要であると考えています。そういった経済対策を打っていく中で、これまで健全財政で培ってきた基金を十分に活用していきたいと、このように考えているところです。","id":"exchange-001"},{"speaker":"本多委員","kind":"質問・要望","question":"４点目は、これをやります、あれをやりますという取り組みが決まってから制度設計にかかる時間というものがどのくらいかかるのか。スピーディーに進めてほしいと求めましたが、制度設計の時間について説明を求めました。","respondent":"堀越企画部長","answer":"今後、まだ検討という形になりますけれども、９月議会等での補正予算のご提案というのも視野に入れながら検討をしていく必要があると思ってあります。","id":"exchange-002"},{"speaker":"本多委員","kind":"質問・要望","question":"進めていただきたいと思うのですけれども、区独自の取り組み、上乗せという部分についてはいかがでしょうか。事業によっては時期を前倒しして取り組むとか、そういった場面も出てくるかと思いますが、取り組みの前倒しなどについても説明を求めました。","respondent":"堀越企画部長、品川財政課長","answer":"制度設計等に関するご質問ですが、国や都と連携をしてということがまず基本ですが、そういった上乗せ等についても検討していきたいと思ってあります。身近な区でさまざま相談をしていただいて… 昨今の災害の発生等が多い状況の中で、こういった観点も含めながら、今後の予算編成にあたっての予備費については検討していきたいと考えております。","id":"exchange-003"},{"speaker":"本多委員","kind":"質問・要望","question":"現時点でのところで結構なので、その辺を教えてほしいと求めました。それも説明を求めました。","respondent":"品川財政課長","answer":"今後の予備費につきましては、当然、現状想定し得る予算を計上していきたいと考えております。今後どのように活用していくべきかというところも十分に考えながら、予備費は積極的に使っていきたいと、このように考えております。","id":"exchange-004"},{"speaker":"本多委員","kind":"質問","question":"感染するリスクについて、感染患者への予算措置や対応についてはいかがでしょうか。既に産業振興のところでご答弁はいただいておりますけれども、改めて伺います。","respondent":"品川財政課長、久保田地域振興部長","answer":"現在検討中の補正予算の中では、まだまだ不足している状態ですので、こういった費用等を計上していきたいと考えております。感染者の対応につきましては、それから防護服等、こういったところを予算措置していく必要があると考えていま… その支援策といたしましては、迅速に対応しているところでございまして、相談窓口を設けるといったことをスピーディーに進めているところです。","id":"exchange-005"},{"speaker":"本多委員","kind":"質問・要望","question":"それ以外の専門分野の人的配置ですとか、さまざまな専門的なことに対応できる窓口というところではいかがでしょうか。説明を求めました。","respondent":"久保田地域振興部長","answer":"専門相談員を配置いたしまして、通常３名のところを４名増員いたしまして、現在対応しています。１日当たり６０件の相談があるということでございまして、こうした急増する相談にも、専門的な相談員を置いて対応しています。","id":"exchange-006"},{"speaker":"本多委員","kind":"質問・要望","question":"さらに充実を求めます。そういった商店や飲食店に対する課題や対応について、また、支援につきまして、考え方を説明を求めました。","respondent":"久保田地域振興部長","answer":"飲食店や宿泊業の関係ですけれども、品川区内には３,０００ほどの宿泊業、飲食店を営んで事業者があります。支援といたしましては、当面の事業継続ができるような形で、積極的に支援をしていきたいと考えております。","id":"exchange-007"},{"speaker":"本多委員","kind":"質問・要望","question":"休業中の手当１日最大８,３３０円、フリーランス４,１００円、雇用情勢をどう把握しているのかお聞かせください。そうした作業をサポート、助けるための各種団体や同業組合への協力などについて説明を求めました。","respondent":"久保田地域振興部長","answer":"雇用調整助成金等に対する対応として私どもが今考えているものが、雇用情勢は、国の制度の窓口となるハローワークといろいろと今協議をしています。それらに対応するため、社会保険労務士等と連携をいたしまして、中小企業の負担を軽減するということも今考えているところです。","id":"exchange-008"},{"speaker":"本多委員","kind":"質問","question":"店舗を利用する側の利用者の安心、そして店舗側の安心についてはどうお考えでしょうか。３,０００件で９００万円、５,０００円のものでも３,０００件で１,５００万円、みんなが安心できるような取り組みについてはいかがか尋ねました。","respondent":"久保田地域振興部長","answer":"サービスを提供する際の前提となるものは安心ということで、これは非常に大事な視点であると、私どもも考えているところです。状況を見きわめながら、必要に応じて調査研究をしてまいりたいと考えているところです。","id":"exchange-009"},{"speaker":"本多委員","kind":"質問・要望","question":"私は条例は必要ないと思いますが、自宅待機要請を守ることの徹底、それと、不要不急の外出を控えるお願い、このバランスをどう考えますでしょうか。よかったと私はすごく思いますけれども、こういった部分のバランスについていかがお考えか尋ねました。","respondent":"福内品川区保健所長","answer":"今後も、クラスター対応については、必要時には職員の応援や、東京都の派遣などで確実に対応してまいります。一人一人が自覚を持ち、感染拡大防止に努めていただくよう、保健所としても周知徹底に努めてまいりたいと考えております。","id":"exchange-010"},{"speaker":"本多委員","kind":"質問・要望","question":"これも国や都道府県の動向になるかもしれませんけれども、家庭内感染を防ぐ予算措置だとか、その辺についてはどういうお考えかお聞かせください。こうした問題点についてどういう認識か、また、品川区も何かできることがあるかなど、その見解を説明を求めました。","respondent":"品川財政課長","answer":"こういった家庭内感染を防ぐときのアドバイス体制やコールセンターの体制等は予算等で充実していきたいと。このように考えております。","id":"exchange-011"},{"speaker":"本多委員","kind":"質問","question":"状況は違いますが、自然災害による国の災害廃棄物処理予算は６６億円、３５８億円、６２４億円と、３年連続で大幅に拡大しています。今回のこの事態ではいかがか尋ねました。","respondent":"工藤品川区清掃事務所長","answer":"国の災害廃棄物処理予算の増加につきましては、やはり近年の国内における災害廃棄物の増加に伴うものと認識しています。引き続きやはり災害廃棄物の処理にあたりましても万全の体制をとっていけるよう、ふだんから準備を進めてまいりたいと考えております。","id":"exchange-012"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"そのため、何点か具体的に強く要望し、質問いたします。これは約５億円ぐらいかかると考えていますが、これらに対しての区のお考えを説明を求めました。","respondent":"久保田地域振興部長、安藤文化スポーツ振興部長、伊崎福祉部長","answer":"春に４億円、秋に４億円という予定で考えてございましたが、こうしたものにつきましても予算の組みかえが必要ではないかという認識をしています。今後… 区は当然ですけれども、地域の観光事業者ならびに観光団体の皆さんと品川区観光振興協議会の皆様で、水辺の活性化について取り組んでまいりました。その中… これについては広報等にも載せていく予定です。","id":"exchange-013"},{"speaker":"石田（秀）委員","kind":"質問","question":"今は区民の安心・安全、感染拡大防止、その後の準備を迅速に進めるということで今質問しておるつもりであります。こういう発言がこういうときには必ず必要だと思っておりまして、その部分について区長から発言があればありがたいと考えています。","respondent":"濱野区長","answer":"あるいは区内の商店、いろいろと検討しながら、有効な使い方をしていきたいと思っているところです。これからもそうした心構えで仕事をしていきたいと考えています。","id":"exchange-014"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"次に、品川区のコミュニティバス導入についてお伺いしたいと思います。各候補ルートの地域の皆様にもちろん説明をして、意見を聞く機会を設けると思いますが、その点をお伺いさせてほしいと求めました。","respondent":"中村都市環境部長","answer":"引き続きさまざまな説明を継続してまいりたいと考えております。プロポーザルへの参加見込みについてですが、バス事業者にプロポーザルで提案をいただくための前提条件をこれから検討してまいります。","id":"exchange-015"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"毎年度１億円を超える負担をしても継続するべきだという議論になりかねないと私は思っておりますので、そこら辺も、それが必要だと考えています。そこら辺のところも地域にどのように話して、どのように一緒になってやっていけるか、改めてその点をお聞かせほしいと求めました。","respondent":"中村都市環境部長","answer":"地域交通検討会、地域の方々への説明や意見を伺う機会を設けて、そして最終的に決定していくというプロセスで行っていきたいと考えております。さまざまアイデアはあると思いますけれども、これは運行前あるいは運行後もいろいろ工夫して考えていきたいと考えています。","id":"exchange-016"},{"speaker":"石田（秀）委員","kind":"提案","question":"平成２０年４月、議員提案によりまして、品川区文化芸術・スポーツのまちづくり条例が施行されました。この１０年間の評価と課題、どのような考えでこれを進めていかれようとしているのか、それをお伺いをしたいと思いますとの意見を述べました。","respondent":"安藤文化スポーツ振興部長","answer":"今、委員がご説明されました、平成２０年に議員提案により品川区文化芸術・スポーツのまちづくり条例ができています。今言いました、これを速やかに生活の中に取り入れていくようなものをこの１０年間でもっと深く考えていきたい、実践していきたいと考えています。","id":"exchange-017"},{"speaker":"石田（秀）委員","kind":"意見","question":"２０１９年のラグビーワールドカップ、そして今年のオリンピックはどうなるかわかりませんが、Ｖ字回復にもつながるのだろうと考えています。こういうことでの企業との連携、それから集客力、こういうことも含めた考え方を改めてお聞かせ願いたいと思いますとの意見を述べました。","respondent":"安藤文化スポーツ振興部長","answer":"そういうことから、東京２０２０大会が、どうなるかわかりませんけれども、機運醸成に努めてまいりました。スポーツを通じた地域の活性化、スポーツの持つ力を活かした振興計画にして、東京２０２０大会のレガシーを残していきたいと考えています。","id":"exchange-018"},{"speaker":"鈴木（博）副委員長","kind":"質問","question":"本日は、現在も流行が続く新型コロナウイルス感染症についてお伺いいたします。新型コロナウイルス感染症の発生の経過についてご説明をお願いします。","respondent":"福内健康推進部長","answer":"国内の感染者数は、現在のところ１,１００名を超えており、また、世界中でも、感染者数、また、死亡者数も日々増加するといったような状況です。いまだ感染源についてはわからないという状況です。","id":"exchange-019"},{"speaker":"鈴木（博）副委員長","kind":"質問","question":"０歳から９歳の子どもでは死亡率が０％であったのに対し、年齢が上がるにつれて死亡率が高くなり、８０歳以上では１４.８％の方が死亡しています。この新型コロナウイルス感染症の診断と治療について、ご説明をお願いします。","respondent":"福内健康推進部長","answer":"咽頭または鼻腔拭い液をＰＣＲ検査し、陽性の場合、感染者と診断されます。治療法については、現在さまざまな既存の治療薬を試みるなど、開発途上です。","id":"exchange-020"},{"speaker":"鈴木（博）副委員長","kind":"質問","question":"１、徹底した感染予防の取り組みは、品川区では現在どのように行われているのでしょうか。３、万が一新型コロナウイルス感染症が発生し、デイサービスを閉鎖した場合の在宅介護の支援方法は、現在どのように検討されているのか尋ねました。","respondent":"伊崎福祉部長","answer":"２点目の受入体制ですけれども、状態に応じて対策を徹底し、サービスの継続利用が可能となるように考えているところです。退院後の生活にご心配がある場合は、高齢者福祉課または在宅介護支援センターにご相談いただき、適切に対応します。","id":"exchange-021"},{"speaker":"鈴木（博）副委員長","kind":"質問","question":"第２に、子どもに対する対策についてお伺いします。特に保護者への感染予防の一般的な啓発が重要と思われますが、現在保護者に対してどのような対応が行われているのか尋ねました。","respondent":"福島子ども未来部長","answer":"速やかに対応できるように、保育課や保育園職員、さらには保健所等の役割を明確にした対応フローを作成しております。具体的には、情報の収集、対策会議の設置、保護者への連絡、園内の消毒作業、さらに訪問保育等を実施する、そのようなフローを決めているところです。","id":"exchange-022"},{"speaker":"鈴木（博）副委員長","kind":"質問・要望","question":"君たちが行ったことは、ありがとうというような、子どもを勇気づけ励ますようなメッセージを発信することはできないものなのでしょうか。今回の新型コロナウイルス感染症の流行が、今後の学校現場における感染症予防教育にどのように活かされるのか、お伺いしたいと思います。","respondent":"本城教育次長","answer":"今回の新型コロナウイルス感染症対応にあたりまして、現在、全校の一斉の臨時休校等、緊急的な対策をしています。いじめの未然防止を含め、人権感覚を養うことにつなげていくような、そのような広がりのある内容もあわせて必要であると考えているところです。","id":"exchange-023"},{"speaker":"鈴木（博）副委員長","kind":"質問","question":"区は、帰国者・接触者外来を持つ中核医療機関と一般診療所を支えるために、どのような対策をお考えでしょうか。区は電話での相談体制など、どのような支援体制の構築を現在お考えなのか尋ねました。","respondent":"福内健康推進部長","answer":"感染地域からの帰国者には、検疫から情報提供がございまして、保健所から１４日間の健康観察を実施しているところです。軽症者への支援体制も含め、今後、東京都の方針を受け、医師会等とも必要に応じ協議や周知を図ってまいります。","id":"exchange-024"},{"speaker":"鈴木（博）副委員長","kind":"確認","question":"さらに、発熱が４日以上かどうか、倦怠感や呼吸困難があるかどうか、慢性の持病があるかどうかを確認します。これは先ほど別の委員も質問されていましたが、増員に関して区のご見解はいかがか尋ねました。","respondent":"福内健康推進部長","answer":"品川区の帰国者・接触者電話相談センターの人員体制ですが、看護師、保健師５名と、事務１名で対応しております。呼吸器症状や発熱が４日以上続くなど、このセンターにおける振り分けというのは適切に行われているのではないかと認識しております。","id":"exchange-025"},{"speaker":"鈴木（博）副委員長","kind":"意見","question":"保護者の方に新型コロナウイルス感染症に対する知識をどこで得ているかアンケート調査を行ったところ、９５％がテレビ情報だったということでした。風評被害、特にテレビ情報に対する品川区の見解等、この誤った情報に対する対応についてお尋ねしますとの意見を述べました。","respondent":"福内健康推進部長","answer":"今後の保健所の業務も当然拡大をしていくと考えておりますけれども、全庁的に応援も受けて対応してまいりたいと考えております。今後とも、医療体制などの状況の変化に応じまして、適切な情報提供や広報に努めてまいります。","id":"exchange-026"},{"speaker":"大倉委員","kind":"質問・要望","question":"私からは、まず、環境対策について伺わせてほしいと求めました。地域の方、事業者等への周知を行っていくことが必要と考えますが、今後の取り組みについてもあわせてお知らせください。","respondent":"中村都市環境部長","answer":"そのために区が率先して取り組むことも必要ですし、区民への啓発がこれから重要なものであると考えています。現在、戸越公園内に環境学習交流施設の設置を検討しておりますけれども、引き続き環境へ配慮した取り組みを進めてまいりたいと考えています。","id":"exchange-027"},{"speaker":"大倉委員","kind":"質問","question":"建物のエネルギー効率をよくすることで省エネを進め、なおかつ、消費をゼロにするＺＥＢの認証をとれるよう設計を進められていると伺っております。これが取得されれば、都内で初となるような取り組みであるということも伺っておりますが、その点もあわせてお知らせください。","respondent":"中村都市環境部長","answer":"一層区における環境の取り組み、こういったものを進めるということと、区外へのＰＲ効果も期待できると考えております。説明を掲示したりですとか、そういった機会になるとも考えておりますので、目指しています。","id":"exchange-028"},{"speaker":"大倉委員","kind":"質問","question":"区が今後設置する建物において、積極的なＺＥＢの認証について、区はどのような姿勢で取り組んでいかれるのでしょうか。ＺＥＢ Ｒｅａｄｙなどさまざま取り組みがあると思いますが、どのようにそれを進めていくのかお知らせください。","respondent":"中村都市環境部長","answer":"理想ではありますが、現実的に施設の用途を考えますと、なかなか難しい面もあると思います。さまざま区が地球環境への取り組みを行っている、そういった考え方も、建物の設計に取り入れていけることが重要であると考えております。","id":"exchange-029"},{"speaker":"大倉委員","kind":"質問・要望","question":"学習段階に応じた取り組みなども、区としてしっかりと取り組んでいってほしいと求めましたが、区のお考えをお聞かせください。災害時にも自家発電を行えるため、電気を利用する必要のある活動の場として利用できるのではないかと考えますが、お考えを説明を求めました。","respondent":"中村都市環境部長","answer":"防災拠点としての考え方ですけれども、その避難所を補完する、そういった使途について検討できると考えております。７２時間の対応ができる蓄電池の設置ですとか、それから太陽光発電等の創エネ等も今検討していますので、そんな工夫がしていければと考えております。","id":"exchange-030"},{"speaker":"大倉委員","kind":"質問・要望","question":"今回の質問では、今まで行ってきた取り組みの中から、品川区開催競技のホッケーの取り組みについて伺いたいと思います。ホッケー体験についても継続を望む声が多いと伺っておりますが、今現在、品川区にどのようなお声が届いているか尋ねました。","respondent":"安藤文化スポーツ振興部長","answer":"継続してやっていただきたいという声も届いていますし、また、大会が終わった後の交流事業等も継続していきたいという声も届いてあります。そんな中で、東京２０２０大会が終わった後も、ホッケーをレガシーとして取り組んでいきたいと考えています。","id":"exchange-031"},{"speaker":"大倉委員","kind":"質問・要望","question":"オリンピックの競技として大会が開催される会場でありますので、ぜひともこうした会場利用について知っていただきたいと考えています。そして、子どもたちがそういったものを観戦することでさらにホッケーを頑張っていく、最後にそうした取り組みについてご答弁をお願いいたします。","respondent":"安藤文化スポーツ振興部長","answer":"オリンピックを開催した後も、品川区内に競技場があるということを活かして、ホッケーの継続した盛り上げを私どももしていきたいと考えています。日本ホッケー協会ならびに東京ホッケー協会と協議をしていきまして、引き続きホッケーを盛り上げていきたいと考えています。","id":"exchange-032"},{"speaker":"大倉委員","kind":"意見","question":"野球での甲子園、目指すべき場所としてブランド化していっていただければうれしいと考えていますので、ぜひよろしくお願いいたします。ありがとうございましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-033"},{"speaker":"新妻副委員長","kind":"質問","question":"そこで、品川区の情報発信の方針と、品川区が公表するケースはどのような場合なのか、伺います。そこで、区民が感染に心配があるときは、どのような順序でどこに相談するのか伺います。","respondent":"福内健康推進部長","answer":"関係者から実施以前に報道機関へ情報提供がされてしまい、検査終了後の２月１８日からホームページや施設での周知を行いました。いずれも結果は保健所に届きまして、その後の対応につながるようになってあります。","id":"exchange-034"},{"speaker":"新妻副委員長","kind":"提案","question":"その要望に沿って伺っていきます。安心につながるよう、区のホームページには新型コロナウイルス感染症対策本部会議の開催状況を載せてはどうかと提案いたしますとの意見を述べました。","respondent":"福内健康推進部長、榎本総務部長","answer":"企業や事業所から、社員で陽性者が出たとき会社はどう対応するのかといったようなご相談等々があります。職員体制は、区の保健師、事務職のほか、派遣職員も含めまして、６名で対応しています。 区のホームページの情報発信につきましては、既に対策本部をつくる前の１月２４日から適宜実施してきたところです。ただ、今後は対策本部会議の開催状況についても区ホームページで周知し、タイムリーな情報発信に努めてまいります。","id":"exchange-035"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"今確認をさせていただきましたが、一層の区民の不安が取り除かれますよう、増員を含めた相談体制の拡充を求めます。区の見解を伺います。","respondent":"福内健康推進部長","answer":"感染症対策の長期化を視野に、相談体制については充実を図ってまいります。全庁的な応援等も受けながら、丁寧に区民の不安に寄り添っていきたいと考えています。","id":"exchange-036"},{"speaker":"新妻副委員長","kind":"質問","question":"品川区議会公明党が、新型コロナウイルス感染症に関して団体や区民のお声を伺った際、細かくお聞きいたします。さらに、妊産婦への配布の考え方も伺います。","respondent":"榎本総務部長","answer":"それから、今後の必要数ですけれども、一月当たりの必要数は約３０万枚と見込んでおります。それから、妊産婦へのマスクの配布ですが、現時点では備蓄の数に限りがあることから、一般区民への配布は難しいと考えているところです。","id":"exchange-037"},{"speaker":"新妻副委員長","kind":"確認","question":"各所管課、各施設での十分な備蓄を前もって検討するべきであると考えますが、いかがでしょうか。見解を伺います。","respondent":"榎本総務部長","answer":"ただ、備蓄はやはりそれなりの場所をとりますので、その辺も含めて検討していきたいと考えています。備蓄の目的が損なわれない範囲内で緊急時には対応する必要があると考えておりまして、それは先ほども言いましたところに配布を行っているものです。","id":"exchange-038"},{"speaker":"新妻副委員長","kind":"質問","question":"現在、区主催のイベントや行事は、開催の中止や延期となっていますが、今後の開催の考え方を伺います。町会や自治会等で区から補助金、助成金を受けていたイベント等が中止になった場合の考え方を伺います。","respondent":"榎本総務部長、久保田地域振興部長","answer":"イベントの今後の開催の考え方ですけれども、それぞれイベントをする場所、会場や規模、参加者の特性などを勘案して判断をしてきたところです。今後は… あわせまして、キャンセル料等がかかったものにつきましても、返金は求めずにそのまま助成金等を執行します。そういったものについては、補助金の中で精算をさせていただいて、返金をしていただくという考えで今進めているところです。","id":"exchange-039"},{"speaker":"新妻副委員長","kind":"質問","question":"３点目に、学校における学習の遅れに関しての認識や、文部科学省の学習支援コンテンツポータルサイト等の活用推進について伺います。４点目に、居場所や食を提供している子ども食堂の状況と、品川区の考え方を伺います。","respondent":"福島子ども未来部長、本城教育次長","answer":"現在２４か所のこども食堂の中で、今日現在で通常開催が４か所、臨時の対応を行っているのが３か所となっております。今後も、品川区社会福祉協議会のしながわ子ども食堂ネットワーク事務局と連携しながら… １人１台のタブレットパソコンの貸与を行い、そのほかの学校におきましては、できる限りの学習支援に努めているところです。それでも遅れがある場合につきましては、新学期に補習を行うなどの工夫も必要であると認識しています。","id":"exchange-040"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"そこで、小・中学生の春休み期間中の居場所の確保と、新学期が始まるまでの学習機会の確保や意欲の向上のための支援を要望いたします。見解を伺います。","respondent":"本城教育次長","answer":"２５日までとしていますが、ＰＴＡによる校庭開放を継続するなど、例年どおりの対応をしてまいるところです。学習意欲に関する支援につきましては、各学校は２５日に予定している修了式の際には、新学期に向けた丁寧な対応に努めてまいるところです。","id":"exchange-041"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"品川区は丁寧でわかりやすい積極的な周知にどのように取り組まれますでしょうか。示されている支援策等に当てはまらない方がいらした場合は、機敏に対応していただきたいと要望しますが、見解を伺います。","respondent":"伊崎福祉部長","answer":"区で今後行います支援策も含めて、一元化をして暮らし・しごと応援センターでご紹介をできるように努めてまいります。各所管から暮らし・しごと応援センターへきちんとつないでもらえますように、連携をとりながら支援を進めていきたいと考えております。","id":"exchange-042"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"品川区議会公明党は、２００３年から一般質問、予算特別委員会で大井競馬場でのホースセラピーの実施を要望してきました。この事業への参加時期もあわせて伺います。","respondent":"本城教育次長","answer":"そして、小学校１校で昨年に引き続いて実施したものと、小・中・義務教育学校合わせて６校から特別支援学級の児童・生徒が参加をしたところです。参加時期につきましては、競馬開催のない日であれば通年いつでも可能と聞いておりまして、各校の希望で参加できる状況です。","id":"exchange-043"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"視察には、東京都競馬株式会社、品川区教育委員会とも懇談されたと伺っています。１回だけではなく複数回開催し、ホースセラピーにつながるモデル授業を要望いたしますが、ご所見を伺います。","respondent":"本城教育次長","answer":"ご提案のモデル授業についてですが、近隣校の特別支援学級からは定期的に参加したいとの声も聞いているところですので、大学との連携も含めまして、効果的な取り組みとなるよう検討していきたいと考えているところです。","id":"exchange-044"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"近隣校からのこういう要望もあるです。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"},{"speaker":"塚本委員","kind":"質問・要望","question":"区内で影響を受けている事業者への財政的な支援と相談窓口の設置を求めました。区の見解を伺います。","respondent":"久保田地域振興部長","answer":"次に、経営変化対策資金を引き続き実施いたしまして、経営状況に変化があらわれた事業者への速やかな資金調達を支援してまいります。あわせまして、経営支援資金や経営安定化資金の要件にセーフティネット保証４号を加えるほか、支援を続けてまいります。","id":"exchange-046"},{"speaker":"塚本委員","kind":"質問・要望","question":"迅速に新型コロナウイルス感染症の区内事業者への影響に対して、今、支援がなされているということが確認できました。必要な人材の確保とあわせて、相談窓口の体制強化について見解を求めます。","respondent":"久保田地域振興部長","answer":"現在、４月からは７名体制に拡充をさせていただいて、１日当たり１００件程度の相談に対応できる体制とする予定であります。臨時の相談窓口を設けるなどしまして、スピーディーに対応できるよう、体制強化に努めてまいります。","id":"exchange-047"},{"speaker":"塚本委員","kind":"質問","question":"すみません。人材の確保の考え方についてもあわせて伺いましたので、お願いいたします。","respondent":"久保田地域振興部長","answer":"委託等も行いまして、大体７名体制で行うということですけれども、常時７名で相談が受けられるような形で専門員を集めて相談体制を強化していきたいと考えています。","id":"exchange-048"},{"speaker":"塚本委員","kind":"質問・要望","question":"漏れることなく的確に案内するために、区はどのように取り組んでいくお考えなのか伺いたいと思います。雇用調整助成金の申請など、相談者の負担が増すことがないということに配慮していただいた相談がなされるといったことを求めたいと思います。","respondent":"久保田地域振興部長","answer":"次に、ワンストップによる対応は重要な視点であると考えておりまして、私どももそのような支援を行っていきたいと考えているところです。社会保険労務士の方々と連携いたしまして、無料相談窓口や申請書類の作成、申請代行を行っていくということを考えているところです。","id":"exchange-049"},{"speaker":"塚本委員","kind":"質問・要望","question":"今の雇用調整助成金の申請を社会保険労務士等にお願いをしてというところでの考え方は、大変に評価できるものだと思いますけれども、この相談窓口の件数というか、規模とか、あるいは場所とか、そういったことについてもう少し何かわかれば教えてほしいと求めました。","respondent":"久保田地域振興部長","answer":"例えばの話ですが、武蔵小山にあります創業支援センター等、中小企業の振興にかかわる施設等で相談を受けるということも一つの案かと思っています。","id":"exchange-050"},{"speaker":"塚本委員","kind":"質問・要望","question":"売り上げが過去の実績より５％以上減少していることなどがありますけれども、事業者の中には、こういった実情もあるかと思います。これまでもこれは確認されてきたことですけれども、それから、事業者の実情に応じて柔軟に対応するという点について求めたいと思いますけれども。","respondent":"久保田地域振興部長","answer":"品川区商店街連合会や東京商工会議所品川支部と連携・協力をいたしまして、必要としている方に行き届くように、積極的に周知に努めてまいります。予約表など、そういったものを相談員と確認するなどしまして、柔軟な対応に努めているところです。","id":"exchange-051"},{"speaker":"塚本委員","kind":"質問・要望","question":"そのために、まず、区内の経済状況を、この先４月・５月と注視して、必要なところに必要な支援を検討すべきと考えます。その把握した結果、どのように次の経済対策といったものを反映していくのか、伺います。","respondent":"久保田地域振興部長","answer":"それによりますと、既に影響が出ている、また、今後影響が出そうであるという回答が約７割を超えているですので、大変厳しい状況にあるです。","id":"exchange-052"},{"speaker":"塚本委員","kind":"質問・要望","question":"そのタイミングというのももう少し、款別審査の中でも、予備費の３億円を活用して経済支援を実施するといったお話は出ておりました。財源としては財政調整基金ということが取り上げられておりますが、この財源の考え方についても、改めて区の見解を説明を求めました。","respondent":"堀越企画部長","answer":"当面はやはり資金繰りにしっかりと対応していくということ、事業継続を図っていくということを考えてあります。財源につきましては、ご質問にもございました財政調整基金等をしっかり活用しながら対応していきたいと。","id":"exchange-053"},{"speaker":"塚本委員","kind":"質問・要望","question":"春、秋に４億円ずつということで計上されておりますけれども、しっかりと検討していただきたいと要望をさせてほしいと求めました。木密地域不燃化１０年プロジェクトの５年延長に際して、令和２年度に期間終了を迎える密集住宅市街地整備促進事業の延長についての見解を伺います。","respondent":"中村都市環境部長","answer":"この１０年プロジェクトの延伸、現在区が取り組んでいる木密事業につきましても、現在実施中です。木密事業の延伸については、検討を行ってまいります。","id":"exchange-054"},{"speaker":"塚本委員","kind":"意見","question":"この事業の内容の説明をお願いいたします。木密地域不燃化１０年プロジェクトの新たな地区指定も含めて、これにより区内の防災性の向上をどのように果たそうとしているのか、説明を求めました。","respondent":"中村都市環境部長","answer":"それから、木密地域全体に対して行っていく考えではありますけれども、検討を行っていきたいと考えております。一軒一軒進める必要がありますけれども、可能な限り少しでも前へ進むようにこれからも取り組んでいきたいと考えております。","id":"exchange-055"},{"speaker":"塚本委員","kind":"質問・要望","question":"海外の研究で、今後、いつまでも健康で生きがいを持った人生を送れるような政策が求められます。今後、ボッチャを高齢者クラブなどで推奨し、将来的には区内で大会を開催することも検討してはいかがか尋ねました。","respondent":"伊崎福祉部長","answer":"ボッチャですけれども、屋内の比較的小さいスペースで実施できることから、高齢者も気軽に楽しめるスポーツだと認識しております。来年度、高齢者クラブの会長の皆様を対象に、ボッチャの講習会を実施する予定としております。","id":"exchange-056"},{"speaker":"塚本委員","kind":"質問・要望","question":"しな助は５００人を目標に募集していると聞いていますが、大会後のレガシーとして、しな助を区内ボランティアの活性化につなげていただきたい。マッチングしていくために、どのような取り組みが考えられるのか、区の見解を伺います。","respondent":"安藤文化スポーツ振興部長","answer":"しな助のボランティア活動が大会終了後も続くように、ご本人の希望に沿ったマッチングができるようなことが大切であると考えています。情報提供を行い、大会のレガシーとしての幅の広い地域ボランティアの活性化につなげていきたいと考えています。","id":"exchange-057"},{"speaker":"のだて委員","kind":"質問・要望","question":"私からは、新型コロナウイルス感染症対策と羽田新飛行ルートの中止を求めて質問します。区が学校給食納品店の補償をすべきですが、いかがか尋ねました。","respondent":"福島子ども未来部長、本城教育次長","answer":"国の方針や区内の感染症の状況を見きわめつつ、適切に利用していただく方法について検討しております。春休みをめどに何らかの措置ができるよう、調整を行っているところです。国におきましても、学校給食の食品納入業者の対応といたしまして、補助金を交付するなどの考え方が示されているところです。","id":"exchange-058"},{"speaker":"のだて委員","kind":"質問・要望","question":"丸一日授業が潰れ、事前の過去問題練習に時間をとられる４月の全国一斉学力テストは延期でなく中止にし、時間を確保できるよう、国に求めるべきです。いかがか尋ねました。","respondent":"本城教育次長","answer":"区の学力調査につきましては、通常の授業が実施される状況であれば、予定の期日で実施するように考えているところです。失業や倒産などにより急激に所得が減少した場合などには個別の相談にも応じておりますので、今回も同様に対応してまいりたいと考えているところです。","id":"exchange-059"},{"speaker":"のだて委員","kind":"質問・要望","question":"イベント中止要請が演劇、芸能、音楽などにもたらした実害を補償するよう国に求め、当事者である区としても支援すべきです。いかがか尋ねました。","respondent":"久保田地域振興部長、安藤文化スポーツ振興部長","answer":"当面の企業の資金需要に応じるという形で、経営変化対策資金の融資あっ旋をスピーディーに進めるということが重要だと認識しています。直接、固定費を補助する考えはございません。 私からは、演劇など文化的な興行の中止についてご説明します。国の補償ですけれども、国の動向を注視しつつ、国から補償について何か示されれば、必要に応じて、私どももしていきたいと考えています。","id":"exchange-060"},{"speaker":"のだて委員","kind":"質問・要望","question":"消費を下支えし、住民の所得を増やし、低所得者と中間層への力強い支援策として、消費税５％への緊急減税を国に求めるべきです。命を守る体制の充実、保健師の増員を求めますが、いかがか尋ねました。","respondent":"品川財政課長、榎本総務部長","answer":"消費税率のことにつきましては、国税のあり方に関することです。国において議論されるべきものであり、減税を国に求める考えはございません。 保健師の体制ということですけれども、この間ずっと採用しながら計画的に保健所の体制を充実するよう努力しております。なかなか増えない状況にありますけれども、今後も継続して増員を図っていきたいと考えています。","id":"exchange-061"},{"speaker":"のだて委員","kind":"質問・要望","question":"なぜ中止を求めないのかの質問に、区は、国がさまざまな意見を受けとめ対応することを前提に実施と答弁し、理由を答えませんでした。改めて、なぜ区長は中止を求めないのか、伺います。","respondent":"中村都市環境部長","answer":"国が平成２６年に新飛行計画を公表しておりますが、騒音環境の低減の取り組み、そして説明を継続して求め続けてまいりました。区といたしましては、引き続き国の取り組みが約束どおり継続して行われるよう、しっかり求めていく考えです。","id":"exchange-062"},{"speaker":"のだて委員","kind":"質問・要望","question":"なぜ区長が答弁しないのでしょうか。区に責任はないと考えているのか、伺います。","respondent":"中村都市環境部長","answer":"区としまして、やはり区民の影響を可能な限り小さくするといった取り組みが必要だと考えております。したがいまして、これからも区民のために、区は寄り添って、国と正面からしっかりと話をしていかなければいけないと考えております。","id":"exchange-063"},{"speaker":"のだて委員","kind":"質問・要望","question":"こうした指摘を受けて、今でも高度変更を求めたのは正しいと考えているのか、伺います。３.５度は、区も国と同じ安全との考えなのか、伺います。","respondent":"中村都市環境部長","answer":"こちらにつきまして、区としましては、かねてから騒音環境の軽減に向けた取り組みを求めておりました。これらの実施に伴う安全性については、区としては騒音軽減と安全対策をあわせて検討された上での、この高度の引き上げが行われたと認識をしています。","id":"exchange-064"},{"speaker":"のだて委員","kind":"意見","question":"昨年の５月には、ロシアの尻もち事故で４１人が犠牲になりました。実機飛行の騒音測定で８０デシベルを超えた場所と、その地点での飛行機の試算高度、その高度の国の推計騒音値をそれぞれお答えくださいとの意見を述べました。","respondent":"中村都市環境部長","answer":"国の測定局では、東京都下水道局南部下水道事務所で２月４日、８１デシベルを記録したです。区の測定、８１.３デシベルの時点では、高度が４７５メートルですが、国の測定地点での高度というものは、区としては把握しておりません。","id":"exchange-065"},{"speaker":"のだて委員","kind":"質問","question":"国土交通省が大井町で８０デシベルと説明してきたのですから、大井町に騒音測定器を設置すべきです。特にきゅりあんの屋上はいかがか尋ねました。","respondent":"中村都市環境部長","answer":"区といたしましても、この測定結果については、しっかりと説明を受けていきたいと考えております。こうした理由から、飛行経路のできるだけ近くの公共施設の中で決定をしたです。","id":"exchange-066"},{"speaker":"のだて委員","kind":"質問・要望","question":"３月２９日から実施延期を国に求めるべきです。いかがか尋ねました。","respondent":"中村都市環境部長","answer":"国からは、夏ダイヤがまだ確定しておらず、羽田空港機能強化により増便する予定の就航数の減はまだまとまったものがないです。国に対して求めてまいりましたが、さらなる国の引き続きの取り組みと丁寧な説明、情報提供を求めてまいる考えです。","id":"exchange-067"},{"speaker":"のだて委員","kind":"質問・要望","question":"そうしたもとで、２９日からの本格実施を行っていくのは、あまりに無謀ではないでしょうか。最後に改めて区長の答弁を求めたいと思いますが、いかがか尋ねました。","respondent":"中村都市環境部長","answer":"区民の安全と騒音対策の取り組みにつきましては、いつでも復便ができるように今回実施をしていくというところが、国の考えとして示されました。これからもしっかりと国には、影響が特に大きい品川区に対して、手厚く対応していただくように求めてまいりたいと考えております。","id":"exchange-068"},{"speaker":"のだて委員","kind":"質問・要望","question":"区長の要望で、危険な急角度の着陸が行われ、騒音の軽減にもならず、実際は想定以上。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-069"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"毎年値上がり続けている国民健康保険料の引き下げ、子どもの国民健康保険料無料化を求めて質問いたします。経年的に見て、さまざまな制度改悪がされてきたこの１１年間で、国民健康保険料がどれだけ値上げされてきたか伺います。","respondent":"福内健康推進部長","answer":"約２倍となっております。年収５００万円の場合、平成２１年度は３２万８,５０５円であり、令和２年度は５９万９,８４６円で、約１.８倍です。","id":"exchange-070"},{"speaker":"石田（ち）委員","kind":"質問","question":"国民健康保険制度を継続させるためにも、住民の負担軽減のためにも、引き下げこそすべきですが、いかがでしょうか。多くの方にも理解が得られることだと思いますけれども、いかがか尋ねました。","respondent":"福内健康推進部長","answer":"国から法定外繰入金を解消するよう求められており、区独自の実施は非常に困難と考えております。引き続き、特別区長会および全国知事会を通して国に求めてまいります。","id":"exchange-071"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"実施ができるお金もあるのに、なぜやらないのか、伺います。こういう支援策と何が違うのか、伺いたいと思います。","respondent":"福内健康推進部長","answer":"多子世帯の支援につきましては、制度の構造的な問題等も含め、国に対して要望書を提出しています。子どもの保険料軽減につきましては、２３区共通の課題であり、品川区独自の実施は現在のところ考えてございません。","id":"exchange-072"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"国民健康保険の世帯・国民健康保険ではない世帯、同じ考えではないのでしょうか。伺います。","respondent":"福内健康推進部長","answer":"国から決算補填等目的の法定外繰入金を解消するよう求められており、特別区では６年間の解消計画を立てて、法定外繰入金を段階的に縮小する予定です。そのため、これ以上の一般財源の繰り入れは考えてございません。","id":"exchange-073"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そして、なぜ取ることにしたのか、理由を伺います。滞納者の滞納の理由として多い順から５つ説明を求めました。","respondent":"福内健康推進部長","answer":"延滞金の概要ですが、期限内納付の推進を目的に実施をするものです。１人当たりの医療費が増加するなど、都の指導検査においても指摘があり、国民健康保険加入者の負担の公平性を確保する運用を開始するものです。","id":"exchange-074"},{"speaker":"石田（ち）委員","kind":"質問","question":"財政状況を考慮してという答弁でしたけれども、なぜ取ってこなかったのか。６０年間取ってこなかったわけですから、ここが重要だと思うのですけれども、そこをもう一度、なぜ取ってこなかったのか、理由を伺います。","respondent":"福内健康推進部長","answer":"延滞金につきましては、これまで区における滞納状況を考慮して、運用をしておりませんでした。","id":"exchange-075"},{"speaker":"石田（ち）委員","kind":"質問","question":"支援策を紹介してつなげるなど、どうやって生活を立て直し、生活再建策を示して支援していくことこそ自治体のすべきことなのではないでしょうか。伺います。","respondent":"福内健康推進部長","answer":"相談の際に、さまざまな支援が必要と思われる場合には、法テラスや福祉の窓口を案内し、生活再建の支援も行っています。その結果、納付が明らかに困難な場合には、納付猶予や執行停止等も実施しています。","id":"exchange-076"},{"speaker":"石田（ち）委員","kind":"質問","question":"そういう人たちに課す延滞金徴収はやめるべきです。それについて、区はどのような対応をされるのか、伺います。","respondent":"福内健康推進部長","answer":"その中に、国税、社会保険料の納付の猶予等があることは認識をしています。今後な正式の通知など、動きを注視してまいります。","id":"exchange-077"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"国民健康保険料は引き下げて、子どもの均等割は無料にして、そして延滞金の徴収はやめるべきと強く求めて、次の質問に移ります。そして、Ｄ案は、品川区とＪＲ、日建設計の３者の検討によって出てきたものなのか伺います。","respondent":"榎本総務部長","answer":"今、委員ご指摘の平成２９年の検討委託の中からということですが、これは違います。それから、３者の検討によって出されてきたのかというのも違います。","id":"exchange-078"},{"speaker":"石田（ち）委員","kind":"質問","question":"それが今、４割も削られた狭い土地になることを、品川区とＪＲと日建設計の３者だけで勝手に決めてしまったということになるのではないですか。伺います。","respondent":"榎本総務部長","answer":"今まで検討してきたのは、広町地区の再開発のほうの検討をしてきたと認識をしております。敷地の約８,３００平米につきましては、第三庁舎、さらに８,３００平米が使えるという形で示しているものです。","id":"exchange-079"},{"speaker":"石田（ち）委員","kind":"質問","question":"勝手にこの３者でＤ案を決めたということではないのでしょうか。伺います。","respondent":"榎本総務部長","answer":"その中で、令和元年度については、庁舎の現状等、また、ほかの区役所の視察等を行い、検討の候補地として４つ出したものです。ほかに候補地があれば、それでまた検討していきたいと思いますけれども、今現在はこの広町地区が最良の候補地だと考えているところです。","id":"exchange-080"},{"speaker":"石田（ち）委員","kind":"提案","question":"いかがでしょうか。そのための１３地域センターでの住民説明会やアンケートなど、広く意見を聞くことを提案しますが、いかがか尋ねました。","respondent":"榎本総務部長","answer":"これまでも、Ａ案からＤ案までの４つの案は全て、町会・自治会、関係団体に昨年の９月から１０月に、候補地を含めて説明してきたところです。今後も、庁舎機能検討委員会の進捗を見ながら、説明をしていきたいと考えています。","id":"exchange-081"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"区民を置き去りにして、ＪＲとの開発を優先させる今のやり方は間違っています。Ｄ案は撤回し、一から住民参加と情報公開を行い、開発と切り離した庁舎検討を求めて、総括質疑を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-082"},{"speaker":"筒井委員","kind":"質問","question":"品川区の将来ビジョンと課題克服について伺います。総合戦略などを出されるご予定だと存じますが、今後の品川区の将来ビジョンと課題、その課題の克服に向けた取り組みを説明を求めました。","respondent":"堀越企画部長","answer":"令和２年度から新しい長期基本計画をスタートさせるということで、今、最終的な準備を進めているところです。今申し上げたような点を４つの視点という形にまとめまして、これらを克服していくという形で新たな区政をつくっていくというふうに考えてあります。","id":"exchange-083"},{"speaker":"筒井委員","kind":"質問・要望","question":"このＪＰＣによると、品川区の総合ランキングは２３区中８位となっており、できるならばもっと上位を目指していただきたいと考えております。この品川区のランキング結果について、どのように考えておりますか尋ねました。","respondent":"堀越企画部長","answer":"中を見ますと、全部でたしか８０を超える項目があったと思いますが、その中の５６項目で品川区は１０位以内というふうな形になってあります。私どもの一定の取り組みと、そのような形で参考にするという考えを持ちながらも、しっかりと政策を打っていくという考え方です。","id":"exchange-084"},{"speaker":"筒井委員","kind":"質問","question":"それへの受入体制は必要かと思いますが、どのような対応をとっていかれるのでしょうか。至急、濃度低減の対策が必要と考えられますが、どのような対策をとられるのか尋ねました。","respondent":"久保田地域振興部長、中村都市環境部長","answer":"まず、１３か国語に対応したクラウド型通訳サービスを導入いたしまして、そういった手続の円滑化を進めているです。コミュニケーションツールとして、やさしい日本語の講座などを開催いたしまして… 平成１１年から開始されたディーゼル車規制に伴い、減少傾向ではあるものの、まだ基準を超えているです。","id":"exchange-085"},{"speaker":"筒井委員","kind":"質問・要望","question":"品川区が、脱固定化、すなわち中止を求める活動を３月２９日の運用開始と同時に直ちに進めなければならないと考えております。そして実機飛行確認についての区の評価と、また、濱野区長は着陸間隔の調整など音を低減化する具体策を求めたいと述べておりますが。","respondent":"中村都市環境部長","answer":"技術的な検討を含めたものは国が行うべきものというふうに考えているところです。関係区との連携につきましては、例えば教室型説明会の要望など、区ごとに状況は違っておりましても情報共有の大切さを感じているところです。","id":"exchange-086"},{"speaker":"筒井委員","kind":"提案","question":"そうした状況で、区は国に対してしっかりと区民の声や議会での提案、要望を届けているのか、また届けられるのかが心配です。そして正確に区民の声や議員の提案、要望を国に対してしっかりと伝えていただきたいと考えておりますけれども、ご見解はいかがか尋ねました。","respondent":"中村都市環境部長","answer":"区民への丁寧な説明、国の責任と判断で行うべきという考えですけれども、国は区の求めに対して継続して検討していくというふうに回答しています。","id":"exchange-087"},{"speaker":"筒井委員","kind":"質問・要望","question":"品川区としては、騒音軽減のために降下角度を上げることを国に求めて、それに国は応じて降下角度を３.４５度に上げました。しかし、それでは品川区としては、どのように騒音軽減対策を国に求めていくのか尋ねました。","respondent":"中村都市環境部長","answer":"本格運行実施の際には、しっかりと対応していくと、国に対して連絡があったです。南風の好天時に実施されるですけれども、これも３.５度で入って、パイロットによる判断というものもあるというふうに聞いております。","id":"exchange-088"},{"speaker":"筒井委員","kind":"質問・要望","question":"もはや国の説明義務違反ともいえますが、この点はいかがお考えでしょうか。問題があまりにも多いので、区は国に対して一旦見直すべきとして運用の中止を求めるべきと考えますが、いかがか尋ねました。","respondent":"中村都市環境部長","answer":"それによって３度か３.５度か、どちらがいいのかというところにつきましては、区はしっかりと説明を受けていきたいというふうに考えております。","id":"exchange-089"},{"speaker":"筒井委員","kind":"質問・要望","question":"その対策はどうされるのでしょうか。以上の点を国に伝え、誠意ある回答を求めたいと思いますが、いかがか尋ねました。","respondent":"中村都市環境部長","answer":"区といたしましても、こういった声もいただいた場合には国に伝えてまいりたいというふうに思っております。伝えた回答につきましても、しっかりと具体的な対応を示していただくように、国のほうへあわせて求めていきたいというふうに考えてあります。","id":"exchange-090"},{"speaker":"筒井委員","kind":"質問・要望","question":"新飛行ルートによって飛行機が大量に区内を通過することになりますけれども、ＮＯｘやＰＭ２.５の濃度が高まるのではないでしょうか。そうすると、区の濃度抑制の対策にも支障が出ることになり、永続的に空気が汚いままということになりますが、いかがお考えか尋ねました。","respondent":"中村都市環境部長","answer":"これも国からの説明で航空機に対するさまざまな影響について説明があった中で、影響は極めて軽微で限定的であるというような回答です。ただ、実際、飛行確認が行われた７日間の観測に数値につきましては、特に目立った変化はなかったです。","id":"exchange-091"},{"speaker":"筒井委員","kind":"質問・要望","question":"新飛行ルートにより区内のＣＯ２は増加するのでしょうか。ＣＯ２の総排出量を増加させないということを合意し、新飛行ルートはＣＯ２の増加につながり、それぞれご見解を説明を求めました。","respondent":"中村都市環境部長","answer":"しっかりと対応するべきものですので、区といたしましても、そういったところについては求めていきたいというふうに考えております。運行状況の中で、区も先ほど申し上げました測定局もあるですので、可能な限りの注視については行っていきたいというふうに考えております。","id":"exchange-092"},{"speaker":"筒井委員","kind":"質問","question":"こうしたことは区も推進するＳＤＧｓの達成にも反するのではないでしょうか。そこで、区は国に対し、新飛行ルートはＳＤＧｓに反すると伝えるべきですが、いかがお考えか尋ねました。","respondent":"中村都市環境部長","answer":"それぞれの機関において、政府において実際に実施に向けて努力をしていくべきというふうに考えております。ＳＤＧｓの考え方に基づく飛行ルートの本格実施の中での考え方につきましては、区の考えを国に伝えてまいりたいというふうに考えております。","id":"exchange-093"},{"speaker":"筒井委員","kind":"質問・要望","question":"区はこの木更津沖の新型滑走路の建設案を代替案の１つとして国に提示すべきですが、いかがでしょうか。第５滑走路が与える区への影響はあるのか尋ねました。","respondent":"中村都市環境部長","answer":"まだ実際の計画として検討しているというところではないということで、整備、設置につきましては未定です。したがいまして、引き続き情報収集に努めまして、新飛行経路の影響については情報収集に努めてまいりたいというふうに考えております。","id":"exchange-094"},{"speaker":"筒井委員","kind":"質問","question":"木更津沖の新型滑走路については、ご存じなのでしょうか。そうしたことも、今、国は未定ということなのか尋ねました。","respondent":"中村都市環境部長","answer":"木更津沖の滑走路につきましては、これは建設の検討に着手をしたというような話は聞いているところです。ただ、これから国に対してしっかりと確認をしてまいりたいというふうに考えております。","id":"exchange-095"},{"speaker":"筒井委員","kind":"質問・要望","question":"８３９万５,０００円をあげるから区民に新飛行ルートを我慢しろというのでしょうか。以上、３点伺います。","respondent":"中村都市環境部長","answer":"これは区が国に対してこういった取り組みを行いたいという提案を行って、国が助成の決定をしたというものです。今回の新飛行ルートを契機といたしまして、こういった助成制度に応募してみようというところで助成制度を活用し始めたです。","id":"exchange-096"},{"speaker":"筒井委員","kind":"提案","question":"いまだにこの条例のことを知らない区民もいるかと思いますが、完全施行直前ということで、改めて周知すべきですが、いかがお考えでしょうか。飲食店等に対し、表示の履行を徹底させるべきですが、いかがお考えか尋ねました。","respondent":"福内健康推進部長","answer":"全面施行後は５月３１日の世界禁煙デーとあわせ、広報しながわ５月２１日号で、受動喫煙の特集号を検討しております。３月３１日には、ほっとラジオしながわで、４月１日からの原則屋内全面禁煙についてお伝えする予定にしています。","id":"exchange-097"},{"speaker":"筒井委員","kind":"質問","question":"これを防ぐべきですが、どのような対策をお考えでしょうか。それは品川区の歩行喫煙を防止する条例の適用対象か尋ねました。","respondent":"福内健康推進部長、久保田地域振興部長","answer":"店外の敷地が飲食店の敷地の場合は、こちらの店主および喫煙者に対して受動喫煙の排除をしていただく必要があります。実際には指導を行う、または事前にこれらについてご相談がありますので、徹底を周知してまいります。 歩行喫煙を防止する条例の対象になりますので、生活安全サポート隊のほうで指導、取り締まりを行うです。歩行喫煙防止条例の対象外ではありますけれども、生活安全サポート隊のほうで実態を調査し、改善を求めているところです。","id":"exchange-098"},{"speaker":"筒井委員","kind":"質問・要望","question":"次に、罰則の過料の徴収方法ですが、都の職員が具体的にどう徴収するのでしょうか。この義務の履行も徹底されるべきですが、徹底させるための方策をいかがお考えか尋ねました。","respondent":"福内健康推進部長","answer":"日中と同様に、区の職員が店舗に赴き、改正健康増進法や都条例についての説明、また指導、助言など段階的な対応をとることになります。今年度も事業者の説明会を実施して周知を図ったところですが、次年度につきましても講習会や説明会を開催し、徹底をしてまいります。","id":"exchange-099"},{"speaker":"筒井委員","kind":"質問","question":"当該事業の周知方法と認知度向上の取り組みはいかがお考えでしょうか。","respondent":"藤田防災まちづくり部長","answer":"料金を求めないこと、それから区として初めて取り組むことであり、想定はなかなか難しいかというふうに考えてあります。今回の事業ですが、都の舟旅通勤の社会実験の実施とあわせて行います。","id":"exchange-100"},{"speaker":"筒井委員","kind":"質問・要望","question":"東京２０２０大会に関係なく、今後の舟運事業等で今回の航路を続けるお考えはあるのでしょうか。今述べた桟橋活用の場合、東京国際クルーズターミナルへ来る来訪者の品川区内への誘致策などのお考えはあるのか尋ねました。","respondent":"安藤文化スポーツ振興部長","answer":"料金についてですけれども、舟運事業者の方々と現在検討中ですが、料金はいただくような方向性で考えてあります。そして、東八潮の船の科学館近くに、今度、東京国際クルーズターミナルができる予定です。","id":"exchange-101"},{"speaker":"筒井委員","kind":"質問","question":"河川・運河などは自治体の境がないものなので積極的に広域連携をすべきですが、いかがお考えでしょうか。舟運事業者に対する新型コロナウイルス感染症に関する風評被害の払拭について、いかがお考えか尋ねました。","respondent":"藤田防災まちづくり部長、安藤文化スポーツ振興部長","answer":"私のほうからは、他区との連携についてお答えをいたします。引き続きまして、積極的に区として取り組んでいきたいというふうに考えてあります。そのような中で品川観光を進める品川区観光振興協議会には、舟運事業者をはじめさまざまな企業、事業者、観光関係団体の方々が構成員としております。","id":"exchange-102"},{"speaker":"筒井委員","kind":"提案","question":"このビジョンをどう把握されているでしょうか。このビジョンを注視して、可能ならば積極的に品川区も関与していくべきと考えますが、ご見解を説明を求めました。","respondent":"藤田防災まちづくり部長","answer":"こちらの先ほどの記載のお話ですが、品川区のこれまでの取り組みがしっかりと評価をされての提案書の記載というふうに考えてあります。引き続き、このように取り組んでまいりたいというふうに考えてあります。","id":"exchange-103"},{"speaker":"筒井委員","kind":"質問","question":"間もなく公表される国土交通省の「建築物における電気設備の浸水対策ガイドライン」を受けての品川区の今後の対応予定はどうなりますでしょうか。特に大切なのは、マンション管理組合、管理会社等への周知ですが、いかがお考えか尋ねました。","respondent":"中村都市環境部長、曽田災害対策担当部長","answer":"区の対応といたしましては、これまでも建築指導において浸水対応など安全への取り組みについて注意を促してきたところですけれども、引き続き。変電設備を設置する建築物の場合、都とも連携しまして指導、周知に努めてまいります。 しながわ防災学校やマンション防災アドバイザー派遣の機会などに周知を図ってまいります。今後の「高層マンション防災対策の手引き」の改訂の際には、このガイドラインで示された内容を取り込んでまいります。","id":"exchange-104"},{"speaker":"筒井委員","kind":"質問・要望","question":"住環境が品川区と比較的近い港区の防災資機材助成を参考に、エレベーターチェアや発電機の助成拡充のお考えはありますでしょうか。この事業の管理組合等への積極的な周知と活用のお考えはありますか尋ねました。","respondent":"曽田災害対策担当部長","answer":"エレベーターに乗っているときに大地震が起きた場合の対応として、あるいは、危険を伴う脱出については求めておりません。積極的に周知に努めているところでありまして、引き続き、周知に努めてまいります。","id":"exchange-105"},{"speaker":"筒井委員","kind":"質問","question":"最後に、現在の新型コロナウイルス感染症のパンデミック中に大地震が起きた際の避難所等での対応はどうされるのでしょうか。クラスターが起き得ますが、それへの備えは何かお考えか尋ねました。","respondent":"曽田災害対策担当部長","answer":"現在の状況の中で首都直下地震が起こった場合の対応についてですが、平素の感染拡大中の対応と同様であると考えております。感染拡大防止対策を講じるとともに、状況に応じて都と連携して医療施設へ移送するなど、さまざまなことを行っていくことになると考えております。","id":"exchange-106"},{"speaker":"筒井委員","kind":"質問・要望","question":"以上で私の質問を終わります。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-107"},{"speaker":"田中委員","kind":"確認","question":"款別審査のときに区内中小企業に対する緊急融資は確認をしております。非正規雇用などにも届く補助の仕組みでもあると理解をしましたが、その理解でよいのか、まず伺います。","respondent":"久保田地域振興部長","answer":"品川区としましても、こうした手続が円滑に進むように支援は進めてまいりたいと思ってあります。若者等就業支援事業等もありますので、こういったものを活用して、そうした方々の支援も進めていくところです。","id":"exchange-108"},{"speaker":"田中委員","kind":"質問・要望","question":"質問の視点は、この事態が終息したときには、全体を検証して何らかの形で記録として残すべきという視点で伺います。公園課では、それぞれどのような協議が行われ、決定に至ったのか尋ねました。","respondent":"榎本総務部長、本城教育次長、福島子ども未来部長、安藤文化スポーツ振興部長","answer":"文化スポーツ振興部、それから防災まちづくり部、全ての部長の中で協議をして一定の方針をつくり上げるための会議を行いました。主な協議の内容は… 休業中も教員が町場を巡回したり、個別の相談等を実施したりしているところで、そういった効果にもつながっているものと考えているところです。… ３つ目の質問の子ども未来部の対応ですが、その１つとして、児童センターが休館しております。現在は、感染症対策の拡大や国の動向を踏まえつつ… 同じく文化スポーツ振興部の対応です。","id":"exchange-109"},{"speaker":"田中委員","kind":"確認","question":"今後、そういう緊急時の職務をどのように行うのかも視野に入れておく必要があると思いますが、見解を伺います。あわせて記録して残す必要があると考えますが、見解を伺います。","respondent":"福島子ども未来部長、榎本総務部長","answer":"家庭環境に問題のある子どもの対応ですけれども、先ほど言いましたように、電話連絡ですとか家庭訪問等も実際には行っているところです。今後、児童相談所を持った場合ですけれども、取り組みにつきましては、さまざまな事例等について… 課題等の記録ですけれども、今回の新型コロナウイルス感染症の関係では、現時点で新型コロナウイルス感染症対策本部会議を５回実施しております。今後も感染症の動向を注視しつつ、適切に対応を進めていきたいと考えています。","id":"exchange-110"},{"speaker":"田中委員","kind":"質問・要望","question":"区の措置への理解を図るためにも、もっと区民への情報発信を積極的に行うべきと考えますが、区の見解を伺います。授業の再開などについて、区は最短でいつごろに発表を行うのか伺います。","respondent":"本城教育次長、榎本総務部長","answer":"保護者の方々に対して、今回の休業措置を何のために行うかということが、あわせてとても大切であるという認識は当然持っているところです。そして保護者と共通認識の中で進められているのが現状であると思いますし、あと… 今後の対応ですけれども、現時点では、施設の開閉については３月分までを発表しています。３月１９日の専門家会議の動向と、それを踏まえて今週中に４月以降の対応について判断し、公表していきたいと考えています。","id":"exchange-111"},{"speaker":"田中委員","kind":"質問・要望","question":"区の見解を伺います。二度目になりますが、区でもきめ細やかな情報発信を行い、感染拡大防止に向けてほしいと強く求めますが、いかがか尋ねました。","respondent":"本城教育次長、榎本総務部長","answer":"緊急的な対応をする、学校だより等の中で広く、校長先生自身がペンをとる形でお伝えをしています。大きな社会的な関心が当然あるものにつきましては、あわせて対外的にもしっかりこれからもＰＲしていきたいと考えているところです。 説明等、また、イベント自粛などの対策の実施や解除するタイミングは。そういったものも踏まえて、今後の状況を考えていきたいと考えています。","id":"exchange-112"},{"speaker":"田中委員","kind":"質問・要望","question":"その中で、２０１７年には、羽田新ルートに対して、視覚障害者の外出の安全・安心を確保するための対策を講じるよう求める請願が採択されました。逆に音を振動で感じ取る聴覚障害者や、音に過敏な発達障害者の生活活動の変化、どのように検討されているのか伺います。","respondent":"伊崎福祉部長、中村都市環境部長","answer":"私からは、平成２９年１１月の請願を受けての区の動きについてお答え申し上げます。引き続き、品川区視覚障害者福祉協会からのご意見を伺いまして、丁寧に対応してまいります。 国に伝えてまいりますが、調査を含めた具体的な対応は、事業主体である国の責任で行うべきものというふうに考えております。引き続き、国に求めてまいりたいというふうに考えております。","id":"exchange-113"},{"speaker":"田中委員","kind":"質問","question":"新ルートが運用された後の調査結果を持っているということは、何かあったときに区としての根拠にもなりますが、改めて見解を伺います。書面で示しているのか、その辺について伺います。","respondent":"中村都市環境部長","answer":"そういった予定がない場合には、文書やメール、こういったこともあります。実際に本格運行を開始した中で、区としてもやはり何らかの具体的な対応を求めていく、そういった考えで臨みたいというふうに考えております。","id":"exchange-114"},{"speaker":"田中委員","kind":"質問・要望","question":"実機飛行確認後の区民の声を受け、どのように庁内で議論があったのか伺います。羽田新ルートに対して否定的な意見が多く寄せられたときには、区は区民の立場に立って撤回を国に求めていくのか伺います。","respondent":"中村都市環境部長","answer":"やはり国の説明の内容から著しく、これは国に対して説明を求めたりですとか、あるいは監視をしていくというふうな考えです。実際に区民の声として文書をもって内容を回答したりですとか、国に届けてほしいという、それぞれご意見をいただいた方の要望に応じて対応しています。","id":"exchange-115"},{"speaker":"田中委員","kind":"質問・要望","question":"区は、もし落下物があったときには、被害が出ていなくても、国へ調査状況の確認を求めるのでしょうか。少なくとも調査を行っている間は事業を止めると強い姿勢で航空会社に求め、国へもそのように求めていくべきと考えますが、見解を伺います。","respondent":"中村都市環境部長","answer":"本格運行実施の後に、状況に応じ、行っていきたいというふうに考えております。そして、落下物に対する対応ですけれども、落下物の対応については。","id":"exchange-116"},{"speaker":"田中委員","kind":"質問・要望","question":"国に対しても同じく航空会社に求めてもらい、区として求めるべきと考えますが、改めて伺います。区としての航空機事故の想定をどのように持ち、対策を始めているのか伺います。","respondent":"中村都市環境部長","answer":"早速、空港事務所に連絡をいたしまして、厳密な対応をお願いしますというようなところを依頼したことがございました。そういった中で、やはり調査がしっかりと行われて確実に結果がわかるというところが一番大事なのかというふうに感じております。","id":"exchange-117"},{"speaker":"田中委員","kind":"質問・要望","question":"そして、区民も一番気にしていることなので、公表すべきとして求めます。品川区地域防災計画についても、今、防災課との協議が進んでいるのか、防災課に限らず、庁内での協議、改定が必要だと思いますが、伺います。","respondent":"中村都市環境部長","answer":"国に対する意見といたしましては、これは記録に残すというところで行っていきたいというふうに考えております。","id":"exchange-118"},{"speaker":"田中委員","kind":"質問","question":"リスクが高まり改定が必要と考えます。いかがか尋ねました。","respondent":"曽田災害対策担当部長","answer":"今、既に大規模事故ということで、航空機事故にかかわらず想定はしております。ただ、その状況に即して対応するというのが基本的な考え方でありますので、今あるもので対応できると考えております。","id":"exchange-119"},{"speaker":"石田（秀）委員","kind":"提案","question":"これは私たち会派が地域の皆様や各種団体からお寄せいただいた声をもとに、要望を提案した施策であり、着実に具体化されることを望みます。そして、本日の総括質疑や款別審査において、我が会派の委員からの要望、提案も事業実施されることを要望いたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-120"},{"speaker":"大沢委員","kind":"提案","question":"東京２０２０大会開催への懸念など、経済的環境は一層混沌の度合いを強め、課題を解決する上で大きな障害になっていると考えます。予算審査で各委員が行った提案、提言が十分に事業執行に反映され、さらなる区民福祉の向上が図られることを望み、意見表明といたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-121"},{"speaker":"若林委員","kind":"提案","question":"以上を改めて緊急要望とし、早急かつ的確な施策展開と補正予算の策定を求めます。以上、品川区議会公明党の意見、要望を今後の区政運営に反映されるよう求め、意見表明を終わりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-122"},{"speaker":"中塚委員","kind":"質問・要望","question":"濱野区長は、なぜ計画中止を求めないのかと再三にわたる質問に対し、区長は最後まで答弁にすら立つことはありませんでした。教員の長時間労働を常態化する変形労働時間制導入の中止、豊かな性教育の実践などを重ねて求め、意見表明といたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-123"},{"speaker":"須貝委員","kind":"質問・要望","question":"再起できるように、そして雇用や働く場が残るように、資金繰り支援や経済対策を実施していただきたい。以上、品川改革連合の意見表明を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-124"},{"speaker":"吉田委員","kind":"提案","question":"品川・生活者ネットワークは、今からでも計画の中止を国に対して求めるべきと主張します。そのほか各款別審査で品川・生活者ネットワークが指摘、提案させていただいた意見を予算執行に生かしていただくことを要望し、意見表明といたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-125"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/273075?Template=document&Id=1122#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":118417,"voices":299}},{"id":"r02-20200326-10","meetingId":"r02-cm03","date":"2020年3月26日","dateIso":"2020-03-26","committee":"議会運営委員会","time":"午前１０時３０分～午前１１時１０分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を2件整理しています。","topics":[{"id":"topic-01","title":"開議時間","agenda":"開議時間","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"従来、この第２３号議案につきましては反対とすべきところを、誤って賛成としてしまいました。なお、本会議の対応になるわけですけれども、厚生委員会に所属をしている２名の議員が一旦退席をさせていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"教育委員会教育長の任命同意について、反対させてほしいと求めました。理由は、品川区の教育行政は抜本的に見直しが必要だと思うからです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/101132?Template=document&Id=5350#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":13405,"voices":67}},{"id":"r02-20200327-6","meetingId":"r02-cm03","date":"2020年3月27日","dateIso":"2020-03-27","committee":"区民委員会","time":"午前１０時５５分～午後 ０時１４分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を17件整理しています。","topics":[{"id":"topic-01","title":"第２８号議案 令和２年度品川区一般会計補正予算（歳出 区民委員会所管分）","agenda":"第２８号議案 令和２年度品川区一般会計補正予算（歳出 区民委員会所管分）","exchanges":[{"speaker":"おくの委員","kind":"意見","question":"幾つかあるのですが、まず、融資あっせんの強化ということで、もう既にたくさん相談が来ていると思うのですけれども、現段階で、通常よりもどのぐらい増えているか、数字をお示しいただければと、まず思いますとの意見を述べました。","respondent":"山崎商業・ものづくり課長","answer":"今、３月２日に例の国のほうの４号認定が追加されまして、同日から延長窓口を開始し、約１カ月経過しようとしております。ピークで先ほど１,２００件と申しましたが、これも通常の月の処理から考えますと、３倍ペースというようなところで現状推移しているところです。","id":"exchange-001"},{"speaker":"おくの委員","kind":"質問・要望","question":"ありがとうございました。大変な数になっているので頑張ってほしいと求めましたけれども、それから、よろしいか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"おくの委員","kind":"質問","question":"すばらしいことだと拝聴していたのですけれども、この代行費用の助成というのは何％ぐらい、どのぐらいの割合で助成されているのでしょうか。お伺いいたします。","respondent":"山崎商業・ものづくり課長","answer":"もろもろの業務というようなところですので、区としましては、それにかかる経費の１０分の１０を支援をするということです。１つの企業でダブルの申請が、１０万円の限度額内であれば申請代行のほうを行っていただけるだろうなというようなところで予算立てをしています。","id":"exchange-003"},{"speaker":"おくの委員","kind":"質問・要望","question":"お伺いいたしますというか要望になるのかもしれませんけれども、休業補償ですか、それに対する社労士の体制を整えられた。これを伺います。","respondent":"山崎商業・ものづくり課長","answer":"武蔵小山創業支援センター、３分の１ぐらいそういうことに対応したのですけれども、そういった拡張をこれから検討しようということで。それぞれのエリアに創業支援センターなどはまだありますので、そういう形で４月はスタートさせようというふうに考えていたところです。","id":"exchange-004"},{"speaker":"おくの委員","kind":"質問・要望","question":"ですから、直接に支援していくということも考えなければいけないという、もう事態になってきたのではないかと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"おくの委員","kind":"質問・要望","question":"そういうものの直接助成、そういうこともいろいろ工夫していただけるのだと思います。この工夫というものも考えていただきたいと私は思うのですけれども、いかがか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"適正に対応はしておりますが、まずは５００万円の今回の経営変化対策ということで、通常のお店をやっている個人事業主の方々です。説明をさせていただきました区内企業の活性化策をもって、区としてもいろいろ検討していかなければいけないのかなというふうに思っています。","id":"exchange-006"},{"speaker":"おくの委員","kind":"質問・要望","question":"ですから、１つの変化が見えてきたかなと私は思ったもので、従来のフレームに捉われずに考えていってほしいと求めました。そういうふうに要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"くにば委員","kind":"質問","question":"もろもろ伺いたいことがあるので、順不同でお伺いしていきます。もちろん、今後さらに追加追加で予算を組む予定がある事業であるとかはどのようなものがあるのか、まずはそちらをお伺いします。","respondent":"山崎商業・ものづくり課長","answer":"２つ目に、いつ、今回のこの影響の収束ということが見えてくるかという判断が非常に難しいです。スピード感をもって対応する内容としましては、適正に区としてはご提案させていただいているかなというふうに判断しているところです。","id":"exchange-008"},{"speaker":"くにば委員","kind":"質問","question":"次のお話をお伺いしながら、今のお話に関してもう１回質問します。そこに対してのスピード感というのをまず伺いたくて、企業によると思うのですけれども、どれぐらいのスピードで決めようと思っているのか。","respondent":"山崎商業・ものづくり課長","answer":"そうしますと、そこにコマの空きができたりというようなこともあって、そうしたところを柔軟に対応しているというのが現状です。ほぼ品川区の小規模８５％という事業所の資金ニーズから考えますと、セーフティネット保証がついているというふうに区としては考えているところです。","id":"exchange-009"},{"speaker":"くにば委員","kind":"質問・要望","question":"コロナ対策のためであるかどうかは、私は伺い損ねているのですけれども、さらに追加なさったではないですか。今年度の２億円ではなくて、もう少し、今回の件があるので追加をしたらいかがかなと思うのですけれども、その辺に関してご所見を伺いたいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"くにば委員","kind":"質問","question":"私は、そういった商店に関してやるのか、中小企業も、今、国のほうから配られていないではないですか。区でストックしているものをどこの場所に配布するかというのをほかの方が伺いましたけれども、区のほうで現在在庫がある中で、最後に伺います。","respondent":"山崎商業・ものづくり課長","answer":"中堅企業とあわせて、商店街の中にある飲食店も個人事業主として区としては中小企業支援ということで考えているところです。そうした方面での直接支援ですとか、参考のご意見としながら、研究課題ということで受け止めさせていただけたらというふうに思ったところです。","id":"exchange-011"},{"speaker":"湯澤委員","kind":"質問・要望","question":"それからあっせん件数、それぞれあるかと思うのですが、そちらのほうを教えていただきたいと。ワンストップでしっかりと連携がとれてできているのかどうかというところと、あとは、件数などがわかっていたら教えてほしいと求めました。","respondent":"山崎商業・ものづくり課長","answer":"来年度予算に計上したということですので、令和２年度の予算で予定をしている事業ということで考えれば、来年度。そういったところは、これまでの連携も含めて、しっかり対応できるような形で行っています。","id":"exchange-012"},{"speaker":"湯澤委員","kind":"質問・要望","question":"まさにリーマンのときと違う中の１つとしては、そこをしないというのはすばらしい対策だと思いますので、お願いしたいと思います。月に１,２００人の方が、それから、区のほうで用意をして相談員の方に配付をしているのかということを教えてほしいと求めました。","respondent":"山崎商業・ものづくり課長","answer":"いわゆるキーワードになっている３密の状態という空間ではありませんが、コロナ対策実施中で、そのような状況です。もちろん、相談員さんも健康あっての部分ですから、ご提案の趣旨のとおり、頑張ってしっかり対応いただいているというふうに思っているところです。","id":"exchange-013"},{"speaker":"湯澤委員","kind":"質問・要望","question":"全てそこに来る人、来た人が感染をしてしまったみたいなことがないような、そういった対策をとっていただきたいと要望させてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"こんの副委員長","kind":"質問・要望","question":"その状況をまず教えていただきたいのと、スピード感を持ってというご答弁をいただいていますので、期待をしております。どういう業種なのかというところをまず確認します。","respondent":"山崎商業・ものづくり課長","answer":"今、やはり現状で多いのが、飲食店の方々がもう半数です。お花屋さんでありますとか、お菓子屋さんでありますとか、商店街の中に位置している個人事業主の方の相談がまず一番多いなというのが特徴です。","id":"exchange-015"},{"speaker":"こんの副委員長","kind":"質問","question":"そうした場合に、ご相談に来られて、書類を提出します。あるいは不備があったり、そうした場合の相談員の相談者に対する対応はどういうふうにしていただいているのかというところをお聞きしたいのですが。","respondent":"山崎商業・ものづくり課長","answer":"相談員の説明が難しすぎて理解が困難であったとか、少しご相談、苦情などをいただくケースも若干出てきております。そういったあたりは強化をさせていただきつつ、改善を図りながら、この混乱を乗り切ってまいりたいというふうに思っているところです。","id":"exchange-016"},{"speaker":"こんの副委員長","kind":"質問","question":"どうしても件数が多くなって時間がかかってしまうのは、そうしていただくことによって、その辺の対応をぜひお願いしたいと思います。あるいは申請書であったり、そうしたものの細かい更新作業を早目にされたほうがいいかなというふうに思いますけれども、いかがか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"そうですね。４月１日はもうすぐですので、おっしゃった趣旨で対応させていただければということを考えています。","id":"exchange-017"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/297302?Template=document&Id=2862#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":23852,"voices":53}},{"id":"r02-20200327-7","meetingId":"r02-cm03","date":"2020年3月27日","dateIso":"2020-03-27","committee":"厚生委員会","time":"午前１０時５５分～午前１１時３０分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を9件整理しています。","topics":[{"id":"topic-01","title":"第２８号議案、令和２年度品川区一般会計補正予算（歳出 厚生委員会所管分）","agenda":"第２８号議案、令和２年度品川区一般会計補正予算（歳出 厚生委員会所管分）","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"昨日は４７人で、その前が４１人ということで、その確認をお願いしたいと思います。これは品川で、この２カ所の医療機関で入院が必要だと判断されたときに、品川区が移送をするという形での移送費ということになるのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ここのところは改める必要があるのではないかと思ったのですけれども、そこのご見解をお聞かせほしいと求めました。〔「補正についてやろう」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういうことにもつながっていくのではないかと思うのですけれども、その点をお聞かせほしいと求めました。そういう点では、保健所の体制というところの予算措置も必要なのではないかという思いがしたのですが、その点についてはいかがか尋ねました。","respondent":"鷹箸保健予防課長","answer":"早目の受診が必要と考えられた場合には、既に品川区内では２つの医師会に、品川区においては保たれているものと認識しております。江戸川区の考え方も含めて、品川区が今後変更するかということについては、今後の課題だとは考えております。","id":"exchange-003"},{"speaker":"あべ委員","kind":"提案","question":"どういう対応をしていったらいいのか、あるいはどういう注意があったらいいのかということを取り出して、ご提案です。手いっぱいになってしまうので、そちらの精神的なケアを切り分けた相談窓口みたいなものはできないだろうかと思っているのですが、いかがか尋ねました。","respondent":"鷹箸保健予防課長","answer":"そこは難しい部分があると思いますので、不要不急の外出を避けるというところが一番の基本かと思います。現状ではそこだけ切り分けてというところは、今のところは体制の中では考えられていない部分になります。","id":"exchange-004"},{"speaker":"あべ委員","kind":"意見","question":"だから、広報というのは周りの人にしてほしいということなのです。重症リスクを抱えた人たちなのだということを、わかってほしいということを知らせてほしいという、これはお願いですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"すごくありがたかったという声をお聞きしているのですけれども、保育のほうは、５０万円を限度に出ているではないですか。〔「厚生委員会なのか」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"いや、医療と介護の現場でのそういう対応というところでは、ここに係るかなと思ったのですけれども、それは総務ということになるのですか。いないですからね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それと、ここの補正のところで、医療廃棄物処理と従事職員用防護用具の中身についても教えてほしいと求めました。それからもう一つ、啓発というところでは、どんな取り組みを考えられているのかについてもお聞かせほしいと求めました。","respondent":"鷹箸保健予防課長","answer":"１つ４,０００円ぐらいするものを幾つかというものと、今お話させていただいた防護服、ゴーグルとか手袋が必要です。は実際の患者の対応に追われている状況でございまして、そういったことも含めての丁寧な啓発を、これから改めて必要だとは思っております。","id":"exchange-008"},{"speaker":"西村委員","kind":"質問・要望","question":"今、詳細を聞かせていただきましたので、賛成をさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/410936?Template=document&Id=3560#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":10230,"voices":41}},{"id":"r02-20200327-9","meetingId":"r02-cm03","date":"2020年3月27日","dateIso":"2020-03-27","committee":"文教委員会","time":"午前１０時５５分～午前１１時１５分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を15件整理しています。","topics":[{"id":"topic-01","title":"第２８号議案、令和２年度品川区一般会計補正予算（歳出 文教委員会所管分）","agenda":"第２８号議案、令和２年度品川区一般会計補正予算（歳出 文教委員会所管分）","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"感染拡大防止対策物品として対象になるのは、どこまでになるのかというか、どういったものになるのかというところでお聞きしたいと思います。支払いの方法はどういったタイミングか、手続なども含めて伺いたいと思います。","respondent":"大澤保育支援課長","answer":"購入に際しましては、４月１日からの購入品が対象になります。支払い方法ですが、各園で購入いただき、領収書等をもって、その後、区からの支払いという形になります。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問・要望","question":"今回の予算については４月１日からのものだということでしたけれども、今、出回っていなくて買えないという状況だと思うのです。ですので、今まで買ってきたものも含めて対象にすべきだと思うのですけれども、いかがか尋ねました。","respondent":"大澤保育支援課長","answer":"対象は４月１日からの購入にします。既に３月中に２万５,０００枚のマスクを各園に配付しておりますので、３月中の物品については、おおむねそれで賄えていると考えております。","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問・要望","question":"今後、マスクですとか消毒液、ほかにも必要なものがありましたら、配付をしていってほしいと求めましたけれども、いかがでしょうか。そういったものが不足しているかどうかということを、各園などの状況を把握していただいて、手配をしてほしいと求めましたが、いかがか尋ねました。","respondent":"大澤保育支援課長","answer":"今後も各園には、国から直接配付ということも聞いております。この状況がいつまで続くか、今は不透明な状況ですので、各園の状況については、区でもしっかりと把握をしていきたいと考えています。","id":"exchange-003"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひそういった手だてを講じてほしいと求めました。こうした残業代、時間延長された部分についても、ぜひ補助してほしいと求めましたけれども、いかがか尋ねました。","respondent":"大澤保育支援課長","answer":"現在のところ、人件費の援助は考えておりません。","id":"exchange-004"},{"speaker":"のだて委員","kind":"質問・要望","question":"ここで聞くしかないかなと思いまして、伺いたいのですけれども、今後どのように考えていらっしゃるのか。予算特別委員会の総括質疑でもお聞きしましたけれども、学力テストの４月の実施。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"のだて委員","kind":"質問","question":"今後、学校が再開された場合には、実際、そのまま区のものはやるという話でしたが、国のほうは延期をしているわけでして、やはり今回の休校で授業が遅れてしまっているというところで、区でも学力テストを中止、少なくとも延期にしていくべきではないかと思うのですけれども、いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"のだて委員","kind":"質問・要望","question":"そういったことも含めて、ぜひ考えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"筒井委員","kind":"質問","question":"今回、私立保育園・幼稚園や認証保育所の感染症対策なのですけれども、小学校・中学校というのはどのようなことになっているのか尋ねました。","respondent":"有馬庶務課長","answer":"小学校・中学校については、総務費にて、同じように感染拡大防止対策物品の購入というのがあります。こちらで学校のほうは手当てしていくという形になっております。","id":"exchange-008"},{"speaker":"塚本委員","kind":"確認","question":"確認ですけれども、２３園ということで、そういったものを一切含むのかどうかというところを確認したいということ。その辺りの上限の考え方というのはどのようになっているか、確認させてください。","respondent":"大澤保育支援課長","answer":"家庭的保育事業も含めまして、上限を１園５０万円で計上しております。","id":"exchange-009"},{"speaker":"塚本委員","kind":"意見","question":"わからないのですけれども、かなり格差というか、規模の違いがあるので、５０万円で大きな保育園では足りるのかとか、そういうところについての今後の推移によって、この辺りの考え方というのは柔軟に対応するというところは、どのように思っていらっしゃいますかとの意見を述べました。","respondent":"大澤保育支援課長","answer":"感染の拡大がいつまで長引くかということによると思うのですけれども、長期的になった場合は、再度予算を組まなければいけない事態になるのではないかとは考えておりまして、その場合は、改めてご提案したいと考えています。","id":"exchange-010"},{"speaker":"塚本委員","kind":"意見","question":"お昼を給食で賄われていたところが、家庭からの支出になっているというところでの相差というか、負担を見ていただいてほしいという。その辺りはよく注視していただいて、区としても考えるべきところがあれば、ということでお願いしておきたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"},{"speaker":"高橋（し）委員","kind":"確認","question":"実際に支払われるまで、どれぐらいの時間というか、日にちを見込んでいらっしゃるのでしょうか。それだけ確認させてください。","respondent":"大澤保育支援課長","answer":"一律に日付を区切って領収書等を提出していただく場合と、５０万円の上限に達した時点で提出していただく場合と、両方があるかと思っているのですけれども、翌月または翌々月の運営費と一緒に支払うというのが通常のやり方ですので、それに沿ってやりたいとは思っております。","id":"exchange-012"},{"speaker":"のだて委員","kind":"質問","question":"対象となる園が、認可外は対象にならないということなのか。少なくとも区が助成をしている認可外については、同じ補助をしていくべきなのではないかと思うのですけれども、いかがか尋ねました。","respondent":"大澤保育支援課長","answer":"区から認可外への補助というのは、今はしていませんので、補助金についても区がやる考えはございませんが、国のほうから認可外には対象として、同じスキームで補助があると聞いておりますので、おそらくそちらで網羅できると考えています。","id":"exchange-013"},{"speaker":"横山委員","kind":"確認","question":"細かいところで確認なのですけれども、期間のところについて、４月１日からの購入分が対象ということだったのですけれども、終わりというか、いつまでというのは、現状での方針というか、そういったことはありますか。","respondent":"大澤保育支援課長","answer":"現在のところは、年度内中と考えております。","id":"exchange-014"},{"speaker":"横山委員","kind":"確認","question":"確認させていただきました。区でも状況は把握していくということですので、情報提供などもしていただきながら、状況に合わせて進めていただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/418457?Template=document&Id=4996#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":5477,"voices":50}},{"id":"r02-20200327-5","meetingId":"r02-cm03","date":"2020年3月27日","dateIso":"2020-03-27","committee":"総務委員会","time":"午後 １時００分～午後 ２時０６分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を27件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"小芝委員","kind":"質問","question":"総論的な話になるのですけれども、今回の補正予算が対象とする時期といいますか、これは多分新型コロナウイルス感染症のこれからの状況を鑑みてやっていくと思うのですが、大体どの程度の時期を鑑みた結果この予算を立てたのか尋ねました。","respondent":"品川財政課長","answer":"さすがに現状としてはそこまで予算として対応しきれない部分があるということで、今回当初予算と同時予算という形で補正予算を上げております。期間としては、とにかく４月から６月補正までの間を想定しての、基本的な考えとしてはそういう対応と考えております。","id":"exchange-001"},{"speaker":"小芝委員","kind":"質問","question":"例えば品川区で運営されています水族館とか健康センター等ありますけれども、そういったところも今軒並み収益が下降していると思うのですが、そういったことの補償といいますか助成といいますか、そういったものは計上がされておるのか尋ねました。","respondent":"品川財政課長","answer":"今回の補正予算の中では具体的な計上はございませんが、水族館等、３月にこのやむを得ない状況により休館することになりましたので、基本的に３月分につきましては今年度予算の予備費という形で対応しています。","id":"exchange-002"},{"speaker":"小芝委員","kind":"質問・要望","question":"私が３月１０日前後にお店に行ってみたら、前月比で３割か４割減という話もありますし、今はそれこそ５割以上減というところもあります。ぜひお考えを聞かせてください。","respondent":"品川財政課長","answer":"確かにこの間に事業所等非常に厳しい状況になっているというところは重々理解しています。そういった費用も補正予算で対応するような形で計上しておりますので、こういう課題について乗り切っていただきたいと、このように考えております。","id":"exchange-003"},{"speaker":"中塚委員","kind":"確認","question":"これまでも区の施設はもちろん病院や私立の保育所もマスクは配られているというお話を伺っております。確認をした上で施設内に入る、そういう対応を既に行っておるのですが、品川区としてはどのような対応をするのか伺いたいと思います。","respondent":"立川総務課長","answer":"区としての検温器の対応ですが、入手でき次第、出入り口でのチェック等を実施したいと考えているところです。〔「どのように使うのか」と呼ぶ者あり〕 消毒液につきましても同様です。検温器につきましては、区の出先施設を中心に配布したいと考えているところです。","id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"医療施設、障害者施設もこういう物品の購入に対して補助をする必要があるかと思っているのですけれども、その考えはないのか伺いたいと思います。今３億円あった上で４億円を積むということで、どういう要素を想定した上での４億円なのか、そこのご説明をほしいと求めました。","respondent":"立川総務課長、品川財政課長","answer":"納入関係についてご説明いたします。現状、見積もりをもらいたいと言いましても、納期のめどが立たないということで、事業者のほうも具体的な対応ができないという状況です。基本的には事業としてやっているところでありまして、保育園につきましては、まず重点的に対応していくという点があります。","id":"exchange-005"},{"speaker":"中塚委員","kind":"質問・要望","question":"対応を迫られておりますので、ぜひ保育園以外のこうした福祉施設に対しても補助の対象拡大をしてほしいと求めましたが、改めていかがでしょうか。伺いたいのは、これを品川区として求めてほしいと求めましたが、いかがか尋ねました。","respondent":"品川財政課長","answer":"基本的には今回計上しております危機管理経費の部分で、先ほどと答弁が重なりますけれども、臨機応変にその辺は対応していきたいと考えております。こういった状況の中で国や都に対して何かを求めていくというスタンスは基本的には避けていこうと考えています。","id":"exchange-006"},{"speaker":"中塚委員","kind":"質問・要望","question":"事業主や個人に対して直接支援、これは必要だと思いますので、改めて求めておきたいと思います。それについてはどのように対応するのかご説明ほしいと求めました。","respondent":"黒田人事課長、立川総務課長","answer":"全てが移動禁止ということではないので、現時点では月曜日以降については通常どおり庁舎を開ける想定で今動いております。日曜開庁につきましても同様の考えでおりますので、現時点では庁舎機能… 予定どおり開庁する予定です。ただ、問い合わせ等も多数考えられますので、そうした場合郵送等をご案内していきたいと思っています。","id":"exchange-007"},{"speaker":"田中委員","kind":"質問・要望","question":"各所管のところに踏み込むので、ご説明ができない部分もあるかもしれないのですけれども、伺います。５０万円までを申請した園がいただけるのか、それとも一律に５０万円ずつ補助を前もって渡して、それらについてお知らせいただきたいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"田中委員","kind":"質問・要望","question":"次に、生活者ネットワークも予算特別委員会のときにも融資あっせんの部分で伺ってきました。現在この制度自体に、そういうケースもこの補正予算でどうにか対応できるものなのかといった部分についてお答えいただきたいのですが、いかがか尋ねました。","respondent":"品川財政課長","answer":"こういう融資をやることによりまして、従業員に対して給料が払えるとかそういう形も出てくるかと考えております。こういった補助について、申請をするために社会保険労務士とかを雇う費用、こういったものを補助の対象という形で今回補正予算に計上しています。","id":"exchange-009"},{"speaker":"田中委員","kind":"確認","question":"今回の補正予算で計上されている相談窓口のほうにとにかく相談をしてもらうという形が一番いいということでしょうか。その辺を確認させてください。","respondent":"品川財政課長","answer":"相談窓口も通常よりも各ブースを大体倍ぐらいに今回の補正予算で上げて対応していこうと考えています。それから、先ほど申しましたけれども、そういったものを十分に利用しながらこの危機を皆さんで乗り越えていただければと思います。","id":"exchange-010"},{"speaker":"田中委員","kind":"質問・要望","question":"ですので、そういった方たちに情報が届くように、待つだけではなく発信を強めていただきたいということを要望します。そして、電話相談センター開設経費が今回の補正予算で計上されているのですけれども、この電話相談センターというのは部屋で設置されるのか尋ねました。","respondent":"品川財政課長","answer":"現状４人体制でやっているところなのですけれども、今回の補正予算で人員増強もしまして対応していきたいと考えております。テレワークは必要ないと考えています。","id":"exchange-011"},{"speaker":"須貝委員","kind":"質問・要望","question":"本当に物がないので、予算をせっかく計上していただいたのですけれども、こういうものを国に早くつくってくれという要請を私はしてほしいと思います。ですから、万全な体制を、支援をしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"西本委員","kind":"意見","question":"おやと思ったのですけれども、巷にはマスクがないのでどうするのという話になるので、そこは区として対処をしていかなければいけないだろうと。だったら、教育費の中にやはり新型コロナウイルス感染症対策が一本入っていないとおかしいのではないかと思ったので、まずそこだけとの意見を述べました。","respondent":"品川財政課長","answer":"危機管理経費の項目については、基本的には区有施設を考えておりますので、当然学校も含んだ形で考えております。この中で、とにかく対応し切れるものは全て対応していくと、このような考えでおります。","id":"exchange-013"},{"speaker":"西本委員","kind":"質問","question":"余裕はありますけれども、基金のこれからの取り扱い、こういう緊急の状況になったときの予算措置の中でどういうふうにこの基金を使い分けていくのか。６月補正で間に合うのか、例えば５月に臨時会がありますけれども、その上程の仕方をまずお聞きしたい。","respondent":"品川財政課長","answer":"今後補正予算につきましては、どういうところから歳入項目を持ってくるかということは、その状況に応じて検討していきたいと考えております。","id":"exchange-014"},{"speaker":"西本委員","kind":"質問","question":"今後も多分１年以上かかる可能性もあるので、今回の新型コロナウイルス感染症も同時に考えていくべきことなのかと思います。そうなってくると、またそこでも余裕ではないですが、ある程度使えるお金が出てくる可能性もあるので、その考え方はいかがか尋ねました。","respondent":"品川財政課長","answer":"ただ、区としては、やはり後々の考え方としてはそのような考えを持ちながらこの新型コロナウイルス感染症対策は進めていきたいと考えております。当然新型コロナウイルス感染症対策のほうについては補正予算等で対応していきますので、このように考えています。","id":"exchange-015"},{"speaker":"西本委員","kind":"質問・要望","question":"半年で終わるのか１年かかってしまうのか、やはり産業振興等々の支援にしても２通り考えておくべきだと思っていて、あとは長く続くなと。区のそれぞれの特徴があると思うので、ぜひとも何かしらの支援策を考えていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"大倉委員","kind":"質問・要望","question":"具体的に確認をさせていただきたいのですが、１万２００本等々があって、実際の購入の見込みというのがどの程度あるのか教えていただきたいのと。今在庫がどのくらいあるのか、改めて確認も含めてお願いしたいと思います。","respondent":"立川総務課長","answer":"入手見込みですが、委員のご案内のとおり大変厳しいということになっております。メーカー、卸業者等に問い合わせをしましても、今のところ見込みが全くないという返事をいただいているところです。 在庫につきましては、最新の状況ですが、マスクにつきましてはおおよそ１７万枚、消毒液につきましては約２,５００本です。おおよそその程度です。","id":"exchange-017"},{"speaker":"大倉委員","kind":"質問・要望","question":"今後必要とする１６１万枚が３カ月分だということです。１７万枚をどう使おうかみたいな話にもなってくるのかなと思ったのですが、その辺の考え方についてお聞かせほしいと求めました。","respondent":"立川総務課長","answer":"この積算については、いわゆる使い捨てのマスクを１日１枚使った場合ですけれども、それは各施設の職員数分ということで聞いております。","id":"exchange-018"},{"speaker":"田中委員","kind":"質問","question":"一つ忘れていたのですが、保育園などへの補助の上限５０万円の根拠について、５０万円で足りるのかなという趣旨でその辺について考え方を説明を求めました。","respondent":"品川財政課長","answer":"この上限５０万円というのは、考え方はなかなか難しいところもありますが、とにかく補助の金額としてはこれぐらいという形で出しているものです。","id":"exchange-019"},{"speaker":"つる副委員長","kind":"確認","question":"大倉委員のほうから細かい部分の確認が出たのですが、それを踏まえてもう一回確認ですけれども、その辺はどういうやりくりになっているのか尋ねました。","respondent":"立川総務課長","answer":"衛生用品ということで、これまでも入札等を実施しておりますので、入札に参加している事業者に問い合わせをするというのがまず基本になります。それ以外には、個別に売り込みというような話も来ているところではあります。","id":"exchange-020"},{"speaker":"つる副委員長","kind":"確認","question":"逆に言うと、ありますよ、売れますよという業者があったときに、どこの縦の縛りがあるのですか。どうぞどうぞ、それは可能なのかどうか、確認させてください。","respondent":"立川総務課長","answer":"基本的に、いわゆる契約のルールというのがありますけれども、こういった非常時ですので、その辺は柔軟に対応したいと考えているところです。","id":"exchange-021"},{"speaker":"つる副委員長","kind":"確認","question":"それからあと西本委員のところでやりとりがあって今大倉委員のほうで確認したときに、大人用マスク、子ども用マスクでサイズ感が違うと思うのです。そこの確認をお願いします。","respondent":"立川総務課長","answer":"先ほど財政課長が答弁いたしました学校用というのは、職員用でございまして、子ども用は含まれておりません。マスクの種類ですが、一般的にサージカルマスクというふうに言われているものですけれども、今回の見積もりについてはそちらを考えているところです。","id":"exchange-022"},{"speaker":"つる副委員長","kind":"質問・要望","question":"一区民の方も本当に困っている現状の中でなかなかさっき言ったようにどこに求めるのかというところがある中、行政の立ち位置としては。そういう型紙等があるわけですから、３Ｄプリンタの活用だとか、その辺について確認させてください。","respondent":"立川総務課長","answer":"１２年ぐらい前なのですが、新型インフルエンザの専門会議で、流行時の日常生活におけるマスク使用の考え方というのが出ております。３Ｄプリンタの活用、この辺につきましては関係するところと協議いたしまして、その可能性については検討していきたいなと考えているところです。","id":"exchange-023"},{"speaker":"つる副委員長","kind":"確認","question":"一番大事な現場に行きつくというところの対策を区としてどうしていくかというところにおいては、そういうのもきちんと確認していただきながらだと思うのですが、あらゆる手段を探ってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"西本委員","kind":"質問・要望","question":"それからもう一つ、マスクなのですけれども、これも細かい話で、言うべきかどうか迷ったのですが、コロナウイルスは大きさが１０ミクロンなのです。なので、それをきちんと所管の方々と相談しながら入手先をお願いしたいと思います。","respondent":"品川財政課長","answer":"ただ、そういう意味を込めて在庫で対応するという形で答弁をしておりますので、お間違えないようにしていただきたいと思います。具体的案のほうについては、当然教育委員会でまた今後出していきますので、その後の状況を見てという形になってありますので、よろしくお願いします。","id":"exchange-025"},{"speaker":"西本委員","kind":"質問・要望","question":"なので、早急に教育委員会と話をして進めてほしいと求めました。でも、現実そうではないわけだから、それをやはり区として何かしらの形をしていっていただきたいという思いがあります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"中塚委員","kind":"質問・要望","question":"それから政府や東京都が外出規制を要請しているわけですから、介護施設、障害者施設の直接支援など思い切った対応が必要だと考えています。それ以外の収入がない仕組みもありますので、今後とも幅広く施設や住民の声に耳を傾けていただいて、執行してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/346628?Template=document&Id=2162#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":19710,"voices":73}},{"id":"r02-20200327-10","meetingId":"r02-cm03","date":"2020年3月27日","dateIso":"2020-03-27","committee":"議会運営委員会","time":"午後 ２時５５分～午後 ２時５７分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/101132?Template=document&Id=5352#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":1006,"voices":8}},{"id":"r02-20200415-10","meetingId":"r02-cm04","date":"2020年4月15日","dateIso":"2020-04-15","committee":"議会運営委員会","time":"午後 １時００分～午後 ２時４８分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を28件整理しています。","topics":[{"id":"topic-01","title":"特別委員会の調査事項等","agenda":"特別委員会の調査事項等","exchanges":[{"speaker":"本多委員","kind":"質問・要望","question":"２つの特別委員会の設置を求めます。これも引き続き求めるものです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"大倉委員","kind":"質問・要望","question":"行財政改革特別委員会とオリンピック・パラリンピック推進特別委員会の２つを、前年度と同様に求めていきたいと考えています。最後に、こうした環境に対する取り組みというのをさらに充実していっていただきたいと思いまして、項目として取り上げさせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"新妻委員","kind":"提案","question":"公明党は、行財政改革、新型コロナウイルス感染症等対策、オリンピック・パラリンピック、この３つの特別委員会を提案します。この３特別委員会を提案いたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-003"},{"speaker":"中塚委員","kind":"提案","question":"日本共産党としては、４つの特別委員会の設置を提案したいと思います。地震、風水害、要援護者対応、気候変動対策、以上でありますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"},{"speaker":"須貝委員","kind":"質問","question":"これからは品川区の喫緊の重要課題に対しては、５常任委員会でしっかりと議論すべきだと思いますので、特別委員会を設置することは反対します。皆さんの話をお聞きしましたが、新型コロナウイルスが区民の命と健康、そしてご商売が倒産するかどうかという時期なのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"本多委員","kind":"意見","question":"今の項目を見ていますと、議会からも４名委員が選出されるということなので、こちらの検討委員会に重きを置いたほうがいいのかなと思います。すみません、それだけ言わせていただいて、一旦終わりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-006"},{"speaker":"渡部委員","kind":"提案","question":"私どもは庁舎のあり方に関することというのを提案させていただいていたのですが、提案を取り下げるといいましょうか、そちらでできればいいのかなと考えしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"中塚委員","kind":"提案","question":"共産党としては４つの特別委員会を提案させていただいたところでありますが、その報告も受けつつ、いろいろな役割があるのではないかなと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-008"},{"speaker":"新妻委員","kind":"提案","question":"各会派のお話を伺わせていただきました。今回、公明党からは３つの委員会ということで提案をさせていただきましたが、危機管理等々も含めて入っておりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-009"},{"speaker":"鈴木（真）委員","kind":"意見","question":"危機管理に関することということで出ていらっしゃるので、コロナ対策という点では、ここに入れたらどうかなと考えておりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-010"},{"speaker":"鈴木（真）委員","kind":"質問","question":"項目が行革で増えるようだったら、こっちをオリパラに変えていってもらうと、数も少し楽になるのかなとは感じています。ですから環境を、リサイクルも含めた上で、オリパラに移すことも、自民党としては了解します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"あくつ委員","kind":"質問・要望","question":"確認したいのは、そういうところで、そのようにしていただきたいということ。どうしても環境の議論が狭まってしまうということがあるので、当然、少し立ち入った議論ができるような形にしていただけるとありがたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"そんなこともあって、環境問題とリサイクルを絡めて、全体的なものとして考えている状況です。これを契機としてということで、一つにはなるけれども、オリンピックだけにとらわれないでやっていただきたいという発想です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"渡部委員","kind":"質問","question":"これからの環境問題をどうするかという思いもあって、幅広くできれば、それにこしたことはないというもともとの思いです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"中塚委員","kind":"意見","question":"新たに新型コロナウイルス感染症について、かつて羽田の問題もここでやっておりましたので、意見を述べたいと思います。現状の課題や対応策をオリンピック・パラリンピックという節目の中で、どう進めていくか、対応していくかという視点も大事ではないかと思っていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"},{"speaker":"本多委員","kind":"提案","question":"行革のほうに提案したのですが、別項目で求めていたのですが、一くくりでもいいのかなと思います。オリンピック・パラリンピックでうちから求めていたアリーナ計画と障害者スポーツ施設なども、そんな思いで発言をしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-016"},{"speaker":"中塚委員","kind":"意見","question":"やはり環境と位置づけるのであれば、ＣＯ２など温室効果ガスを、どう減らしていくのかと。行政計画が定められて、毎年発表されておりますけれども、一言で言えば、ＣＯ２削減の視点は欠かせないと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-017"},{"speaker":"あくつ委員","kind":"質問・要望","question":"本当にこれを集中してやるべきではないかという意見が、私どもの会派ではありましたので、ここは何とか皆さんにご検討いただけないか。できれば入れていただきたいという趣旨で、繰り返しになってしまいますが、お願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"鈴木（真）委員","kind":"提案","question":"うちも２番目の公益財団法人ということを出したのですけれども、逆に項目が多ければ、これを外してもいいかなと思っています。水族館が来年３０周年ということで、今後の計画ということについては、行革の中で詰めたらどうかということがうちの提案ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"},{"speaker":"中塚委員","kind":"質問・要望","question":"１点だけ、検討会の進捗状況については、常任委員会にしっかり報告をしていただきたいと述べておきたいと思います。保健所と言ったらいいのでしょうか、コロナについては保健所の対応なくして進みませんので、いずれにしても保健所の視点が大事だと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"あくつ委員","kind":"提案","question":"私どもも提案をさせていただいたのですが、それとは別に、なかなか厳しい状況が生まれかねないのかなという懸念もあります。先ほどほかの委員からもご提案あったように、全庁的対応を問うという形では、ぜひ入れていただきたいというところがありますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-021"},{"speaker":"新妻委員","kind":"質問・要望","question":"この行革の中で議論をしていくということを、一つここにとどめてほしいと求めましたが、いかがでしょうか。今後品川区も導入するとしているチャットボットですとか、ぜひ取り上げてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"石田（ち）委員","kind":"質問","question":"もしざっくりとあればお聞きしたいと思うのですが、特に３番のアリーナ計画というのは、そういったことなどがあればお聞きしたいと思うのですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"鈴木（真）委員","kind":"提案","question":"基本的に、そういう感覚です。既にいろいろ出ている中で、それも関係してくるのではないかということで、提案させてもらっていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-024"}]},{"id":"topic-02","title":"新型コロナウイルス感染症の拡大防止に向けた対策等","agenda":"新型コロナウイルス感染症の拡大防止に向けた対策等","exchanges":[{"speaker":"あくつ委員","kind":"質問・要望","question":"おまとめいただいて、ありがとうございました。議会運営の話で要望というか、ぜひお願いしたいということがありまして、この場で意見として述べします。","respondent":"渡辺議長","answer":"丁寧に準備段階、相談という形が増えるかもしれませんが、諮っていきたいと思っています。現在も肝に銘じておりますが、意識して取り組みたいと思います。","id":"exchange-025"}]},{"id":"topic-03","title":"その他の(1)政務活動のあらましおよび年度収支報告書等の公開","agenda":"その他の(1)政務活動のあらましおよび年度収支報告書等の公開","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"１,０００億円という基金を蓄えていただいているのですから、その１割でもコロナ対策に回すような活用を、区に進言する。〔「接触のリミットなのだから、手短に」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"須貝委員","kind":"提案","question":"２割から３割削減するという提案をしなかったら、区議会は何をしているのだと、私は言われても仕方がないことだと思います。それだけ、もし皆さんでご意見があったら、言っていただけたらありがたいと思いますとの意見を述べました。","respondent":"渡辺議長","answer":"既に多くの議員が、繰り返しますが、政策の提案、要望を、個人もそうですし、会派としても多くがされている。先ほどのような認識があることを大変反省して、議長職として議員に呼びかけていきたいと思います。","id":"exchange-027"},{"speaker":"須貝委員","kind":"質問","question":"商売をやっている人はどんな立場なのかというのが、そして医療現場の大変さが、すごく明確に我々の目に飛び込んできているわけではないですか。区にしっかりまた進言するということは、私は大事なことだと思いますので、それで意見を言わせていただきました。","respondent":"渡辺議長","answer":"ぜひ須貝議員もお願いいたします。区とやりとりをきれいな形で行えていますので、ただ要望するのではなく具体的に、非常に有効な要望をぜひお出しいただければ幸いです。","id":"exchange-028"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/101132?Template=document&Id=5354#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":21825,"voices":86}},{"id":"r02-20200420-6","meetingId":"r02-cm04","date":"2020年4月20日","dateIso":"2020-04-20","committee":"区民委員会","time":"午後 １時００分～午後 １時３７分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を12件整理しています。","topics":[{"id":"topic-01","title":"新型コロナウイルス感染症の拡大に伴う中小企業支援策等の実施状況","agenda":"新型コロナウイルス感染症の拡大に伴う中小企業支援策等の実施状況","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"２の（３）の雇用環境安定化事業助成金の雇用調整助成金のところなのですけれども、今、実績がないというお話だったのですが、これは相談もないのか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"２の（１）の社会保険労務士相談窓口で設置しておりますので、ここでは話を受けていたり、あるいは電話で、この雇用調整助成金はどうですかという話は聞くのですが、私どもはまだ持ち合わせていないようなところがありまして、話は伺うけれどもという状況です。","id":"exchange-001"},{"speaker":"おくの委員","kind":"質問","question":"社会保険労務士の相談窓口なのですけれども、混み具合はいかがなものなのか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"一斉にどっと来た感じでして、今ですと、今月いっぱいがちょうど埋まっている状況です。来月でしたらまだ、来月の早い段階で予約を取っていただけるという状況です。","id":"exchange-002"},{"speaker":"おくの委員","kind":"質問","question":"同じく、１番の経営相談のほうなのですけれども、これの混み具合をお聞きしたいのですが、要するに、相談に実際に乗れるのは、３月の段階、前回の区民委員会で聞いたときは、たしか２週間か３週間お待ちになっているという話だったと思うのですが、現在ではどのぐらいの感じになっているのか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"４月から中小企業診断士の相談ブースを３つ増やしたところでありまして、今ですと、３週間まではかからない、大体２週間ぐらいでご相談は受けることができるかなという状況です。","id":"exchange-003"},{"speaker":"おくの委員","kind":"質問","question":"だから、門前払いを必ずしもされないという、私も詳しい話や論理が分かっているわけではないのですが、そういう話も伺っているのです。私はそのお話を伺ったときに思ったのですが、国と歩調を合わせるような考え方はできないものか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"制度として区の税金を使うということで、多分、難しいというお話をさせていただいたかと思います。対応できるのかなと思いますので、お電話でも頂戴できれば、こちらの診断士で対応したいと考えております。","id":"exchange-004"},{"speaker":"おくの委員","kind":"質問・要望","question":"そういう状況の中で、品川区もそろそろ、幾ら何でもいろいろ考えていいのではないかと私は思うのですけれども、品川区として何かお考えでしょうか。考えてほしいと求めましたが、どうでしょうか、伺いたいと思います。","respondent":"遠藤商業・ものづくり課長","answer":"私どもの考えとしては、そこのところが一義的には、やると考えているところです。国とか都のいろいろな支援を見ながら、区で何かすることが必要であれば、そのときに改めて検討させていただきたいと考えています。","id":"exchange-005"},{"speaker":"湯澤委員","kind":"質問・要望","question":"１点だけ確認をさせてほしいと求めました。これは対象がどういった方で、どのぐらいの範囲でお配りというか、ご案内されているのかというのを教えてほしいと求めました。","respondent":"遠藤商業・ものづくり課長","answer":"区内の事業所に対して、シルバー人材センターを通じて配付したものでございまして、２万５,０００枚用意させていただいたです。おそらく２万ちょっとぐらいという形では聞いているのですが、すみません、まだ実際に全部配られたかは把握できていません。","id":"exchange-006"},{"speaker":"湯澤委員","kind":"質問","question":"事業所ということですけれども、これは全ての事業所を対象としているのか、それともある程度、何か対象区分とか、そういうのがあるのか、それを教えていただけますか。","respondent":"遠藤商業・ものづくり課長","answer":"こちらで把握しているところにつきましては、全てお送りするです。","id":"exchange-007"},{"speaker":"松澤委員","kind":"質問・要望","question":"３０分で８件の対応をしてくれたり、流れではインターネットの審査というのが、対応が多く求められているのかなというのを切実に感じております。そういった部分でも品川区として、臨機応変に対応をお願いしたいというのが１点。","respondent":"遠藤商業・ものづくり課長","answer":"例えば、ほかの郵送なりなんなりという部分で工夫ができればということで、検討していきたいと思います。区で積極的にこちらを支援していくことを考えておりまして、区のホームページ、ぜひとも活用いただければということで支援させていただいているです。","id":"exchange-008"},{"speaker":"松澤委員","kind":"意見","question":"今、何かそういうのを具体的にいろいろと商連と行政で話していただいて、そういうのが品川区に広がればうれしいというお願いであります。パソコンは２台買っていいとか、抜け道をいろいろと模索して支援していただけると、すごくありがたいと考えていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-009"},{"speaker":"おくの委員","kind":"意見","question":"すみません。なぜ実績がないかというところがよく分からなかったので、ご説明願えればありがたいのですが、お願いできますかとの意見を述べました。","respondent":"遠藤商業・ものづくり課長","answer":"そこの部分ではないというところでございまして、すみません、説明が不十分でした。大変失礼いたしました。","id":"exchange-010"},{"speaker":"こんの副委員長","kind":"質問","question":"そこで、今後の参考なのですけれども、東京都でこれからやる感染拡大防止協力金についても、これから４月２２日にウェブで出ると。手続上、この協力金についての手続などが、また各個店にお知らせとかというのは区からされるのかというところをお聞きしたいのですけれども。","respondent":"遠藤商業・ものづくり課長","answer":"直接やられるのかなと考えております。そこに載せられればというところは考えているところですが、ぎりぎりな部分がありますので、ほかの方法等を検討させていただければと考えています。","id":"exchange-011"},{"speaker":"松澤委員","kind":"質問","question":"支援の窓口がいろいろ、どんどん増えてくるではないですか。そもそもホームページが分からない人向けだと難しいとは思うのですが、そういうのがあると、すごく丁寧かなと思いました。","respondent":"遠藤商業・ものづくり課長","answer":"しばらくは、混乱するかなという部分がありますので、今のところは電話対応という形で対応させていただいています。","id":"exchange-012"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/297302?Template=document&Id=2864#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":12465,"voices":60}},{"id":"r02-20200420-7","meetingId":"r02-cm04","date":"2020年4月20日","dateIso":"2020-04-20","committee":"厚生委員会","time":"午後 １時００分～午後 ２時２４分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を33件整理しています。","topics":[{"id":"topic-01","title":"なお、冒頭申し上げましたとおり、取り上げる順番を変更し、報告事項(3)を先に行います。 (3)新型コロナウイルス感染症の対応","agenda":"なお、冒頭申し上げましたとおり、取り上げる順番を変更し、報告事項(3)を先に行います。 (3)新型コロナウイルス感染症の対応","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"改めてお伺いさせていただきたいのですが、そのうちＰＣＲ検査が行われた件数についてお聞かせほしいと求めました。感染者１３０人中、退院された方が、それぞれ何人なのかということについて教えてほしいと求めました。","respondent":"鷹箸保健予防課長","answer":"現在の１３０人がどういう状況かということなのですけれども、日々変更があることと、本来は入院しなくてはいけない。おかげさまで４月１３日から東京都で一括調整をしてくれている結果、電話で聞き取って、翌日または翌々日までには入院ができている状況です。","id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういうところでは、品川区としては検査の課題というのはないのかということについて、お聞かせほしいと求めました。４月１５日の厚労省のこの事務連絡を受けて、品川区としてはどう対応していくのかについてもお聞かせほしいと求めました。","respondent":"鷹箸保健予防課長","answer":"検査をするための外来についての考え方ですけれども、これまでの検討あるいは協議状況もありますが、具体的な協議を進めているところです。単に設置すればいいだけではなくて、設置した後は、あるいは不安がある方へのきちんとした対応ということも一方で必要ですので。","id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"検討会みたいなものというのは、発熱外来だけというか、今回出されていることについてだけ検討するということでやっているのでしょうか。それとも、対策会議みたいなものは定期的にというか、医師会の先生たちとの連携がどうなっているのかということについても説明を求めました。","respondent":"鷹箸保健予防課長","answer":"例えばご家族に既に陽性の方がいるという方については、そこまでお待たせしている現状は、今のところはないと認識しております。そういった方々の受診の方法ですとか、そういったものについても今、協議を進めているところになります。","id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"ごめんなさい。４月１５日の厚労省からの事務連絡で、そこら辺の見通しについて、最後に説明を求めました。","respondent":"鷹箸保健予防課長","answer":"今ご説明したとおり、品川区においては、それほどお待たせしているという認識は持っていないところから、地域外来・検査センターという形での外来の設置が必要かどうかも含めて、現在協議を進めているところになります。","id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"最後に、質問ではなくて。全日本の医師会の先生方も、そういう訴えもされておりますので、ぜひ品川でも実現していただくよう要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"あべ委員","kind":"質問","question":"その上で、３点ほどお伺いしたいと思います。区として、陽性になった方のその次、つまり、検査の後の場を整えるというところも議題に上っているかどうかというのを、まず説明を求めました。","respondent":"鷹箸保健予防課長","answer":"後半のほうは聞き取れたのですが、初めのほうの、検体を採るだけではない連携がという意味がよく分からなかったので、もう一度お願いいたします。","id":"exchange-006"},{"speaker":"あべ委員","kind":"質問","question":"私が知る限りでは、２３区中１０区ぐらいで今、いろいろな独自の動きが始まっているかなと。行政と医師会と言ったらいいのでしょうか、どういう方向で今、検討されているのかということをお伺いしたいと思いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"あべ委員","kind":"質問","question":"いえいえ、違う。だから、そういうことをやらないのであれば、どういうことをやるのですかということを、オープンクエスチョンとして聞いています。","respondent":"鷹箸保健予防課長","answer":"例えばその日、夜に具合が悪くなっても、その病院にきちんと対応していただくというところを担保されています。そこのところをきちんと決めませんと、単に検査というようには、我々としては、そこは勝手に検査すればいいというのではない。","id":"exchange-008"},{"speaker":"あべ委員","kind":"質問","question":"２３区の報道などで、いろいろな区がこういうセンターを始めますということを聞くと、では品川区はどうなっているのでしょうかとよく聞かれるのです。その辺、品川区はこうなのですよというのが、何かあるといいのですけれども、難しいか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"あべ委員","kind":"質問・要望","question":"それを周知していただきたいと思うのですけれども、今だったら、妊婦はどうしたらいいのですか。教えていただいていいか尋ねました。","respondent":"高山健康課長","answer":"資料にありますように、保健師が必要に応じて個別に電話や訪問などをすることで、フォローさせていただいているところです。きちんと一度は顔を合わせて、そういった部分については、落ち着くのを待ってフォローしていきたいと考えております。","id":"exchange-010"},{"speaker":"あべ委員","kind":"質問・要望","question":"電子申請の件数がこの間あったかどうかお伺いしたいのですが、特に電話でご一報くださいというのは、ぜひ周知していただきたいのです。既に区でもらっている人はどうなるのかなとか、それから妊娠していて妊娠届を出していない方への周知をぜひお願いしたいのですが、いかがか尋ねました。","respondent":"高山健康課長","answer":"きちんと対面でお会いして育児パッケージをお渡しできるように、その後の面談の日程などについては、きめ細やかにフォローしてまいりたいと思います。もらえる、もらえないの間に不利益などがないように、制度の枠組みの中できちんとフォローしてまいりたいと考えております。","id":"exchange-011"},{"speaker":"あべ委員","kind":"質問・要望","question":"何か指導というか、助言というか、そういうことはなさっているのでしょうか。何か一定のものを出されているのか、それに従って各課で判断されているということになっているのか、教えてほしいと求めました。","respondent":"鷹箸保健予防課長","answer":"都立の公園であれば都から出された方針、都の方針に準じて区で決めて、全てにおいて都から方針が示されているので。","id":"exchange-012"},{"speaker":"あべ委員","kind":"意見","question":"例えば公園を使える、使えないとか、その中の大型遊具を使う、使わないというのは、自治体によってかなり対応が分かれているかと思うのですが、今のご説明の、都の基準で皆さん一律でそういうことだと、自治体によって違うということは出てこないと思うのですがとの意見を述べました。","respondent":"鷹箸保健予防課長","answer":"失礼いたしました。都の考え方にのっとって使っていると私のほうでは理解していたところですので、差があることを認識していないところがありまして、申し訳ありません。","id":"exchange-013"},{"speaker":"あべ委員","kind":"質問・要望","question":"感染症学的と言ったらいいのでしょうか、それは感覚的なものではなくて、そこはぜひアドバイスをしてほしいと求めました。これを最後の要望にしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"}]},{"id":"topic-02","title":"に戻りまして、(1)品川区立西大井福祉園","agenda":"に戻りまして、(1)品川区立西大井福祉園","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういう関係するところへの周知というのがどうなっているのかということを、１点お聞かせいただきたいのと、どう違うのか。事業所に入る報酬というか、そういうところではそんなに変化のないものなのかどうか、その点だけ説明を求めました。","respondent":"松山障害者福祉課長","answer":"１点目の周知についてですけれども、私ども障害福祉課の障害者相談支援センターから、各相談支援センターには情報を流しています。２点目の報酬の違いについてですけれども、生活介護と就労継続支援Ｂ型のそれぞれの報酬単価というのは、西大井福祉園からは聞いておりません。","id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういう点では、事業者にマイナスになるようなことのないように、配慮はお願いしておきたいと思います。要望で結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"あべ委員","kind":"確認","question":"ということは逆に言えば、変更しても、利用されている方は基本的に同じ方が利用していると考えてよろしいのでしょうか。確認です。","respondent":"松山障害者福祉課長","answer":"利用されている方は、就労継続支援Ｂ型の方が生活介護をご希望されてということなのですが、状態といたしましては、生活介護の状態であったというところで、西大井福祉園の中での事業の所管を変えたということになります。","id":"exchange-017"},{"speaker":"あべ委員","kind":"確認","question":"確認ですが、これまで就労Ｂで使われていた方が、いられなくなってとか、そういうことではないということでよろしいか尋ねました。","respondent":"松山障害者福祉課長","answer":"そういうことではないです。","id":"exchange-018"}]},{"id":"topic-03","title":"障害福祉計画策定のための基礎調査の結果","agenda":"障害福祉計画策定のための基礎調査の結果","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"どんな要望だったりとか、そういうことに対しても、クロス集計もしっかりとやっていくというご答弁だったと思うのです。ここのところがこういう要望だったり、障害の方がより見えるような形にするためにも、そういう集計の仕方が必要なのではないかと思うのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"私は改めて……。〔「質問だけ端的にしよう」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"質問していますから、聞いていてください。〔「何を言っているか分からない」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"クロス集計は、年齢や性別、地域などをクロスして、よりデータを深掘りしていくもの。そういうものがクロス集計だと思いますので、今回のアンケートのまとめに対しても、ぜひクロス集計をしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"前回はアンケートのまとめという形で、クロス集計をしたものが出されてきたのですけれども、ではこういうものは、これからまた改めて出てくるということで考えていいのか尋ねました。","respondent":"築山障害者施策推進担当課長","answer":"策定委員会において、必要なものについてはクロス集計をしまして、分析しながら計画に反映をするということで考えております。","id":"exchange-023"},{"speaker":"あべ委員","kind":"質問","question":"委託の仕方で、相談とかはされたのでしょうか。印刷して冊子にしてしまうというのは、もったいない気がするのですけれども、そこら辺はどうお考えか尋ねました。","respondent":"築山障害者施策推進担当課長","answer":"それを用いまして、クロス集計はいかようにもできるような形になっております。それぞれのクロス集計をしたものを全て表しますと、膨大な量になりますので、今回はアンケートの質問内容に沿いまして集計をしたです。","id":"exchange-024"},{"speaker":"あべ委員","kind":"確認","question":"確認しますけれども、この状態で検討されると考えて、あくまでも内部の生データと考えてよろしいか尋ねました。","respondent":"築山障害者施策推進担当課長","answer":"こちらは計画策定に当たって使わせていただくデータです。","id":"exchange-025"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"生データということであれば、ここの中に書かれたものが、自由意見が全て載せられているのでしょうか。そこのところを伺いたい。","respondent":"築山障害者施策推進担当課長","answer":"自由意見については、全て載せているところです。","id":"exchange-026"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そこのところは改めて確認していただきたいのが１点です。全部載せたかどうかの確認はされているかどうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"それとも、前回と同じようなものが、今回に加えてもう一回出てくるということなのですか。この厚生委員会に報告すべきだし、問題とは感じられなかったのか、その点についても伺います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"だから、障害者を全部ひっくるめてグラフにするというやり方は、おかしいのではないですかと伺っているのです。その点については、ご覧になられてどうだったのか尋ねました。","respondent":"築山障害者施策推進担当課長","answer":"こちらも同じ回答になりますけれども、データで頂いておりますので、策定委員会において、必要に応じた分析をしながらとなってまいります。","id":"exchange-029"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"クロス集計もしっかりとしたものを、この委員会の中でも報告していただけますでしょうか。障害者別のグラフにするなどの訂正をした上で、出していただきたいと思うのですけれども、最後にこの点をお伺いします。","respondent":"築山障害者施策推進担当課長","answer":"この後、今年１年をかけまして策定委員会を開催してまいりますので、その中で、途中で報告できるものがあれば、ご報告をすると考えております。","id":"exchange-030"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"そういう方々の困り事や要請も出していくということで、今回取ったわけですから、難病者の項目というのを別立てで取り出してやっていただきたい。やはり要望の多いところですし、そして発達障害というのを出していただきたいと思うのですが、いかがか尋ねました。","respondent":"築山障害者施策推進担当課長","answer":"調査結果をどのように反映していくかにつきましては、策定委員会において検討してまいります。","id":"exchange-031"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"その策定委員会ですけれども、メンバーはどのようになっていたのでしょうか。当事者の方の意見をぜひ反映してほしいということで、今も要望がある中ですので、伺いたいと思います。","respondent":"築山障害者施策推進担当課長","answer":"現在の予定ですけれども、学識経験者の方、それから保健医療関係ということで医師会を想定しております。当事者のご意見を聴くというところでは、障害者団体を予定しております。","id":"exchange-032"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"７団体という形ということで、出していただきたいので、ぜひ充実したものにしてほしいと求めました。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/410936?Template=document&Id=3562#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":25335,"voices":118}},{"id":"r02-20200420-8","meetingId":"r02-cm04","date":"2020年4月20日","dateIso":"2020-04-20","committee":"建設委員会","time":"午後 １時００分～午後 ３時２６分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を36件整理しています。","topics":[{"id":"topic-01","title":"なお、冒頭申し上げましたとおり、取り上げる順番を変更し、報告事項(4)から(7)を先に行います。 初めに、(4)特定空家等の認定","agenda":"なお、冒頭申し上げましたとおり、取り上げる順番を変更し、報告事項(4)から(7)を先に行います。 初めに、(4)特定空家等の認定","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"それぞれの件で情報提供が住民からあったということですが、近隣住民からどのような声が寄せられたのか伺います。一番下にありますけれども、具体的にはどのような措置がなされ、解決に向かっていくのかも伺います。","respondent":"森住宅課長","answer":"そういった措置についても、空家等の除却の後押しになるのではないかと考えています。所有者とコンタクトが取れておりますので、それぞれ情報を頂きながら、こちらからも必要な情報等を提供しながら進めていければと考えております。","id":"exchange-001"},{"speaker":"石田（秀）委員","kind":"質問","question":"そうすると、１０年たっても何万円です。だから、そこら辺のところをどうお考えになっているのかだけ教えてほしい。","respondent":"森住宅課長","answer":"それは毎年払っていて、どうしようかと思って、そのままになっているというところもあります。新たに令和２年度予算で、民間の事業者に委託を考えておりまして、売却というのを後押ししていきたいと考えております。","id":"exchange-002"},{"speaker":"松本委員","kind":"質問","question":"品川区の過去の事例を調べると、代執行まで行った事例があるということで、この理由はたしか家屋に近接とか、通学路沿いとか、そういった事由があったかと思うのですけれども、今回のこの３件については、そのあたりはどうなっていますか尋ねました。","respondent":"森住宅課長","answer":"その中で、状態の悪いものとして３件をまずは特定空家等として認定したです。例えば崩れたりすると周りへの影響が大きいものもありますので、今後一生懸命取り組んでいければと考えております。","id":"exchange-003"},{"speaker":"松本委員","kind":"質問","question":"おそらく対応は取られているかと思います。周辺に、例えば、崩れてどうにかなるというのを予防する措置というか、周知も含めて、そういったところはどうなっていますか尋ねました。","respondent":"森住宅課長","answer":"審議会の中でも、委員にそれぞれ見ていただきまして、コーンの設置、そういったものも今後進めていこうと考えております。周辺の公共施設といいましょうか、保育園だとかには注意して登園なりお散歩に出かけてというようなことは周知をし、お願いをしています。","id":"exchange-004"}]},{"id":"topic-02","title":"分譲マンションの管理状況届出制度","agenda":"分譲マンションの管理状況届出制度","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"中身について幾つかお伺いしますけれども、届出内容の真偽はどう確かめるのかというのが１点目と、届け出なかった場合はどうなるのかということです。伺います。","respondent":"森住宅課長","answer":"も届出等、今ある区のマンションへの支援制度等をご紹介しながら、適正な管理についてお願いをしていくという形になります。そういったものをそれぞれ各区、あるいは区内の分譲マンションで突き合わせをしながら、必要な助言はできたらと考えております。","id":"exchange-005"},{"speaker":"安藤委員","kind":"確認","question":"１点目の届出内容の真偽は、どう確かめるのかという質問をしたので、改めてお伺いします。その実効性を担保する体制を、住宅課としてどう構築していくのかについて伺いたいと思います。","respondent":"森住宅課長","answer":"今、例えば総会が年１回以上開かれていないというものにつきましては、年１回開きましょうという助言をするというふうになろうかと思います。","id":"exchange-006"},{"speaker":"安藤委員","kind":"質問・要望","question":"はこういった制度が始まるということで、結構悩んでいるところはたくさんありますよね。一緒に問題点を共有して、一緒に寄り添って解決していくという方向でぜひこの制度を活用してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"}]},{"id":"topic-03","title":"しながわＥＣＯフェスティバル２０２０の開催中止","agenda":"しながわＥＣＯフェスティバル２０２０の開催中止","exchanges":[{"speaker":"吉田委員","kind":"質問・要望","question":"それはそうしていただきたいと思うのですが、１つだけ、プラスチック製のものがまだ使われていると思うのです。そのような製品の削減を今後区の事業の中で行っていく予定があるのかどうか、その辺、伺いたいと思います。","respondent":"提坂環境課長","answer":"ほかの様々な機会で積極的に取り組んでまいりますということでご説明しましたけれども、必要な部分については、啓発活動をやっていきたいと思います。本来、環境課が参加できるかどうかということを検討して、前向きに取り組んでまいりたいと考えています。","id":"exchange-008"},{"speaker":"石田（秀）委員","kind":"質問","question":"今まで二十何回もやってきているとなると、出てきてくださる業者の方というか、いろいろな方々も慣れている方が多いではないですか。一気呵成に行うとなったら、復活する可能性があるかだけ、説明を求めました。","respondent":"提坂環境課長","answer":"なかなか今年度の開催延期は困難と考えまして、来年度に、来年度は今年の分もまとめて盛大にやっていきたいと考えております。夢さん橋とか、そういうところにもブースを出していくとか、そういうことは検討していきたいと考えているところではあります。","id":"exchange-009"},{"speaker":"石田（秀）委員","kind":"意見","question":"どうしてこういうことを言っているかというと、皆さん、準備もそんなに難しくないと思うのです。来年にまとめてということでしたが、そんなことをいったら経済活動が全部ストップしてしまうと私は思っているということだけ伝えておきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-010"}]},{"id":"topic-04","title":"実機飛行確認における航空機騒音の精査結果","agenda":"実機飛行確認における航空機騒音の精査結果","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"２段階降下のほうが、通常のＩＬＳ運用時の３度の降下よりも、よりうるさいということなのですか。この国の資料の２つのグラフというのですか、何が違うのかが分からなかったというか、少し分かりづらいと思いませんかということで、お願いします。","respondent":"鈴木都市計画課長","answer":"３度と比較した２段階降下、降下角３度のほうが小さかったということで、東京都立産業技術高等専門学校と八潮ポンプ所のほうは効果が出ています。その下、青のほうは、ＩＬＳ運用時、降下角３度の場合と３.４５度の場合では効果が出ましたという内容です。","id":"exchange-011"},{"speaker":"安藤委員","kind":"質問・要望","question":"そうなのでしょうけれども、まず、今のご説明だと、上の青のグラフと下の青のグラフ、結局、どちらもＡとＣで比べているのではないですか。もう一度教えていただきたいというのと、水色のほうのグラフでは、そこら辺はどのように区は認識しているのか尋ねました。","respondent":"鈴木都市計画課長","answer":"説明が分かりづらくて申し訳ございません。データもまだ７日間ということで、これから国のほうは本格運用を開始して、国の言い方です。","id":"exchange-012"},{"speaker":"安藤委員","kind":"質問・要望","question":"３月２９日から強行されていくというのが本当に納得いかないところで、撤回というのを強く求めてもらいたいと、改めて申し上げたいと思います。これは実際、住民、人間の耳で聞き分けられる程度なのかどうかというのはどうなのか尋ねました。","respondent":"鈴木都市計画課長","answer":"当然ながら、音を感じる感じ方というのは、同じ音、例えば、同じ８０デシベルだとしても、その方が感じる感じ方というのは、皆さん様々だと思います。８０デシベルですとか、やはり１つでも１デシベルでも、国のほうに強く求めていきたいです。","id":"exchange-013"},{"speaker":"吉田委員","kind":"質問・要望","question":"生活にいろいろ変化が起きてくる人の調査を区としてやるべきではないかというふうに質問しているのですが、本来国がやるべきものというご答弁でした。それを区として国のほうに求めておられるのかどうか、その辺について伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"決定前にいろいろな説明会の中でお示ししてきた数字ですが、これを超えたから超えないからそれでいいのだという認識は持ってございません。あるいは必要な対応を国の責任をもって国のほうでしっかり行っていただくように、これまでも求めてきましたし、今後も求めていきたいです。","id":"exchange-014"},{"speaker":"吉田委員","kind":"質問・要望","question":"なので、ぜひ今後区としても検討をしていただきたいと要望しておきます。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"}]},{"id":"topic-05","title":"コミュニティバス導入に向けた検討状況","agenda":"コミュニティバス導入に向けた検討状況","exchanges":[{"speaker":"松本委員","kind":"質問","question":"沿線人口のところなのですけれども、米印の４を見ると、これは平成２７年の国勢調査のデータを用いてと書かれてあるかと思います。平成２７年と比較して、今回の評価の中である程度考慮されたのかどうか、そのあたりをお願いいたします。","respondent":"鈴木都市計画課長","answer":"国勢調査は平成２７年度が最新でして、当然ながら、実際の利用率がどれぐらいになるのかということを見込んでいくのが大変難しいところでして。","id":"exchange-016"},{"speaker":"松本委員","kind":"質問・要望","question":"その際に少しデータと違うようなところがある場合には、そういったところも気を付けながら、引き続き検証してほしいと求めました。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"たけうち委員","kind":"質問・要望","question":"３つのルートともになのか、地域の要望があるようなところには、車両制限令とかでなかなか行けないというご説明もありました。資料の別紙３の一番最後の４ページで、区のほうで一応今のところ考えている、おそらくこうなるだろうという試算表ということでよろしいのか尋ねました。","respondent":"鈴木都市計画課長","answer":"資料の運行収支ですが、これは先ほどご説明したとおり、区の一定程度条件をつけて試算をしてみるとという形での提示です。一定、こうなるのではないかという予想をしているものです。","id":"exchange-018"},{"speaker":"たけうち委員","kind":"質問・要望","question":"そういう声をぜひできる限り聞いていただいてということは１つ要望するのと、例えば、そういったものをバス事業者に求めるということでいいのか。そうではなくて、そこも含めてプロポーザルで出させるのか、その辺の考え方を説明を求めました。","respondent":"鈴木都市計画課長","answer":"この地域はこれぐらいのことを見込めるのではないかということは、そのときに、まるっきりバス事業者も試算した結果赤字でしたと。運行経費として支援しますというところの数字も、そうしたところはしっかり検討して、提案していきたいと思います。","id":"exchange-019"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"道路幅員の制限令があるから、資料にあることしか書けないというのは、それはまさにそのとおりだと思います。西大井本通りの中に入っていくようなことを地域の方とも話していただきたいということをお伝えくださいと言っていたので、それだけお伝えします。","respondent":"鈴木都市計画課長","answer":"この大井ルートの左側の地域につきまして、特に西大井本通りは、その地域の中でも比較的幅員が広いところですので、場合によっては、白線を引き直すとか、そうしたところをしっかり検討して、警視庁のほうとも、地域の声も聞きながら、協議を進めていきたいと考えております。","id":"exchange-020"},{"speaker":"安藤委員","kind":"質問・要望","question":"別紙４の今後の予定のところで、３回分の地域公共交通会議の日程も出ていますが、地域公共交通会議の開催時期との関係でご説明ほしいと求めました。","respondent":"鈴木都市計画課長","answer":"今年６月に第１回目の地域公共交通会議を実施予定なのですが、地域公共交通基本方針については、このタイミングです。そのルートが決まった中身を令和３年２月頃という、３回目のところに書いていますが、その中でまとめていくという予定です。","id":"exchange-021"},{"speaker":"安藤委員","kind":"質問・要望","question":"これまでも明記するよう求めてきたのですけれども、改めてこの方針に入れるよう求めたいのですけれども、いかがでしょうか。そして、区はなぜこうした観点を入れないのか、その理由を伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"小委員会の中で大分移動の保障についての議論がなされたようなのですが、最終的には、交通政策基本法には盛り込まれなかったです。区のこの基本方針に、あるいは鉄道を含めて、文字として書いていないからそうしたところを排除しているのかというところでは全くございません。","id":"exchange-022"},{"speaker":"安藤委員","kind":"質問・要望","question":"これは素案ですから、また地域公共交通会議にかけるわけですけれども、ぜひその視点を持っていただきたいと改めて要望したいと思います。ここら辺を、素案ではこのように書いているのですが、見直しを求めたいのですけれども、求めた上で区のここについてのお考えを伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"やはり走らせてからその中身について検討していこうかというところよりも、流れを、しっかり進めていくことが必要だと考えています。５年１０年というのは長過ぎますが、状況によっては、その次のルート案の検討ということも考えていくということはあろうかと思います。","id":"exchange-023"},{"speaker":"安藤委員","kind":"意見","question":"周知なども含めて、もう少しそれを聞きたいというのが１つと、あと、３つのルートを、ありていに言えば、幾つに絞る考えなのか。どういう基準に絞るのかというのも聞かせてくださいとの意見を述べました。","respondent":"鈴木都市計画課長","answer":"これからしっかり検討してきたいというところで、できれば６月ですとか７月、８月にワークショップを行っていきたいと考えています。１本なのか、それは３ルートでまとめて試行運行を開始する場合もあるでしょうし、まずは試行運行として１本という考え方もあるでしょうし。","id":"exchange-024"},{"speaker":"安藤委員","kind":"質問・要望","question":"困っている方が気軽に利用できるようにすべきだと思うのですけれども、１００円にしてなおかつシルバーパスの利用というのは可能なのでしょうか。伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"やはりそこはバリアフリー対応のバスをまず考えて、ただ、少しでもバス停あるいは駅から遠い地域を走らせられるように協議をしていきたいです。１００円とシルバーパスの関係ですが、１００円にした場合は、シルバーパスの併用は基本的にできないと聞いてあります。","id":"exchange-025"},{"speaker":"安藤委員","kind":"提案","question":"最後のところですけれども、基本的にはということなので、私もこれから、ぜひそのようにすべきではないかと思います。なので、研究もして、提案もしていきたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-026"},{"speaker":"吉田委員","kind":"質問・要望","question":"考えておくべきなのではないかと思うのですが、８月までにプロポーザルを行うということであれば、どうしてもその辺でやらなければいけない。そこに手を挙げられるかどうかはご本人が決めることですけれども、広く募っていただきたいのですが、伺います。","respondent":"鈴木都市計画課長","answer":"ワークショップに代わるやり方を何か検討して、そこは、スケジュールも全体的にずらしていくということになろうかと思います。地域の方にご説明してきた中で、やはりさらに地域のいろいろな区民の方からご参加いただける、あるいは意見を頂く。","id":"exchange-027"}]},{"id":"topic-06","title":"「品川区中高層建築物等の建設に関する開発環境指導要綱」および「品川区ワンルーム形式等集合建築物に関する指導要綱」の改正","agenda":"「品川区中高層建築物等の建設に関する開発環境指導要綱」および「品川区ワンルーム形式等集合建築物に関する指導要綱」の改正","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"別紙１の一番右上の、区や地域からの要望に合わせた機能として、ほかに何があるのか教えてください。ですから、そこも増やすべきなのではないかという声も聞いているのですけれども、これはなぜなのか。","respondent":"鈴木都市計画課長","answer":"それから、基本的には区内全域で２５m2以上というところで強化を図ったわけですが、増やしていくというところは検討の中ではしてございません。開発環境指導要綱のほうでも、今のところ、ワンルーム要綱のほうに駐輪場の設置を新たに加えるというところは検討してございません。","id":"exchange-028"},{"speaker":"安藤委員","kind":"質問","question":"そういうのも理解できるのですけれども、それ以外のところの改正の理由、動機というのですか。特にまちづくりに寄与するエリアというあたりなのですけれども、これはどういう背景や動機があったのか、もう少し説明ください。","respondent":"鈴木都市計画課長","answer":"別紙１の３の景観に配慮したエリアとまちづくりに寄与するエリアについては、対象をこういう形で今分けておりますが、考え方は一緒です。","id":"exchange-029"},{"speaker":"安藤委員","kind":"質問","question":"検討は以前から行われていたということで、資料にもありますけれども、今回、建設委員会に一回報告があって、約１０日後には改正がされると。こういう今の進め方だけだとなというふうに思うのですけれども、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"内容を見直す検討にあたっては、あるいは不動産の関係の方々とも内容について意見を交換しながら、これまで取りまとめを進めてまいりました。周知期間を置いて、運用を１１月から行っていくというところで、今考えてあります。","id":"exchange-030"},{"speaker":"吉田委員","kind":"質問","question":"その周知期間のことを伺いたいと思うのですが、期間は６か月ですが、周知の方法というのはどのように考えられているのか、説明を求めました。","respondent":"鈴木都市計画課長","answer":"基本的には、区のホームページ、窓口等での周知を考えてあります。","id":"exchange-031"}]},{"id":"topic-07","title":"に戻りまして、(8)東京都高潮氾濫危険水位","agenda":"に戻りまして、(8)東京都高潮氾濫危険水位","exchanges":[{"speaker":"吉田委員","kind":"質問","question":"区の対応のところなのですけれども、「高潮氾濫危険情報発表時の対応として、沿岸部全域の区民の避難態勢を改めて検討し」となっておりますが、検討スケジュールとか、今考えておられましたら、伺いたいと思います。","respondent":"中島防災課長","answer":"夏頃、出水期をめどに一定程度の方向性を定めまして、区民の方々にその結果を周知できるように検討は進めてまいりたいと思います。","id":"exchange-032"},{"speaker":"安藤委員","kind":"意見","question":"品川区全体が緑の点線の枠に入っているということですけれども、今後の区の今のところ、対応というところで、沿岸部全域の区民の避難態勢を改めて検討するとあるのですが、その対象となる地域について、現在、どういうところという想定をしているのか、もう少し説明を求めました。","respondent":"中島防災課長","answer":"今回、高潮氾濫危険水位というところで、想定し得る最大規模の台風というものが前提となります。区の東側、そういうところの範囲が広範囲にわたりますので、そちらのほうを広範囲に検討する必要があると考えています。","id":"exchange-033"},{"speaker":"石田（秀）委員","kind":"質問","question":"私が不勉強なのですが、高潮氾濫危険水位になったときに、水門というのは連動して閉めるとか、どういう状況になったら水門は閉めるのですか。今、台風というお話だったのだけれども、そこら辺のところがよく分からないので、説明を求めました。","respondent":"藤田防災まちづくり部長","answer":"区内には、ご案内のとおり、２か所水門があります。その辺が出たときに際しても、その後の状況等を勘案しながら港湾局が対応しておりますので、おそらくそういう形になろうかと考えています。","id":"exchange-034"},{"speaker":"石田（秀）委員","kind":"質問","question":"どうしてそういうことを言うかというと、手動は生きているのかと。都が閉めてくれなければ、ずっとそのまま開けっ放しなのか、そこら辺がよく分からなかったので、もう少し教えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"石田（秀）委員","kind":"質問","question":"どうしてこんなことを言うかというと、天王洲に水門があるではないですか。その通路なので、そうすると、変わらずあれは水門用の通路として確保しなくてはならないという理解で変わっていないということでいいのか尋ねました。","respondent":"藤田防災まちづくり部長","answer":"基本的には、通常の車が入るとか、そういったものの確保は必要かと考えています。","id":"exchange-036"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/733618?Template=document&Id=4288#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":41228,"voices":140}},{"id":"r02-20200420-9","meetingId":"r02-cm04","date":"2020年4月20日","dateIso":"2020-04-20","committee":"文教委員会","time":"午後 １時００分～午後 ３時０４分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を25件整理しています。","topics":[{"id":"topic-01","title":"令和２年度学級編制","agenda":"令和２年度学級編制","exchanges":[{"speaker":"横山委員","kind":"確認","question":"第二延山小学校の１年生と２年生で色が違うのですけれども、内容はほぼ同じということでよろしいのでしょうか。確認だけお願いします。","respondent":"篠田学務課長","answer":"こちらは国の基準がもともと３５名という中で、そこに教室の関係からはまらなかったという運用になっているということ。２年生に関しましては、国の基準でいけば４０名ですけれども、取り扱いは若干違うということで色分けがされているです。","id":"exchange-001"},{"speaker":"高橋（し）委員","kind":"確認","question":"校長先生のほうから説明されているのかもしれませんが、その辺りの確認です。東京都のほうで手当てをしていただいているのか、それとも区の独自の方なのか、そこだけ確認させてください。","respondent":"篠田学務課長","answer":"要は、お子さんの数が多くなっていることについては必ず言及はされているものというふうに考えております。それから、三木小学校の場合ですけれども、基本的には区の固有教員を充てるという前提で対応をしているものです。","id":"exchange-002"}]},{"id":"topic-02","title":"令和２年度品川区立幼稚園、小・中学校、義務教育学校 園長・校長・副校長異動者名簿","agenda":"令和２年度品川区立幼稚園、小・中学校、義務教育学校 園長・校長・副校長異動者名簿","exchanges":[{"speaker":"高橋（し）委員","kind":"意見","question":"なかなかお尋ねする機会がないので、すみません、年度の初めなので。簡単で結構ですので、お願いしますとの意見を述べました。","respondent":"工藤指導課長","answer":"現在、私どものほうでは、文部科学省への問合せなどを行いながら、法的な根拠も含めまして、調査をしています。調査研究の上、そういう制度については設けるべく検討しています。","id":"exchange-003"},{"speaker":"高橋（し）委員","kind":"意見","question":"そういった条例を設けるべく検討していただけるということなので、区の固有教員の方が校長先生になれる道筋をぜひお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"}]},{"id":"topic-03","title":"新型コロナウイルス感染症の対応","agenda":"新型コロナウイルス感染症の対応","exchanges":[{"speaker":"横山委員","kind":"確認","question":"教育委員会としては個別に対応してくださっていると３月の予算特別委員会でのご答弁がありましたが、現在はどのような対応になっていますでしょうか。毎年実施している家庭訪問の対応についての検討状況はいかがか尋ねました。","respondent":"有馬庶務課長、矢部教育総合支援センター長、篠田学務課長","answer":"１点目の頼れる親がいない児童・生徒への対応です。幸いに、今、そういったときには子ども未来部とも連携をとりながら考えていくというふうに思って… ４点目の個別のお子さんの対応ですけれども、職員がそれぞれ何人か対応して、保護者からの相談を受けているです。気になる子につきましては… いろいろと対応が変わってくるのかなということで、国のＧＩＧＡスクールに対応した形で進めているというものは、今はないです。","id":"exchange-005"},{"speaker":"筒井委員","kind":"質問","question":"結局、大勢のお子さんたちが集まっているものですから、子どもがいくらなんでも公園に集まり過ぎではないかというお声をかなりいただきました。校庭でお子さんたちを遊ばせる、その点、ご見解はいかがか尋ねました。","respondent":"有馬庶務課長","answer":"そのようなところで対応してきましたけれども、今、緊急事態宣言が出ている中で校庭開放をやるというのはなかなか難しいかなと思っています。","id":"exchange-006"},{"speaker":"筒井委員","kind":"質問・要望","question":"ご家庭で過ごしていただきたいという思いがあるのですけれども、それでも、どうしても一部のお子さんたちとかが出られてしまうと思うのです。どうしても公園とかで遊ぶ場合は、啓発していただきたいのですけれども、その点のお考えはいかがか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"縄跳びカードなどを配付していますから、その縄跳びで体力をつける、心の健康も維持しているということを聞いてあります。生活指導上は全体的にマスクの励行ということはとても大切ですので、いろいろな場面で発信していく必要はあると考えています。","id":"exchange-007"},{"speaker":"塚本委員","kind":"質問・要望","question":"そういった活用なども視野に入れながら、検討状況というか、どういうお考えで今後取り組もうとされているのかというところをお聞きしたいのが１点。今どのようなお考えというか、状況なのか、教えていただければというところでお願いいたします。","respondent":"篠田学務課長、矢部教育総合支援センター長","answer":"そういった形で、大体のお子さんはつながるような環境をおもちなのかと、そういったものもご案内しながらやってきているところです。いずれにしても、真剣に取り組んでいく必要があるというふうに感じているところです。少し検討していかなければいけないのですが、１週間前に１つ課題を出して、それを添削するというような活用の効果も上がってあります。","id":"exchange-008"},{"speaker":"のだて委員","kind":"質問・要望","question":"最初に簡単に確認させていただきたいのですが、ほかに区独自で考えたこととか、考慮したことなどがあったら伺いたいと思います。お考えのこととか、なかなか苦慮されているところだと思うのですけれども、そこのところを伺いたいと思います。","respondent":"有馬庶務課長、矢部教育総合支援センター長","answer":"休業の延長の件ですけれども、基本的には、３月末の段階では、まだ学校をやっていけるかどうかというところを検討していた状況がありました。ですので… 常時、２ｍの間隔をとるというのはなかなか難しいということもありまして、学校図書館も併せて閉館しているというような状況ということです。… 我慢という一方で、私は、今できること、家でできることを考えるという意識改革も必要かと思っています。","id":"exchange-009"},{"speaker":"のだて委員","kind":"質問・要望","question":"豊島区でも３月からやっているということですので、品川区でもぜひ実施していただきたいのですが、いかがでしょうか。補償してほしいのですが、いかがか尋ねました。","respondent":"篠田学務課長","answer":"区として、そういったことが対応できるかどうかというのは、なかなか難しい部分はあるのかなというふうに感じているところです。例えば、手続き上の細かな説明も出てきましたので、改めて国に対して申請をしていくというところで考えているところです。","id":"exchange-010"},{"speaker":"のだて委員","kind":"質問・要望","question":"それは確かに重要なのですが、そういったところも含めて、ぜひ支援を考えてほしいと求めました。業者に対して区として何か支援をしていくべきだと思うのですけれども、お考えを伺いたいと思います。","respondent":"篠田学務課長","answer":"出せるかどうかといった観点も含めて検討していかなければいけないのかと考えていますので、何らか対応できるかどうか、今。実際に見込まれた利益に関してどこまで補償するかということになりますと、なかなか教育委員会の立場では難しいものかと考えているところです。","id":"exchange-011"},{"speaker":"のだて委員","kind":"質問・要望","question":"次の質問ですが、今、どうなっていらっしゃるのか。休業されているとすれば、その休業への補償がされているのか、伺いたいと思います。","respondent":"工藤指導課長","answer":"習熟度別学習指導助手は会計年度任用職員ではございませんので、ご指摘いただいているように、勤務するという実態がない場合にお支払いできないです。","id":"exchange-012"},{"speaker":"のだて委員","kind":"質問・要望","question":"そうでない方々が、どういう方が当たるのか、教えてほしいと求めました。そういうことにつながってくると思うので、そういった支援をぜひしていただきたいと思うのですけれども、いかがか尋ねました。","respondent":"工藤指導課長","answer":"ご勤務いただいたりした中で支払うという、通常、またそういった方たちも外出を控えるというふうな対応を同様にしているというところが生じています。国あるいは都からの何らかの指示等、また、何か対応があれば、それは検討していきたいというふうには考えてあります。","id":"exchange-013"},{"speaker":"のだて委員","kind":"質問","question":"そうすると、先ほど例示した介助員とか学習支援員とか、そういった方たちは、みんな会計年度任用職員ということでよろしいのですか。学習支援員もそうだったか、学校司書とか、そういった方たちはどうなっていらっしゃるのか尋ねました。","respondent":"有馬庶務課長","answer":"厚生労働省でそれを補填するという仕組みがあるので、それはその事業者がそちらのほうを通じて補填するという形が、今はとられているというふうに認識しております。","id":"exchange-014"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"勤務なので、その点についての先生方への徹底といいますか、その点についても改めて確認させてほしいと求めました。こういったことをきちんとやられているということは大変すばらしいことだと思うのですが、今のところを伺います。","respondent":"工藤指導課長","answer":"完全に自己研鑽に当たるというよりは、やはり校務として今年度ご自身がなさるようなところを、先々を見通して進めるというところで指示しています。学校によっては、その途中、またそういった記録を残しながら勤務するというのは意識していただくという取組をしています。","id":"exchange-015"},{"speaker":"高橋（し）委員","kind":"確認","question":"勤務の状況をどう確認するかということもお伺いしようと思ったのですが、今、いただきました。先生方の数が多いと、その対応はすごく大変だと思うのですが、そこだけ確認を。","respondent":"工藤指導課長","answer":"そういった意味では、学校は誰がその報告を受けたかという記録をちゃんと残せるような工夫をしているというところがほとんどです。簡単な記録なのですけれども、文書で残すような形で工夫していますので、そういったことで勤務の実態を把握するということで行ってあります。","id":"exchange-016"},{"speaker":"横山委員","kind":"質問・要望","question":"１点だけ。体制、様々なケースを想定しながら対応を検討していただきたいのですが、一言だけお願いします。","respondent":"有馬庶務課長","answer":"ここも大事だと思っていますので、そこはしっかり。学校が再開するにあたっても、できるだけ３密を避けることは徹底して、学校と連携しながらやっていきたいと思います。","id":"exchange-017"},{"speaker":"のだて委員","kind":"質問","question":"今、９０％近くの方が自粛をされているということでしたので、正確に８０何％というものがあれば伺いたいと思います。その後の経過観察といいますか、濃厚接触者の方も含めてどういう状況になっていらっしゃるのか、伺いたいと思います。","respondent":"立木保育課長、崎村子ども育成課長、若生保育支援課長","answer":"利用率ですけれども、本日の登園状況ですと、８８％の方が自粛ということで、１２％の園児が登園しているという状況になってあります。それから… すまいるスクールの利用状況ですが、緊急事態宣言が４月７日に発令されまして、先ほど申し上げたような対応をしたのが４月９日からになります。… ４月１５日までの段階での回答で集計したところ、９日から１９日までの間では８割以上の方が自粛をされているという状況にあります。","id":"exchange-018"},{"speaker":"のだて委員","kind":"質問・要望","question":"医療は続けていかなければいけない、そこはそういったところも含めて考慮してぜひやっていただきたいと思うのですが、いかがでしょうかというところ。いかがか尋ねました。","respondent":"立木保育課長、崎村子ども育成課長","answer":"ただ、これはもしかしたら園のほうでの説明で、きちんと園のほうには説明の仕方を徹底してまいりたいと思います。区長の公印をついたもので出するというような対応をとらせていただくという形で、今、運用をしています。 昨年度の４月の実績を見ますと、１か月、大体１日４,０００人弱が利用しております。それが今回の緊急事態宣言を受けた対応ということで、例年に比べますと１０分の１程度の利用率になっているというところで把握しています。","id":"exchange-019"},{"speaker":"のだて委員","kind":"質問・要望","question":"休園と休業の補償のところで、事業者に対して協力の申し入れをしたということですが、事業者に協力してほしいということで出したということですね。世田谷区でしたか、区でも対応のガイドラインを作っていくべきではないかというふうに思うのですけれども、いかがか尋ねました。","respondent":"立木保育課長","answer":"そういったほかの区の事例等を参考にさせていただきまして、検討してまいりたいと思います。","id":"exchange-020"},{"speaker":"のだて委員","kind":"質問・要望","question":"それだけの単純な要件だけでいいのかというところを確認させてほしいと求めました。そういった相談窓口の設置ですとか、対応はどうされているのか、伺いたいと思います。","respondent":"若生保育支援課長、立木保育課長","answer":"それから２点目の従事者への心のケアですけれども、従来から各事業者の対応の中で、そういったところの対応は行ってきている。今回の新型コロナウイルス感染症の流行の中で… 大分疲労もたまってきておりますし、怖さの中での仕事という部分では、精神的な支えが必要なことも確かです。","id":"exchange-021"},{"speaker":"横山委員","kind":"質問・要望","question":"３点目に、自粛等の働きかけなどを行っていただいたかと思うのですけれども、その依頼後の状況を確認させてください。４点目、お子さんたちの状況の確認について、保育園等ではいかがか尋ねました。","respondent":"崎村子ども家庭支援センター長、立木保育課長、若生保育支援課長","answer":"私からは、１点目のご両親が感染した場合のお子様への対応というところでお答えします。我々の子ども家庭相談の部署である子ども家庭支援センターのほうに… ４月８日に入園式を予定しておりましたけれども、幼稚園に関しては入園式をやるということで、今のところ考えているところです。そういった場合には、適宜… 今後、実施を見合わせるですとか、ゴールデンウィーク明け以降に延期をするというようなことで対応しているというふうな情報を得ているところです。","id":"exchange-022"},{"speaker":"横山委員","kind":"質問・要望","question":"お子さんたちの状況の確認についてだけちょっとお伝えしたいところがあるのです。などということをお話しになれるきっかけにもなるかと思いますので、何か具体的な実現可能な方法でご検討いただけたらというふうに要望いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"筒井委員","kind":"質問","question":"今のケアのお話と関連するかもしれないのですけれども、今、家庭内でのＤＶとか虐待とかが増えているということも聞いておりますが、そうしたご相談とかはあるのか尋ねました。","respondent":"崎村子ども家庭支援センター長","answer":"これは昨年１０月から行われていますけれども、この４月になって、とりわけ件数が著しく増えたというような状況にはございません。子ども家庭支援センターのほうにも、婦人相談、家庭相談の部署におつなぎするといった対応をとっているところです。","id":"exchange-024"},{"speaker":"筒井委員","kind":"質問・要望","question":"そうした事態も考えられますので、そこはしっかりと対応、対策を練っていただきたいと考えております。その点、今後どのような対応というか、対策をお考えなのか、ご見解を伺います。","respondent":"崎村子ども家庭支援センター長","answer":"継続的な支援が必要なケースについても、訪問して確認をする、お話を聞くといった対応をとっていくといったところで考えてあります。子ども家庭支援センターのほうに必ずご連絡くださいといったことで、ここは連携を図りながら対応していくといったところで考えてあります。","id":"exchange-025"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/418457?Template=document&Id=4998#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":34894,"voices":127}},{"id":"r02-20200420-5","meetingId":"r02-cm04","date":"2020年4月20日","dateIso":"2020-04-20","committee":"総務委員会","time":"午後 １時００分～午後 ２時３９分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を29件整理しています。","topics":[{"id":"topic-01","title":"品川区長期基本計画の策定","agenda":"品川区長期基本計画の策定","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"品川区長期基本計画ですけれども、策定時から問題点については指摘をし、変更を求めてまいりました。それは引き続き求めていきたいと思います。","respondent":"佐藤企画調整課長（計画担当課長兼務）","answer":"長期基本計画を踏まえた今後の改定といいますか、社会情勢の反映の状況というご質問だと理解しました。今、また別なものとして、もっと分かりやすく経済対策等を入れたものを作るのかということを内部で検討しています。","id":"exchange-001"},{"speaker":"田中委員","kind":"確認","question":"これはあくまでイメージ図ですよねというのを確認したくて、特に環境学習交流施設については近隣の方と話し合って進めていくと以前伺っているのですが、いかがか尋ねました。","respondent":"佐藤企画調整課長（計画担当課長兼務）","answer":"長期基本計画の本体のほうに描かれている児童相談所や環境学習交流施設の外観ですが、あくまでイメージということで、より分かりやすく捉えていただくために載せているものでございまして、決定ではございません。","id":"exchange-002"},{"speaker":"田中委員","kind":"確認","question":"ちなみに、１０２ページの環境学習交流施設が外観イメージで、７３ページの児童相談所が完成予想図なのですけれども、その違いを確認させてほしいと求めました。","respondent":"佐藤企画調整課長（計画担当課長兼務）","answer":"完成の予想については議会でもご説明しているとおりですが、今後また住民の方とのお話をして進めていく中で、分けているところです。","id":"exchange-003"},{"speaker":"須貝委員","kind":"質問","question":"国の非常事態ではないですか。意見だけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"西本委員","kind":"質問","question":"今後の取り組みで、この長期基本計画の本体はどういう形でお配りするのかということと、概要版はどういう形で使おうとしているのか。せっかくこうやって作っているわけですから、より区民の人たちに理解をしていただいて、その方向性を説明を求めました。","respondent":"佐藤企画調整課長（計画担当課長兼務）","answer":"説明を行う場が持てないというところですが、今後もより皆様に読んでいただけるようにさまざまな工夫をしていきたいと考えています。２点目のご質問の概要版ですが、コンパクトに説明したい場合について、活用していきたいと考えております。","id":"exchange-005"},{"speaker":"西本委員","kind":"質問","question":"なので、せっかくいいものができているわけですから、そういう形で広げていくというのをもう一つ考えていただいてもいいのかなと思います。長期基本計画でなければならないと思いますので、１年かけてもいいぐらいの検討をぜひお願いしたいと思いますが、いかがか尋ねました。","respondent":"佐藤企画調整課長（計画担当課長兼務）","answer":"ワークショップや勉強会等というご提案をいただきました。どういった形ができるのかというのを幅広く考えながら進めていきたいと考えています。","id":"exchange-006"}]},{"id":"topic-02","title":"令和２年度 組織改正","agenda":"令和２年度 組織改正","exchanges":[{"speaker":"田中委員","kind":"質問","question":"これは障害の種類にかかわらず相談できる体制になったということだったと思うのです。これからも変わらず、どんな障害の方でも相談支援を受けられる体制となっているのかということを伺いたいです。","respondent":"佐藤企画調整課長（計画担当課長兼務）","answer":"説明が悪くて申し訳ないですけれども、そういった連携等、組織を立ち上げて検討していくというものです。フレキシブルな対応をしていきながら、障害者施策を進めていくというところで、組織改正をしたところです。","id":"exchange-007"},{"speaker":"田中委員","kind":"質問","question":"どういった放課後サポート担当という係なのかなという、具体的なものがちょっと分からなくて、そこら辺をもう１回教えていただけますか。","respondent":"佐藤企画調整課長（計画担当課長兼務）","answer":"説明が足りなくて申し訳ございません。委員ご指摘のとおり、すまいるスクールを含めて、総合的に放課後サポートをどういった形でやっていけばいいのかという検討をしています。","id":"exchange-008"},{"speaker":"中塚委員","kind":"質問","question":"その狙いは何かを伺いたいと思います。部長まで設置をし、この再開発推進の体制というのは一体何を狙ったものなのか、質問したいと思います。","respondent":"佐藤企画調整課長（計画担当課長兼務）","answer":"品川区組織規則には、再開発等に関わる総合調整に関することを所管業務として明記しています。その動き等もありますので、その辺に関して推進していくといいますか、担っていくです。","id":"exchange-009"},{"speaker":"中塚委員","kind":"質問","question":"こうした開発推進の区政は、私は改めるべきだと思います。狙いだけ、もう一度伺います。","respondent":"佐藤企画調整課長（計画担当課長兼務）","answer":"都市整備推進担当の設置の狙いとまちの動きというご質問だと思いますが、鉄道の立体化等の動きも出てきているというところもありまして、その辺の動きを的確に捉えて円滑に進めていくというところも狙いの１つだと考えております。","id":"exchange-010"},{"speaker":"西本委員","kind":"確認","question":"１点だけ確認させてください。情報収集がかなり必要になってくるのではないかなと思うのですけれども、そういう機能も果たす部署になりますという理解でよろしいか尋ねました。","respondent":"佐藤企画調整課長（計画担当課長兼務）","answer":"当然、庁舎の建て替えにかかわる検討をしますので、情報収集も行っていくというところです。明日の行財政改革特別委員会で、庁舎のあり方に関することが出るところです。","id":"exchange-011"},{"speaker":"西本委員","kind":"質問・要望","question":"もちろん審議会も１つの案という形になるかと思いますけれども、しっかり事務局の中でも、ぜひとも自由な発想でやってほしいと求めました。意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"}]},{"id":"topic-03","title":"(3)新型コロナウイルス感染症の対応","agenda":"(3)新型コロナウイルス感染症の対応","exchanges":[{"speaker":"田中委員","kind":"確認","question":"ホームページを確認したら、ほかの園が噂をされてしまって、休園した保育園の公表については今後どうしていくのかなといったところを伺いたいです。もう１点なのですけれども、それがどこになっているのかというところを確認させてください。","respondent":"立川総務課長","answer":"プレス発表におきまして具体的に保育園名を公表するかしないかですが、メリット・デメリット双方あると認識しています。園名についても公表する必要があるのかなと考えておりますが、保護者１名と、園名については公表を控えするという考えです。","id":"exchange-013"},{"speaker":"田中委員","kind":"質問・要望","question":"ここを開けば出てくるというのは分かるのですけれども、探している方が一目で分かるような記載があるといいなと思うので、そこは要望させてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"中塚委員","kind":"質問・要望","question":"１０万円の給付も１回限りでなく連続して実施することを、品川区として国に要望してほしいと求めましたが、いかがでしょうか。以上、３点について、本部でぜひとも検討してほしいと求めましたが、いかがか尋ねました。","respondent":"立川総務課長","answer":"ただ、東京都に対してのさまざまな要望はこれまでも区長会を通じて実施してきたところですので、そういった東京都からの支援について。さまざま要望等は承っているところではありますので、今後、こういったことについても検討が必要かなと考えているところです。","id":"exchange-015"},{"speaker":"中塚委員","kind":"質問・要望","question":"２３区の区長会で、何を誰に求めているのか、その中身も伺いたいと思います。最後に併せて、職員の在宅勤務について、どういう状況、どのようにやっているのかということを伺いたいです。","respondent":"立川総務課長、榎本総務部長","answer":"地域医療体制の支援についての東京都の支援を充実してほしい、そういった内容について区長会を通して要望したりしています。現在の状況は、まだ始まったばかりということもございまして、３割程度だと聞いているところです。それからＵＳＢも情報推進課が許可した物以外は使えない、そういう扱いになっています。","id":"exchange-016"},{"speaker":"小芝委員","kind":"質問・要望","question":"先般、区の対策として経営相談と経営変化対策資金２０２０の制度が載っていたのですけれども、実際にはそれだけではないと思うのです。そういった方々にも等しく情報を提供してほしいと求めましたが、ご見解を説明を求めました。","respondent":"立川総務課長","answer":"委員ご指摘のとおり、分かりやすさといったところでは課題があるかなと認識しておりますので、もう少し工夫していきたいと思います。これからも分かりやすく掲載していくことが必要かなと考えておりますので、広報広聴課等と連絡をとりまして実施していきたいと考えております。","id":"exchange-017"},{"speaker":"西本委員","kind":"質問・要望","question":"そうなった場合に、庁舎全体としてはどう対応されるのですかということです。保健所は品川区に設置しているわけですから、その対応については何か考えられていることがあるのか、お聞きしたいと思います。","respondent":"立川総務課長","answer":"こちらは東京都と一緒で、土日も夜間９時までですけれども、実施しています。今までは本庁舎の７階で業務をしていたところですけれども、第２庁舎８階の人事課の研修室、そちらに移りまして業務を実施しています。","id":"exchange-018"},{"speaker":"西本委員","kind":"質問・要望","question":"なので、これからの感染者の増え方次第なのでしょうけれども、品川区で適切な対応ができるような仕組みはできるところがあるのではないでしょうか。そういう迷いがないような、交通整理をぜひ区でしてほしいと求めましたが、いかがか尋ねました。","respondent":"立川総務課長","answer":"１点目、相談時間の延長や職員体制につきましては、いただいたご意見を所管に伝えていきたいと考えています。伝えていく必要があるかということは、広報所管とも協議いたしまして、実施してまいりたいと考えているところです。","id":"exchange-019"},{"speaker":"西本委員","kind":"質問","question":"１０万円支給というのがありますが、それは、どこの所管が担当という話がこれから出てくるのか尋ねました。","respondent":"立川総務課長","answer":"現在、検討を進めているところです。","id":"exchange-020"},{"speaker":"須貝委員","kind":"質問・要望","question":"東京都でできないのですかと思うと、フェイスシールドも作れない、エタノールもなかなか間に合わない。品川区も今、事業を進めていると思うのですが、これは結局止まってしまうから、当面、予定は全く立たないということなのか尋ねました。","respondent":"榎本総務部長","answer":"一部工事をストップしている方針の会社はストップしますし、今後、また別の方針を考えていかなければいけないと考えています。工事ができないということで、その辺についても企業側と十分に相談しながら、どういうふうに契約等が進められるかというのは検討しています。","id":"exchange-021"},{"speaker":"大倉委員","kind":"質問・要望","question":"事業の継続が大変でとか、その辺、分かりやすい区民の皆様への周知というところをぜひお願いしたいなと思います。これは意見で、ぜひ取り組んでいただければなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"つる副委員長","kind":"質問・要望","question":"いろいろな要望とか、この所管というところも含めた確認を２点させていただきたいのですけれども、１点確認させてください。","respondent":"立川総務課長","answer":"駅等にラックが設置してありますので、そちらにも置いております。広報広聴課のほうに申し込みいただきますと、直接郵送でお配りできる仕組みもありますので、そういった方法で広報しています。","id":"exchange-023"},{"speaker":"つる副委員長","kind":"質問・要望","question":"これは要望にしたいと思います。もう１個が、どうしてしまったのだ、なぜかお叱りの声をいただくのです。","respondent":"立川総務課長","answer":"総務課のほうで１日３回やるとか、皆さんに聞いていただける放送が大事かなと考えておりますので、協力して行っていく考えです。","id":"exchange-024"}]},{"id":"topic-04","title":"人権に関わる意識調査結果","agenda":"人権に関わる意識調査結果","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"１人の人が何回もできるようにしてはいけないわけであって、どういう対策か、ご説明ほしいと求めました。どういうふうに対策されているかということと、これ自身は必要な取組みだと考えていますので、今後も工夫してみてほしいと求めました。","respondent":"島袋人権啓発課長","answer":"インターネットで回答する場合のあなたの番号というものを付けておりまして、それをホームページ上で入力すると、その人のページに入っていくと。委員おっしゃるとおり、ダブりがないかの確認はとれておりまして、今回はダブりはなかったという報告です。","id":"exchange-025"},{"speaker":"田中委員","kind":"質問・要望","question":"各所管、関わりのあるところでは、このアンケート結果がきちんと活かされるようになるのかというところをまず確認させていただきたいのと。４ページの「子どもの人権が守られていないと思う場合」の部分、どうしても親による子どもの虐待など、ここについても何かあればお願いします。","respondent":"島袋人権啓発課長","answer":"アンケート結果が他課との連携の事業で活かされるのかということですが、こちらに関しては、活かしていくように私たちも働きかけていく予定です。やはり状況もさまざま変化しておりますので、これからは設問状況を見直してまいりたいと考えているところです。","id":"exchange-026"},{"speaker":"田中委員","kind":"質問","question":"性的マイノリティの部分です。質問がどういったものになれば当事者の方たちも納得できる質問になるかといったことを聞いてもらって、作り上げていただければなと思います。","respondent":"島袋人権啓発課長","answer":"今回初めて開く予定でおります「みんなのひろば」というところですが、１人ではなく、区政に活かしてまいりたいと考えているところです。","id":"exchange-027"},{"speaker":"西本委員","kind":"質問","question":"例えばこれは用語の説明はされているのでしょうか。そこの調整はどう考えられていますか。","respondent":"島袋人権啓発課長","answer":"本編の報告書のほうにはさまざまな用語解説、あるいは送らせていただいた回答用紙にも簡単な用語説明は付けて渡させていただいたところです。教育の中で学びたい部分という回答も多くいただいておりますので、今後、法律に基づきましてさまざまなことをお聞きしたという次第です。","id":"exchange-028"},{"speaker":"西本委員","kind":"意見","question":"ただ、ここで分かることは、認知度を上げるという広報がいかに大切かということかなと思うのです。言葉の意味合い、今後、ご検討いただければなという意見で終わりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-029"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/346628?Template=document&Id=2164#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":29349,"voices":94}},{"id":"r02-20200421-14","meetingId":"r02-cm04","date":"2020年4月21日","dateIso":"2020-04-21","committee":"行財政改革特別委員会","time":"午後 １時００分～午後 １時５８分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を30件整理しています。","topics":[{"id":"topic-01","title":"特定事件調査の(1)庁舎のあり方に関すること","agenda":"特定事件調査の(1)庁舎のあり方に関すること","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"前回１２月の当委員会で示されたような様々な分野でのプロジェクトチームの検討、先行自治体の事例研究、当委員会には報告がないのでしょうか。伺いたいと思います。","respondent":"濱中庁舎計画担当課長","answer":"庁内検討ＰＴについてご質問いただきました。５月末に一定の検討案を取りまとめるよう依頼していたところですが、現状、６月末に検討案をまとめていこうということで進めているところです。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"それですと、当委員会への報告というのは、次回も難しいということなのか、伺いたいと思います。それと、もし今の段階で報告できる範囲でありましたら、どんな検討になっているのかというのを教えてほしいと求めました。","respondent":"濱中庁舎計画担当課長","answer":"庁内検討ＰＴの進捗をお尋ねいただいたところですが、６月とＰＴをやって固めていくところですので、お示しできる段階ではないのかなと考えております。","id":"exchange-002"},{"speaker":"安藤委員","kind":"意見","question":"５月２０日に行財政改革特別委員会が予定されておりますが、適切に議会にも、庁内での検討内容というのをご報告いただく必要があると思うのです。そこら辺を、ぜひよろしくお願いしたいと思いますとの意見を述べました。","respondent":"濱中庁舎計画担当課長","answer":"６月末で庁内ＰＴの検討案がまとまり次第、そちらから様々なタイミングのところで皆様方に説明する、今はまだ検討案を。","id":"exchange-003"},{"speaker":"おくの委員","kind":"質問・要望","question":"委員に加えていただきたいということを要望として申し上げたように覚えているのですけれども、この中で、この７団体だけではないと思うのです。障害に応じた様々な条件なり要望なりがあると思うので、せっかくこの先５０年を見込んで庁舎の機能を検討していく以上、いかがか尋ねました。","respondent":"濱中庁舎計画担当課長","answer":"福祉団体、３団体の方に入っていただきまして、その中に障害者七団体協議会の代表者の方も入っていただく。庁内検討ＰＴの中には、そういった中で、そちらにつきましても庁舎機能検討委員会で議論していただく予定ではあります。","id":"exchange-004"},{"speaker":"おくの委員","kind":"質問・要望","question":"１０年のことではなくて、５０年をにらんで建てるようなことですから、私は思うのです。そこのところをもう少しお考えになって、このメンバーに反映していただきたいと思うのですが、ご再考願うわけにはいかないのか尋ねました。","respondent":"榎本総務部長","answer":"庁内で何回か検討を重ねておりまして、福祉関係は２団体だけだったのですが、障害者七団体協議会を加えさせていただいたところです。庁舎機能検討委員会というレベルですと、それはまた、どういうやり方がいいのかというのは考えていかなければいけないのかなと思っています。","id":"exchange-005"},{"speaker":"こんの委員","kind":"確認","question":"１点、確認なのですが、区民公募の締切が１か月先に延期をされた。それとも、１か月遅れても余裕のあるスケジュールを組んでいたのか、このスケジュールはどのように組まれたものなのか尋ねました。","respondent":"濱中庁舎計画担当課長","answer":"５月に第１回を想定していたところですが、１か月程度、後ろ倒しにしたところです。それに伴いまして、公募区民の募集も１か月程度、後ろ倒しにして、幅広い区民の方にご応募いただく機会を設けたです。","id":"exchange-006"},{"speaker":"こんの委員","kind":"質問","question":"そこはどうなのでしょうか。大丈夫なのか尋ねました。","respondent":"濱中庁舎計画担当課長","answer":"当初、５月を第１回に、最後の第５回を２月に想定しておりましたので、全体スケジュールを１か月後ろ倒しにして、今の段階では収まるものと見ております。","id":"exchange-007"},{"speaker":"こんの委員","kind":"質問","question":"分かりました。本当に６月が行われるかどうかというところも、たとえ延びてでも、その辺りのお考えはどうなのか尋ねました。","respondent":"榎本総務部長","answer":"ちょうどこの庁舎機能検討委員会というのがスタートの第１歩目になりますので、将来の設計とか、議論は十分し尽くしたいと思っています。例えば６月が開催できないとなれば、全体のスケジュール感を考えなければいけないかなと、現時点では思っています。","id":"exchange-008"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"１２月の行財政改革特別委員会での区からの資料でも、求められる庁舎機能というところでは、さらに広げた専門家が必要なのではないかと感じました。バリアフリー、ご意見を言ってくれる専門家を増やしていってほしいと思うのですけれども、いかがか尋ねました。","respondent":"濱中庁舎計画担当課長","answer":"ご提案いただきました学識経験者の人数ですが、庁舎機能検討委員会ではこちら３名の方を挙げさせていただいておりまして、次の基本構想を策定する段階におきましては、専門的な手法をもった方々の参加を検討してまいります。","id":"exchange-009"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"５０年先を見込んだ庁舎、ぜひ幅広い専門家の皆さんの意見を入れた形で進めていただきたいと、改めて要望したいのです。今後の多様性だったり、検討委員会にこの視点を入れていっていただきたいと思うのですけれども、いかがか尋ねました。","respondent":"濱中庁舎計画担当課長、榎本総務部長","answer":"１点目、専門家のことに関しましては、基本構想の策定段階で、庁舎機能検討委員会の取りまとめをもとに議論をしていきたいと考えています。ジェンダーの視点ですが、各団体に推薦依頼をかけているところではありますが、男女比率は今… 補足ですけれども、検討委員会とか、男女共同参画のための品川区行動計画の中では４割という目標とさせていただいています。いろいろな検討委員会で、計画上は４割となっていますので、それを目指していきたいと思います。","id":"exchange-010"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"公募区民５名とあって、もっと増やしていただきたいという思いはあるのですが、公募時期も５月１４日が締切と延びたということです。当初、４月１６日締切ということで進めていたと思うのですけれども、分かれば教えてほしいと求めました。","respondent":"濱中庁舎計画担当課長","answer":"公募区民の応募状況ですが、５名を超える応募があるといったところです。","id":"exchange-011"},{"speaker":"石田（ち）委員","kind":"質問","question":"何人ぐらいかというのは分からないということなのか、そこを伺いたいです。いろいろ公表できないと区はおっしゃっているのですが、そうすると、この部分は公表されることになっていたということでいいか尋ねました。","respondent":"濱中庁舎計画担当課長","answer":"公募区民ですが、５名程度を超えるところで、今現在１０名程度ございまして、申込書配付のみのご連絡をしています。検討報告書ですが、こちらは所管ではないので、お答えを控えさせていただければと思います。","id":"exchange-012"},{"speaker":"石田（ち）委員","kind":"質問","question":"ですので、それが参考になるのは当然だと思うのです。そうしてくると、しっかり税金をかけて検討したものが、ここでも出されてくるということでしょうか、ということです。","respondent":"濱中庁舎計画担当課長","answer":"庁舎機能検討委員会ですが、そちらには現状の課題等を整理しまして、お示ししていくところと考えています。","id":"exchange-013"},{"speaker":"石田（ち）委員","kind":"質問","question":"それが出されるのは当然なのですけれども、既に検討してきた報告書には現庁舎の課題と新庁舎の基本条件というのが、黒塗りですけれども出ているわけですから、それが出されるということですか、ということです。","respondent":"榎本総務部長","answer":"まずは準備段階でいろいろ検討した中で、まだそこまでの段階ではないという形なので、私も中身は存じているものではありません。この庁舎機能検討委員会の中では、そこの機能検討からがスタートで、積み上げていきたいと考えているものです。","id":"exchange-014"},{"speaker":"石田（ち）委員","kind":"意見","question":"分かりました。あり方というのは、引き続き十分議論していきたいと、私も期待したいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"},{"speaker":"安藤委員","kind":"質問・要望","question":"今、ましてや求められる庁舎機能のところにユニバーサルデザイン等も入っているわけですから、改めて意見として申し上げたいと思います。この１年間の間にやって、その内容をこの庁舎機能検討委員会の材料にすべきだと私は思うのですけれども、伺います。","respondent":"濱中庁舎計画担当課長","answer":"区民意見の聴取ですが、庁舎機能検討委員会で区民意見の具体的な聴取方法や時期を検討していくことになると想定しております。他自治体の事例や、検討支援業務委託事業者のノウハウ等を活用しながら、区民意見の聴取方法を検討してまいりたいと思います。","id":"exchange-016"},{"speaker":"安藤委員","kind":"質問","question":"私としては、わざわざ集まってもらうわけですから、早くアンケートをやってほしいと考えています。再三、今のＤ案の前提なのだと言っていましたけれども、ＪＲとの交渉の現況はどうなっているかというのを伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"安藤委員","kind":"質問","question":"知らないのですか。知っていれば教えてほしい。","respondent":"濱中庁舎計画担当課長","answer":"こちらにつきましては所管外ですので、答えられないところです。","id":"exchange-018"},{"speaker":"安藤委員","kind":"意見","question":"区が進めようという検討の前提条件なわけです。所管外だからといって、何かつかんでいるかどうかもお答えがなければおかしいと思うので、そこら辺だけ答えてくださいとの意見を述べました。","respondent":"榎本総務部長","answer":"まだ協議が続いている最中ですので、その協議の結果については、まだ所管からの報告を受けていないという段階です。","id":"exchange-019"},{"speaker":"安藤委員","kind":"確認","question":"先ほど、部長の答弁の中でも、そういうものだという感じもあったように聞こえたのですけれども、そこを確認したいのです。今のＤ案というのを前提にした議論を行う場所なのかどうか、伺います。","respondent":"榎本総務部長","answer":"ただ、機能としての検討なので、広町地区よりももっといい候補地が出てくるのであれば、その候補地を前提に考えるということも、一つの案だと。そういった意味では、費用的には、今まで所有していた土地を有効に活用できるという利点があると考えております。","id":"exchange-020"},{"speaker":"安藤委員","kind":"質問・要望","question":"別の話ですから、区の新庁舎として、どこまで使うのか。これを前提にして議論をするべきではない、これはやめるよう求めたいのですけれども、改めていかがか尋ねました。","respondent":"榎本総務部長","answer":"そうすると、なかなか庁舎の改築の検討自体が進まなくなってしまうのかなと思うのですけれども。実際に庁舎の改築にはかなりの期間がかかるわけですから、その準備としては着手していかなければいけないのかなと考えています。","id":"exchange-021"},{"speaker":"安藤委員","kind":"質問・要望","question":"５０年、１００年という建物ですから、私はあることだと思います。ぜひそのことを受け止めて、検討を進めていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"須貝委員","kind":"質問・要望","question":"これから検討していこうということですから、何も始まりませんので、私は粛々とやってほしいと求めました。意見だけ言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"}]},{"id":"topic-02","title":"区有施設・公有地等活用に関すること","agenda":"区有施設・公有地等活用に関すること","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"時期はいつ頃なのかとか、これは事業説明会が行われて、設計する前にこういうことを行うという理解でよろしいですか。伺いたいと思います。","respondent":"佐藤企画調整課長","answer":"１点目の今後の住民説明会ですが、今後どういう見込みになるか分からないのですが、現時点の予定では６月以降を目指していると聞いております。２点目の前回の住民説明会ですが、説明内容に関しましては、どういった施設になるかという概要をご説明したところです。","id":"exchange-024"},{"speaker":"安藤委員","kind":"質問・要望","question":"説明会でも地域の方から要望を出されていたということですが、ニュースという形でもいいので、どうなったのかを知らせてほしいという声が出ています。細心の注意を払って対策を取っていただきたいと要望しますけれども、何かあれば、こちらもご答弁お願いします。","respondent":"佐藤企画調整課長","answer":"住民説明会でも出ておりますので、そちらに関しましては、基準に則って適切に対応するということも回答しています。説明してから時間が経っているところですので、地域の方々に適切に情報を流すため、所管課を通じて対応していきたいと思います。","id":"exchange-025"}]},{"id":"topic-03","title":"特定事件調査のまとめ","agenda":"特定事件調査のまとめ","exchanges":[{"speaker":"大沢委員","kind":"意見","question":"区組織と関連団体に関することと同様に、この件についても賛成し、そのほかの修正点もないと考えますので、この案文でお願いしたいと思います。賛成ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-026"},{"speaker":"おくの委員","kind":"質問・要望","question":"その点に関して私は質問して、区としても要望を出しているし、やはりホーム柵について取組をさらに促進していくことを打ち上げていると。私からはその修正をお願いしたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"石田（ち）委員","kind":"意見","question":"(1)の１行目で「『鉄道駅バリアフリーに関する優先整備の考え方』に基づき、エレベーターを強調したかっただけなのです。意見はそれだけですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-028"},{"speaker":"あくつ委員","kind":"質問","question":"今の石田ちひろ委員の意見なのですけれども、新馬場駅の南口等を想定されているということだと思うのですが、例えば、「エレベーターなどもワンルートだけではなく」とか、そういうことではないのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"あくつ委員","kind":"質問","question":"エレベーターだけではないということですか。１本のエレベーターでなくて２本造ってもという、エレベーターを造ってという意味ではないのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/988746?Template=document&Id=6086#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":16904,"voices":93}},{"id":"r02-20200422-18","meetingId":"r02-cm04","date":"2020年4月22日","dateIso":"2020-04-22","committee":"オリンピック・パラリンピック推進特別委員会","time":"午後 １時００分～午後 １時１３分","status":"正式会議録","sourceType":"formal","overview":"オリンピック・パラリンピック推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を1件整理しています。","topics":[{"id":"topic-01","title":"東京２０２０大会の延期","agenda":"東京２０２０大会の延期","exchanges":[{"speaker":"つる委員","kind":"確認","question":"保育園等の年長から高校３年生までということが最初でしたけれども、来年の年の年長からという考え、この辺は既に何か確認されていることがあれば説明を求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"学校連携プログラムについての対象者ですが、今のところまだ東京都等から連絡は入っておりません。通常考えると、今の年中が上がったところなのかと思いますが、詳しいところはまだ来ておりませんので、これからの対応です。","id":"exchange-001"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/312568?Template=document&Id=6572#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=18&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":4115,"voices":27}},{"id":"r02-20200428-10","meetingId":"r02-cm04","date":"2020年4月28日","dateIso":"2020-04-28","committee":"議会運営委員会","time":"午後 １時００分～午後 １時３１分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/101132?Template=document&Id=5356#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":10705,"voices":58}},{"id":"r02-20200511-10","meetingId":"r02-cm05","date":"2020年5月11日","dateIso":"2020-05-11","committee":"議会運営委員会","time":"午前１０時３０分～午前１０時４１分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を1件整理しています。","topics":[{"id":"topic-01","title":"本会議・委員会の運営","agenda":"本会議・委員会の運営","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"本会議場の傍聴者の人数が２０名ということですけれども、今で７０名か６０名くらいいたと思いますけれども、意見だけ述べておきたいと思います。それともう１点、今、５点にわたって説明がありましたが、文書で後ほどというか配ってほしいと求めましたので、御対応。","respondent":"米田区議会事務局長","answer":"今、議長のほうから御発言ありましたことが間違いなく各議員に伝わるように、文書もしくはメモ等で各会派のほうにきちんと周知をさせていただきたいと思います。","id":"exchange-001"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/101132?Template=document&Id=5358#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":4269,"voices":21}},{"id":"r02-20200512-6","meetingId":"r02-cm05","date":"2020年5月12日","dateIso":"2020-05-12","committee":"区民委員会","time":"午前１０時１１分～午前１１時２６分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を34件整理しています。","topics":[{"id":"topic-01","title":"第３３号議案 品川区中小企業事業資金融資あつ旋条例の一部を改正する条例","agenda":"第３３号議案 品川区中小企業事業資金融資あつ旋条例の一部を改正する条例","exchanges":[{"speaker":"おくの委員","kind":"質問・要望","question":"３点にわたって対象者の範囲が拡大されておりまして、私も要望してまいりましたので、非常に評価はいたしたいと思います。お願いいたします。","respondent":"遠藤商業・ものづくり課長","answer":"５年で５００万円の貸付をさせていただいているのですが、いわゆる通常の状態に戻るのがなかなか時間がかかるだろうというような見込みがあります。２０人以下に限らず、ある程度柔軟に対応できればというところで、改正させていただいたところです。","id":"exchange-001"},{"speaker":"おくの委員","kind":"意見","question":"その最初の２つのことは今ご説明いただきましたので、その３つ目の売り上げ減少、これを条件にしなくなった、これも画期的なことだと思うのですよ。重要なことだと思うので、その点について、さらにご説明ほしいと求めました。","respondent":"遠藤商業・ものづくり課長","answer":"例えば４月の時点ですと１月、２月、３月というものが対象になるかと思います。今回、５％以上減少というのを廃止させていただきまして、積極的に融資するというところです。","id":"exchange-002"},{"speaker":"おくの委員","kind":"質問・要望","question":"今、理由を伺いまして、やはりとても重要な改正だと思います。それからもう１つ、これは念のための質問ですけれども、もちろんないですよね。","respondent":"遠藤商業・ものづくり課長","answer":"こちら、区の単独の事業になっておりますので、特別補助金等はついていないというところです。","id":"exchange-003"},{"speaker":"おくの委員","kind":"質問","question":"件数や何かを少しお伺いしたいのですけれども、さらに申し込んでから融資までにかかった期間が今どうなっているかということを伺いたいと思います。前の委員会で報告があったと思いますけれども、これもそうなのですけれども、４号認定や５号認定の認定までの期間、件数と期間も伺いたいと思います。","respondent":"遠藤商業・ものづくり課長","answer":"あさっての木曜日にもまだ空きがあるような状況ですので、２日、３日いただければご案内できるかなというところです。銀行では２、３週間というのが引き続きかかっているというような形で聞いております。","id":"exchange-004"},{"speaker":"藤原委員","kind":"質問","question":"だけれども今回はこれが外れるわけですから、それと、４年目以降が０.２ではないですか。今回、このコロナという特別な事態であるわけですから、ずっと無利子という形にはできないのかというのが質問です。","respondent":"遠藤商業・ものづくり課長","answer":"前回、雇用の関係などで配らせていただいた、それをもう一度行おうかというところで検討させていただいているところです。０.２％、私どもで大体１.４％ぐらいは引き続き負担する形になっておりますので、そこの部分についてはご理解いただければというところです。","id":"exchange-005"},{"speaker":"藤原委員","kind":"質問・要望","question":"いい施策をしていくわけですから、絶対に情報弱者をつくってはいけないと思うのですね。ですから、情報弱者をつくらないようにしていくということを教えていただきたいのと、区は税金でというのはわかっています。","respondent":"遠藤商業・ものづくり課長","answer":"周知につきましては、できるだけ全員に、わからないという方がないように周知させていきたいと考えています。引き続き要する費用の全額を私どものほうで対応するという部分で行わせていただいておりますので、４年目以降、ご負担いただければと考えております。","id":"exchange-006"},{"speaker":"湯澤委員","kind":"質問","question":"経営変化対策資金２０２０で改正の中で、３６カ月に延ばしていただいたり、大変すばらしいことだと考えています。その窓口に相談が大変殺到しているとお聞きしている中で、資金がある人との差というか、その辺はどういうふうに捉えているのかと。","respondent":"遠藤商業・ものづくり課長","answer":"ずっと対応させていただきまして、先ほど言ったおおよそ２日間いただければ、かなりのところでできているのかなというふうに思っております。","id":"exchange-007"},{"speaker":"湯澤委員","kind":"質問・要望","question":"確認をさせていただきたいのですけれども、改正が決定したときには、その方たちにも適用されるのか。ぜひしてほしいと思いますし、例えば１,５００万円借りたいとか、そういうことも可能なのかというのを説明を求めました。","respondent":"遠藤商業・ものづくり課長","answer":"それを戻すというのは、銀行との中で１回なしにしてという部分では、それで５００万円を増やすなりという部分では可能かと考えています。","id":"exchange-008"},{"speaker":"湯澤委員","kind":"質問","question":"そうすると、ごめんなさい。今、手続き中の方は難しいということか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"後戻りできる部分なのか、もう終わってしまっている部分なのかというところで、多分銀行によって少し違うのかなというふうに考えております。","id":"exchange-009"},{"speaker":"くにば委員","kind":"質問・要望","question":"何点か伺いたいのですけれども、今回、売り上げ上昇の見込みが難しい事業者ということについて伺いたいのですね。そちらについてご答弁いただきたいのが１点と、こちらは２,０００万円に達するまでは、何度でも融資申し込みができるかどうか。","respondent":"遠藤商業・ものづくり課長","answer":"保証協会がきちんと対応、指導するなりという形で行われていますので、そこの部分で十分対応できるかなと。税金の部分がありますので、そこはきちんと分けて、ですので、当然、個人貸付にはならないような形のもので対応させていただいているところです。","id":"exchange-010"},{"speaker":"くにば委員","kind":"質問","question":"１点目なのですけれども、ご答弁の中で、結局、緩和、審査が緩和されたかどうかという部分について、今ひとつ聞きとれなかったので伺いたいのと、あとは、３点目の個人事業主についてなのですが、開業届を出していない方は対象にならないという認識でよろしいのか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"一定程度、これは会社のお金、個人のお金は含まれないような形で行っているかと思います。結局、先ほどの保証協会等もありますので、そういう部分ではきちんと分けられているのかなというふうに感じているところです。","id":"exchange-011"},{"speaker":"くにば委員","kind":"意見","question":"お金を借り入れても、もう事業をするのが難しいのではないかと、そういったところで心が折れて廃業なさっている方々がもうたくさんいらっしゃいます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"},{"speaker":"こんの副委員長","kind":"質問","question":"その上で、こういうふうに改正をしてくださるということで、大変にありがたいことであります。ここを計算すると１,０８８件、この辺の数字の現状を１つお聞きしたいのと、その辺のところをお聞きしたいと思います。","respondent":"遠藤商業・ものづくり課長","answer":"要件の緩和等によって、新たな方がいらっしゃるのかなというところですけれども、当初は５００万円で足りていたという方が多分多かったのかなと。とりあえず１回は、それが出てきて、またこちらの部分でお使いいただく方も増えてくるのかなというふうには思っているところです。","id":"exchange-013"},{"speaker":"こんの副委員長","kind":"質問・要望","question":"この４月、この５００万円まで借りられなかった人たちが、助かる部分もかなり出てくるのかなと。窓口の対応をさらに強化していく、あるいは対応をこのように工夫していくということが何かあれば、お答えほしいと求めました。","respondent":"遠藤商業・ものづくり課長","answer":"支援メニューというのは幾つか、そういう部分をご説明しながら、いろいろな支援がありますので。","id":"exchange-014"},{"speaker":"こんの副委員長","kind":"質問","question":"最後に、５月から郵送受付をされるということで、もう既にこれが始まっているという理解でよろしいのでしょうか。それが１点と、３密も避けられるしというところで、その辺の郵送受付の流れみたいなものを少しご説明いただけますか。","respondent":"遠藤商業・ものづくり課長","answer":"郵送のほうは５月に入ってから受付を開始させていただきまして、大体、今、１日４０件ぐらいが届いているような状況です。とにかくスピード第一という形でさせていただきまして、リスクができるだけ少ないような形で行わせていただければというふうに思っております。","id":"exchange-015"}]},{"id":"topic-02","title":"第３２号議案 令和２年度品川区一般会計補正予算（歳出 区民委員会所管分）","agenda":"第３２号議案 令和２年度品川区一般会計補正予算（歳出 区民委員会所管分）","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"報道もされていたのですけれども、窓口が混んでいるというのは、報道どおりマイナンバーの暗証番号を忘れてということでよろしいのでしょうか。いろいろやりようがないのかという問い合わせを今朝も受けたのですけれども、その辺がどうなっているのか、伺えればと思います。","respondent":"木村戸籍住民課長","answer":"主には、途中でエラーになってしまったとかいう形で、それの対応が本庁舎でないとできないというところで集中してしまっているところがあります。","id":"exchange-016"},{"speaker":"おくの委員","kind":"質問","question":"窓口へ行って手続きをとる以外に手段がないから、今の状態になっている。だけれども、今、改善策を考えているところだという理解でよろしいわけか尋ねました。","respondent":"木村戸籍住民課長","answer":"１日の処理ができる件数であるとか、処理をする端末の台数を増やすであるとか、人も含めてですね。そこは福祉計画課のほうとも連携を図りまして、お客様にとってどちらが速く着金をするのかというあたりも含めて広報を図ってまいりたいと思います。","id":"exchange-017"},{"speaker":"おくの委員","kind":"質問","question":"それで、商業・ものづくり課長にお伺いしたいのですけれども、先ほど、融資あっ旋の実態ということで件数をお伺いしましたけれども、今度、新たに出てきた雇用調整助成金のほうですけれども、これの相談件数、それから、やはり相談までの期間と申請数をお伺いしたいと思います。","respondent":"遠藤商業・ものづくり課長","answer":"私どもでしています社会保険労務士の無料相談窓口、４月から開始させていただきましたが、そちらの件数が現在１６０件を予約で受けているところです。５月２０日、２１日ぐらいに空きがあるような状況でして、４月１５日から開始して１６０件というような状況です。","id":"exchange-018"},{"speaker":"おくの委員","kind":"質問","question":"３７万５,０００円ということなのですけれども、全部で９８商店街ということなのですけれども、それぞれ幾つ商店街があるのですか。１００店舗以上の商店街、５０から９９店舗、４９店舗以下という商店街というのは。","respondent":"遠藤商業・ものづくり課長","answer":"今回の予算計上をさせていただいたところにつきましては、１００店舗以上が１０商店街、それから、５０から９９店舗の商店街が６０、残りの４９店舗以下が２８商店街という形で算出しています。","id":"exchange-019"},{"speaker":"おくの委員","kind":"質問","question":"どういう基準で計算して、こういう支援額になったのか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"９９店舗以下のところにつきましては、さらにうちのほうで５,０００円を上乗せして、それぞれ１万５,０００円という形になっております。ですので、４９店舗以下のところに対しては１万５,０００円というような算出で、今回計上させていただいたところです。","id":"exchange-020"},{"speaker":"おくの委員","kind":"意見","question":"そうしますと、１００店舗以上のところは東京都から出ることを勘案して行ったと。でも、１００店舗以上のところは、都から出る協力金も勘案しながら額を決めたという、そういう理解でよろしいわけですねとの意見を述べました。","respondent":"遠藤商業・ものづくり課長","answer":"１００店舗以上のところについては都のほうから別のメニューがあるというところがありますので、９９店舗以下は少し手厚くさせていただいたというところです。","id":"exchange-021"},{"speaker":"おくの委員","kind":"質問・要望","question":"あるいは、商店街の方から、どういうことに使いたいからという要望があったのでしょうか。その辺、どういう使いみちを想定して出されたのかということをお伺いしたいと思います。","respondent":"遠藤商業・ものづくり課長","answer":"このメニューを考えるときに、こちらにつきましては、商店街によってかなりばらつきがあろうかと思います。支援金を出するところですので、一定、商店街のほうにお任せするということで考えております。","id":"exchange-022"},{"speaker":"おくの委員","kind":"質問・要望","question":"もし、商店街の方から具体的な要望が、これを決める前にあったのなら、例えばということでお教え願えればありがたいのですけれども、その点はいかがか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"どのような形でもいいから支援いただけないかというところで、させていただければというところで、ご要望には応えられたのかなというふうに思っているところです。","id":"exchange-023"},{"speaker":"おくの委員","kind":"質問・要望","question":"私がつい最近伺った小売業の方も、４分の１に減っているのだというおそばやさんから伺ったり、クリーニング店でももう客が半分以下に減った。特に、テレワークの進展で、特にワイシャツやスーツのクリーニングが減ったのだというお声を伺ったりもしました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"おくの委員","kind":"意見","question":"さらに、他方で、自粛、本当に行ってほしいと。戸越銀座にお住まいの高齢の方からも、かなり頼まれたのですよとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-025"},{"speaker":"おくの委員","kind":"質問・要望","question":"ほしいという、自粛してほしいということを頼まれましたので、もうなっているのではないでしょうかね。ですから、それを改めて求めたいと思いますけれども、いかがか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"あるいは休業要請を出した都道府県という形が、まずは一義的に行うものかなというふうに私は考えております。限られているところがありますので、区としてどのような支援ができるか、できることは行わせていただきたいということで進めてまいります。","id":"exchange-026"},{"speaker":"おくの委員","kind":"質問","question":"品川区で区独自に、こういう固定費の補助、そういうことを工夫していく余地はあるのではないでしょうか。区独自の制度を、品川区でまだ踏み出していないのはなぜなのか、その点をお伺いしたいと思います。","respondent":"遠藤商業・ものづくり課長","answer":"これによって、区のほうの負担も、大体５００万円ですと２０万円ぐらい、融資を受けた方への、いわゆる助成に近いような形になろうかと思います。そういった部分で、いろいろな支援の方法はあろうかと思いますので、いろいろ研究してまいりたいというふうに思います。","id":"exchange-027"},{"speaker":"おくの委員","kind":"質問","question":"１,０００億円のため込み金もあるのですから、何のためこみ金かということに、やはりなるのだと思うのです。これだけの工夫をしてきたのですから、さらに工夫、ほんとうにお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"松澤委員","kind":"質問","question":"そういった、この助成金に対するメーンと言いますか、というのはどういうところなのか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"雇用環境整備事業の、まず、ハードウエアをなかなか手当てしていただけないというようなところを聞いております。うちのほうで持たせていただくというところが、今、比較的簡易に申請していただけるというところがメリットなのかなというふうに思っております。","id":"exchange-029"},{"speaker":"松澤委員","kind":"意見","question":"１件ですね。社労士、そういった、見つからない可能性があったときの対処法などが何かあったらお願いしますとの意見を述べました。","respondent":"遠藤商業・ものづくり課長","answer":"この後、現在、休業されている方も多いので、申請も多分、それで少し後ろにずれているのかなというふうに感じているところです。できるだけこちらのほうに協力して、あっ旋などもしていただけるような形で、要望を出させていただいている形です。","id":"exchange-030"},{"speaker":"湯澤委員","kind":"質問","question":"１００件という目安を示されているのですけれども、これが１００件ぐらいなのかなというふうに思われた、どういった経緯でなのかと。それからもう１つが、こちらの会員店ということだと思うのですが、賛助会員などの場合もそこに含まれるのかというのを教えてほしいと求めました。","respondent":"遠藤商業・ものづくり課長","answer":"現在１００件、２００件以上になった場合どうするかということなのですけれども、申請があれば受け付けたいというふうには考えているところです。要するに、実際にコロナの対策という形で考えておりますので、含めても構わないのかなというふうに思っております。","id":"exchange-031"},{"speaker":"湯澤委員","kind":"質問・要望","question":"どうしても早く、早くとスピードを求められるところもあると思いますので、スピード感を持った対応をしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"くにば委員","kind":"質問","question":"２点伺いたいのですけれども、こちらの商店街の対策支援金のほうなのですけれども、先ほどおっしゃって、ご答弁なさっていた予算金額６，５６０万円、その内訳をもう一度伺いたいのですけれども、よろしいか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"６,５６０万円の内訳です。４９店舗以下のところが３７万５,０００円掛ける２８商店街で１,０５０万円、１０万円ほど計上させていただいて、合計額という形になっております。","id":"exchange-033"},{"speaker":"くにば委員","kind":"質問","question":"伺いたいのが、伺いたいのが、伺います。","respondent":"遠藤商業・ものづくり課長","answer":"申請の段階で、一定、こんなことをやりますというのを書いていただくような形で考えておりますので、そちらを書いていただければ、後で確認などはしないで、その場でもうすぐに支給するという形で考えております。","id":"exchange-034"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/297302?Template=document&Id=2866#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":26248,"voices":110}}]);
